local config = {
  ui_story_5038_50380001_1_dialog_content = "進來。",
  ui_story_5038_50380001_2_dialog_content = "四！",
  ui_story_5038_50380001_3_dialog_content = "呼哇，塔塔沒來晚吧！",
  ui_story_5038_50380001_4_dialog_content = "怎麼氣喘吁吁的，塔塔，路上很趕嗎？",
  ui_story_5038_50380001_5_dialog_content = "剛才在送信，收信人聽不懂塔塔縮滴話，不願意簽收。",
  ui_story_5038_50380001_6_dialog_content = "怎莫會這樣呢，塔塔一直在練習通用語呀。",
  ui_story_5038_50380001_7_dialog_content = "哈哈，真是辛苦妳了，在外鄉打工很費力吧？",
  ui_story_5038_50380001_8_dialog_content = "小問題啦，難不倒塔塔滴！",
  ui_story_5038_50380001_9_dialog_content = "塔塔有耽誤納努塞爾姐姐滴四情嗎？",
  ui_story_5038_50380001_10_dialog_content = "沒有沒有，我今天不趕時間。",
  ui_story_5038_50380001_11_dialog_content = "不如說，妳的時間更寶貴一些……",
  ui_story_5038_50380001_12_dialog_content = "欸？森莫意思？",
  ui_story_5038_50380001_13_dialog_content = "派給妳的新一批信件包裹到了，這裡是清單，妳確認一下。",
  ui_story_5038_50380001_14_dialog_content = "<size=50>欸？！！三十封？！！</size>",
  ui_story_5038_50380001_15_dialog_content = "正面是加急信件，翻到背面還有五十封一般信件。",
  ui_story_5038_50380001_16_dialog_content = "還有？！！",
  ui_story_5038_50380001_17_dialog_content = "怎、怎莫一下子這麼多……",
  ui_story_5038_50380001_18_dialog_content = "塔塔手裡還有一些沒送完呢……",
  ui_story_5038_50380001_19_dialog_content = "送信也分淡季和旺季，現在正好趕上了繁忙的時候。",
  ui_story_5038_50380001_20_dialog_content = "而且，影鎮那邊似乎碰到了一些突發狀況呢……",
  ui_story_5038_50380001_21_dialog_content = "妳看看這些包裹的簽收地址吧，塔塔。",
  ui_story_5038_50380001_22_dialog_content = "唔，我看看啊……",
  ui_story_5038_50380001_23_dialog_content = "咦，則些包裹全都四從影鎮送往——<color=#FFB400>雙榭城？</color>",
  ui_story_5038_50380001_24_dialog_content = "是的，一批加急貨物突然從影鎮發往了雙榭城的各處。",
  ui_story_5038_50380001_25_dialog_content = "這些訂單催得急，未來這兩天妳可能會很辛苦哦。",
  ui_story_5038_50380001_26_dialog_content = "哇，雙榭城是森莫地方？在哪裡？我還從來沒有去過！",
  ui_story_5038_50380001_27_dialog_content = "呵呵，那就趁這個機會好好去瞧一瞧吧。",
  ui_story_5038_50380001_28_dialog_content = "這個時節正是參觀雙榭城的好時候。",
  ui_story_5038_50380001_29_dialog_content = "好！辣偶現在就要幹勁滿滿地出 · 發 · 啦！",
  ui_story_5038_50380001_30_dialog_content = "<color=#e8d9bb>五天後</color>",
  ui_story_5038_50380001_31_dialog_content = "<size=50>嗚哇哇哇哇哇——</size>",
  ui_story_5038_50380001_32_dialog_content = "<size=50>PlayerName！救救偶！</size>",
  ui_story_5038_50380001_33_dialog_content = "欸，塔塔？妳怎麼了！",
  ui_story_5038_50380001_34_dialog_content = "發生什麼事了？",
  ui_story_5038_50380001_35_dialog_content = "偶滴信件和包裹要送不完了！",
  ui_story_5038_50380001_36_dialog_content = "別著急，坐下來慢慢說。",
  ui_story_5038_50380001_37_dialog_content = "四這樣滴，最近影鎮委託信使公會，幫忙運送大量的<color=#FFB400>紅色彩紙</color>。",
  ui_story_5038_50380001_38_dialog_content = "因為需求量很多，又要得很急，所以偶這幾天一直在加班派送……",
  ui_story_5038_50380001_39_dialog_content = "可就算四這樣，也快到偶滴極限了……",
  ui_story_5038_50380001_40_dialog_content = "偶努力了五天，也就送完了一部分，可是……",
  ui_story_5038_50380001_41_dialog_content = "離最緊急的送達時間只剩一天了！",
  ui_story_5038_50380001_42_dialog_content = "延遲派送的後果很嚴重嗎？",
  ui_story_5038_50380001_43_dialog_content = "後果、後果會變成，塔塔給大家拖了後腿、被信使公會開促……",
  ui_story_5038_50380001_44_dialog_content = "然後沒有錢花、呲不起飯、沒地方足……",
  ui_story_5038_50380001_45_dialog_content = "然後就要回雲山劈柴了哇！",
  ui_story_5038_50380001_46_dialog_content = "這麼嚴重？！",
  ui_story_5038_50380001_47_dialog_content = "所以……塔塔這次來，是想拜託PlayerName先森幫個忙。",
  ui_story_5038_50380001_48_dialog_content = "塔塔想，雇傭臨空者號送偶一程。",
  ui_story_5038_50380001_49_dialog_content = "塔塔會付傭金滴！等這個月滴薪水發了，全都給你！",
  ui_story_5038_50380001_50_dialog_content = "傭金不重要啦，能幫上塔塔的忙就好。",
  ui_story_5038_50380001_51_dialog_content = "既然時間緊急，我們現在就出發吧！",
  ui_story_5038_50380001_52_dialog_content = "所以妳的目的地是？",
  ui_story_5038_50380001_53_dialog_content = "四一座港口城四，它叫「雙榭城」。",
  ui_story_5038_50380001_54_dialog_content = "哦，這麼說的話，臨空者號的下方，正是金河流域。",
  ui_story_5038_50380001_55_dialog_content = "順著金河一直往下游走，等看到海的時候，就到雙榭城了。",
  ui_story_5038_50380001_56_dialog_content = "咦？！卡蓮妳……去過那裡？",
  ui_story_5038_50380001_57_dialog_content = "沒有，我只是在白夜城的圖書館裡看到過。",
  ui_story_5038_50380001_58_dialog_content = "它坐落在金河出海口上，文化風格又與別處迥異，時常會被各種書籍提到。",
  ui_story_5038_50380001_59_dialog_content = "說起來，它的起源可能會讓你感到熟悉。",
  ui_story_5038_50380001_60_dialog_content = "哦？",
  ui_story_5038_50380001_61_dialog_content = "是<color=#FFB400>林家商會</color>建起了這座城市。",
  ui_story_5038_50380001_62_dialog_content = "林家商會？！他們不是在影鎮嗎？",
  ui_story_5038_50380001_63_dialog_content = "影鎮是他們進行商業貿易的地方，而雙榭城是他們在艾斯特拉大陸的落腳點。",
  ui_story_5038_50380001_64_dialog_content = "你還記得吧，林家商會來自遙遠東方的另一片大陸。",
  ui_story_5038_50380001_65_dialog_content = "在他們出現之前，金河的出海口只有些貧窮的小漁村。",
  ui_story_5038_50380001_66_dialog_content = "直到有一天，巨大的船停泊在那裡，林家商會的部分人口來到艾斯特拉。",
  ui_story_5038_50380001_67_dialog_content = "他們把遙遠東方的貨物從船上卸下，再沿著金河一路運往影鎮。",
  ui_story_5038_50380001_68_dialog_content = "他們需要雇傭工人，需要住宿、吃飯，原本的漁民們紛紛有了新的工作。",
  ui_story_5038_50380001_69_dialog_content = "這些林家商會的人賺到了錢，也帶著這座港口一起變得富裕。",
  ui_story_5038_50380001_70_dialog_content = "原住民們接受了來自東方的文化，照著龍洲大陸的樣子修建起了一座城市。",
  ui_story_5038_50380001_71_dialog_content = "逐漸形成了從林家而來的新住民與原住民共同生活的景象。",
  ui_story_5038_50380001_72_dialog_content = "這就是我們要去的地方——雙榭城。",
  ui_story_5038_50380001_73_dialog_content = "哇，商人建立起的城市，我還是第一次見呢。",
  ui_story_5038_50380001_74_dialog_content = "會、會不會消費很高啊，我們的存款不算多哦。",
  ui_story_5038_50380001_75_dialog_content = "聽說富人住的地方，停車都是要收費的。那臨空者號豈不是……",
  ui_story_5038_50380001_76_dialog_content = "唔，收費問題倒是不用擔心，但是為了不引起不必要的麻煩——",
  ui_story_5038_50380001_77_dialog_content = "PlayerName，請把臨空者號停在城外吧。",
  ui_story_5038_50380001_78_dialog_content = "說的也是。",
  ui_story_5038_50380001_79_dialog_content = "快看，我們好像要到了！",
  ui_story_5038_50380001_80_dialog_content = "哇，好漂亮的街道！",
  ui_story_5038_50380001_81_dialog_content = "對吧？到醋都四紅色滴，好膩害！",
  ui_story_5038_50380001_82_dialog_content = "是啊，看起來有一種喜氣洋洋的感覺。",
  ui_story_5038_50380001_83_dialog_content = "嗯，按照書上的記載，這完全是另一片大陸的風格。",
  ui_story_5038_50380001_84_dialog_content = "在大洋彼岸，房子、街道應該都是這副模樣。",
  ui_story_5038_50380001_85_dialog_content = "隔著一片大海，他們就像生活在另一個完全不同的世界。",
  ui_story_5038_50380001_86_dialog_content = "而且而且，他們還會過完全不同的節日哦！",
  ui_story_5038_50380001_87_dialog_content = "偶這兩天送的紅色彩紙，好像就是他們的傳統節日必備用品。",
  ui_story_5038_50380001_88_dialog_content = "這個傳統節日叫……叫……？",
  ui_story_5038_50380001_89_dialog_content = "過年好啊，你們是來過春朔節的？",
  ui_story_5038_50380001_90_dialog_content = "對！就叫「春朔節」！",
  ui_story_5038_50380001_91_dialog_content = "雙榭城這半年幾乎沒有陌生面孔過來，你們是外鄉人吧？",
  ui_story_5038_50380001_92_dialog_content = "光看你們的衣服就看出來了。",
  ui_story_5038_50380001_93_dialog_content = "先森，您出來得正好，這是您店鋪訂的紅色彩紙，喏！請簽收！",
  ui_story_5038_50380001_94_dialog_content = "哦，謝謝你啊，我還以為年前拿不到了！",
  ui_story_5038_50380001_95_dialog_content = "可以請問一下，為什麼你們要從影鎮訂購這麼多紅色的紙嗎？",
  ui_story_5038_50380001_96_dialog_content = "說這個啊，這畢竟是營造過年氣氛的重要道具嘛。",
  ui_story_5038_50380001_97_dialog_content = "龍洲那邊的春朔節傳統，就是用紅色彩紙謄寫對聯和「福」字，貼在門上。",
  ui_story_5038_50380001_98_dialog_content = "以祈求未來這一年吉祥、順心！",
  ui_story_5038_50380001_99_dialog_content = "「龍洲」——這就是那座東方大陸的名字嗎？",
  ui_story_5038_50380001_100_dialog_content = "沒錯，看來你們是第一次聽說啊。",
  ui_story_5038_50380001_101_dialog_content = "我們這些居住在雙榭城的居民，向來都是自給自足，所以也很少跟內陸往來。",
  ui_story_5038_50380001_102_dialog_content = "這些紅色彩紙，本來也都是可以在我們雙榭城的商舖買到的。",
  ui_story_5038_50380001_103_dialog_content = "不過……今年確實出了一點狀況。",
  ui_story_5038_50380001_104_dialog_content = "狀況？發生了什麼事嗎？",
  ui_story_5038_50380001_105_dialog_content = "我們這些商舖最近全面斷貨了，不要說彩紙，連過年的年貨都快買不到了。",
  ui_story_5038_50380001_106_dialog_content = "怎麼會這麼困難……連配給都沒有嗎？",
  ui_story_5038_50380001_107_dialog_content = "一般來說，林家商會的<color=#FFB400>遠航商船</color>，每個季度都會從龍洲駛來這裡。",
  ui_story_5038_50380001_108_dialog_content = "但是這半年不知道是出了什麼問題，林家的商船再也沒有來過。",
  ui_story_5038_50380001_109_dialog_content = "那些原本依靠商船往來而進購貨品的店鋪，逐漸快要支撐不下去了。",
  ui_story_5038_50380001_110_dialog_content = "這其中，也包括紅彩紙在內。所以我們才不得不捨近求遠從影鎮那邊訂購。",
  ui_story_5038_50380001_111_dialog_content = "（原來是這樣，還真是讓人有些擔心……）",
  ui_story_5038_50380001_112_dialog_content = "（我也算是受過林家商會的幫助，不知道他們近況怎樣了。）",
  ui_story_5038_50380001_113_dialog_content = "唔……偶明白這種感受哦，先森一定也很想念家鄉的味道吧。",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>嘟——嘟——</color>",
  ui_story_5038_50380001_115_dialog_content = "咦，什麼聲音？",
  ui_story_5038_50380001_116_dialog_content = "港口那邊的方向好像有喇叭聲……",
  ui_story_5038_50380001_117_dialog_content = "這……是船笛！",
  ui_story_5038_50380001_118_dialog_content = "沒有錯，就是港口的船笛啊！",
  ui_story_5038_50380001_119_dialog_content = "港口有船了！難道是林家的船開過來了！",
  ui_story_5038_50380001_120_dialog_content = "林家的商船？",
  ui_story_5038_50380001_121_dialog_content = "PlayerName，我們來得好像正是時候。",
  ui_story_5038_50380001_122_dialog_content = "是商船，真的是林家開過來的商船！",
  ui_story_5038_50380001_123_dialog_content = "太好了，我還以為今年的年貨買不到了！",
  ui_story_5038_50380001_124_dialog_content = "開艙了，有人走下來了！",
  ui_story_5038_50380001_125_dialog_content = "……",
  ui_story_5038_50380001_126_dialog_content = "（那邊有一個奇怪的男人，看起來好像一點都不興奮。）",
  ui_story_5038_50380001_127_dialog_content = "讓一讓讓一讓，關愛一下老弱病殘啦各位！",
  ui_story_5038_50380001_128_dialog_content = "這位小哥，你擋住仲胥老哥的輪子啦。",
  ui_story_5038_50380001_129_dialog_content = "原、原來他坐著的東西是……輪椅？！",
  ui_story_5038_50380001_130_dialog_content = "抱、抱歉，失禮了！",
  ui_story_5038_50380001_131_dialog_content = "無妨。我說多少次了厘青老弟，不必用這四個字稱呼我……",
  ui_story_5038_50380001_132_dialog_content = "我還沒死，我能自理。",
  ui_story_5038_50380001_133_dialog_content = "哈哈哈哈，我、我這不是想快速通過嘛！",
  ui_story_5038_50380001_134_dialog_content = "我已經等不及要採購龍洲特產的上好藥材了！",
  ui_story_5038_50380001_135_dialog_content = "讓一下，讓我先過去，我都帶好白夜幣了！",
  ui_story_5038_50380001_136_dialog_content = "往前走一走啊，前面的！",
  ui_story_5038_50380001_137_dialog_content = "嗚哇？不、不要擠啊！",
  ui_story_5038_50380001_138_dialog_content = "請諸位肅靜。",
  ui_story_5038_50380001_139_dialog_content = "……",
  ui_story_5038_50380001_140_dialog_content = "蜃風號當真是煥然一新，連領航的船長也是新面孔。",
  ui_story_5038_50380001_141_dialog_content = "我是林家商船「蜃風」的新船長，月白。",
  ui_story_5038_50380001_142_dialog_content = "……看來這裡確實有不少認得這艘船的林家人啊。",
  ui_story_5038_50380001_143_dialog_content = "半年前，身在龍洲大陸的林家家主略有變故，導致林家無法派船出海。",
  ui_story_5038_50380001_144_dialog_content = "這半年，龍洲與艾斯特拉大陸之間的航路阻斷，想必各位同胞也飽受懷鄉之苦。",
  ui_story_5038_50380001_145_dialog_content = "但是，那些都已經過去了，從我踏上這裡的這一刻起——",
  ui_story_5038_50380001_146_dialog_content = "從龍洲到艾斯特拉的航線，已經<color=#FFB400>順利恢復</color>。",
  ui_story_5038_50380001_147_dialog_content = "……仲胥老哥，他們真的順利把船開到這裡了！",
  ui_story_5038_50380001_148_dialog_content = "我們好像可以回去啦！",
  ui_story_5038_50380001_149_dialog_content = "……",
  ui_story_5038_50380001_150_dialog_content = "突然一下又可以回龍洲了？但我還沒做好計畫……",
  ui_story_5038_50380001_151_dialog_content = "是啊，我已經提前跟生意夥伴約了許多酒局，難以脫身啊……",
  ui_story_5038_50380001_152_dialog_content = "諸位如果想要隨船返回龍洲，只需要買好船票即可。",
  ui_story_5038_50380001_153_dialog_content = "不過，由於往返的航線出現了變數，也請諸位知悉其中的<color=#FFB400>危險性</color>。",
  ui_story_5038_50380001_154_dialog_content = "不管啦，林家的海船向來非常靠譜，給我來三張票！",
  ui_story_5038_50380001_155_dialog_content = "那，給我也先來一張！省得到時候都搶空了……",
  ui_story_5038_50380001_156_dialog_content = "諸位同胞不要急、不要慌～",
  ui_story_5038_50380001_157_dialog_content = "距離蜃風號的返航，還有好些時日呢！",
  ui_story_5038_50380001_158_dialog_content = "在下剛從蜃風號下來，就覺得此地的百姓都很不俗。",
  ui_story_5038_50380001_159_dialog_content = "不知是否有貴人願意讓在下為其占卜，順便為在下指路呢？",
  ui_story_5038_50380001_160_dialog_content = "李天閑這個江湖騙子又想騙人了……",
  ui_story_5038_50380001_161_dialog_content = "丹棠殿下，在下可不是騙子啊。",
  ui_story_5038_50380001_162_dialog_content = "……殿下小心！",
  ui_story_5038_50380001_163_dialog_content = "噢噢噢噢噢噢噢——",
  ui_story_5038_50380001_164_dialog_content = "蜃風號好像比先前更華麗了！",
  ui_story_5038_50380001_165_dialog_content = "而且還更寬敞了……",
  ui_story_5038_50380001_166_dialog_content = "咳咳咳……阿玖姑娘的反應還真是快啊……",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>嘰嘰喳喳……嘰嘰喳喳……</color>",
  ui_story_5038_50380001_168_dialog_content = "呃……嗚……",
  ui_story_5038_50380001_169_dialog_content = "塔塔，你怎麼了？",
  ui_story_5038_50380001_170_dialog_content = "偶、偶也想去蜃風號上看一看……",
  ui_story_5038_50380001_171_dialog_content = "上面應該也會有偶想要看到滴東西……",
  ui_story_5038_50380001_172_dialog_content = "妳是想要找這個嗎，小信使？",
  ui_story_5038_50380001_173_dialog_content = "哇——一大摞一大摞滴紅彩紙！",
  ui_story_5038_50380001_174_dialog_content = "對！塔塔就是想要這個！",
  ui_story_5038_50380001_175_dialog_content = "我出發前就已經聽說了，年末在即，雙榭城的年貨很不充裕，連彩紙都沒有。",
  ui_story_5038_50380001_176_dialog_content = "少不了要向內陸的商會進貨，還要請一堆小信使們奔走派送。",
  ui_story_5038_50380001_177_dialog_content = "現在紅彩紙已經從龍洲運來了，妳往後也不用再這麼辛苦了。",
  ui_story_5038_50380001_178_dialog_content = "<size=50>好耶——偶放假啦！！！</size>",
  ui_story_5038_50380001_179_dialog_content = "塔塔終於從工作中解放了呢。",
  ui_story_5038_50380001_180_dialog_content = "你們三個，是艾斯特拉大陸內陸的居民吧？",
  ui_story_5038_50380001_181_dialog_content = "——光看衣服就可以看出來了，對吧？",
  ui_story_5038_50380001_182_dialog_content = "呵呵，那就請你們多多關照了。",
  ui_story_5038_50380001_183_dialog_content = "蜃風號還要在艾斯特拉大陸這邊停泊一段時間。",
  ui_story_5038_50380001_184_dialog_content = "在這段時間裡，就讓我們好好相處吧。",
  ui_story_5038_50380001_185_dialog_content = "（哇……面無表情英姿颯爽的大姐姐！）",
  ui_story_5038_50380001_186_dialog_content = "好、好的，我的名字叫PlayerName……",
  ui_story_5038_50380001_187_dialog_content = "歡迎來到艾斯特拉大陸，龍洲的客人！",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>雙榭城街道</color>",
  ui_story_5038_50380101_2_dialog_content = "（在這段時間裡，我們一直在雙榭城內享受著難得的閒暇時光……）",
  ui_story_5038_50380101_3_dialog_content = "（春朔節將至的雙榭城，真是一個讓人放鬆身心的地方啊。）",
  ui_story_5038_50380101_4_dialog_content = "發什麼呆呢，PlayerName？",
  ui_story_5038_50380101_5_dialog_content = "我在想，不知不覺，竟然都數不清已經在這裡玩了幾天了。",
  ui_story_5038_50380101_6_dialog_content = "不，我這邊有精確的日程紀錄。",
  ui_story_5038_50380101_7_dialog_content = "我看看，PlayerName前三天在和李天閑逛東方特色小吃街……",
  ui_story_5038_50380101_8_dialog_content = "第四到六天在和我們參與雙榭城對弈遊戲……",
  ui_story_5038_50380101_9_dialog_content = "第六到十天，在丹棠舉辦的新春書法大賽上慘敗……",
  ui_story_5038_50380101_10_dialog_content = "第十到十五……",
  ui_story_5038_50380101_11_dialog_content = "好、好了……我知道了！",
  ui_story_5038_50380101_12_dialog_content = "總之，我們也差不多可以計劃著時間離開了。",
  ui_story_5038_50380101_13_dialog_content = "PlayerName自己是可以慢慢考慮啦……但我明天就該回啟光了哦。",
  ui_story_5038_50380101_14_dialog_content = "哎？！這麼快！",
  ui_story_5038_50380101_15_dialog_content = "畢竟在這個時候，啟光也要開啟冬季的特殊補給通道了。",
  ui_story_5038_50380101_16_dialog_content = "我要回去為物資配給的工作幫忙啦～",
  ui_story_5038_50380101_17_dialog_content = "按照慣例，我也是時候回去，和伯利恆陛下一起度過北境新年了。",
  ui_story_5038_50380101_18_dialog_content = "速度夠快的話，從北境來的馬車今晚就會趕到這裡。",
  ui_story_5038_50380101_19_dialog_content = "連卡蓮也？！",
  ui_story_5038_50380101_20_dialog_content = "好吧，再見了，我的假期……",
  ui_story_5038_50380101_21_dialog_content = "哇？！看看塔塔發現了誰！",
  ui_story_5038_50380101_22_dialog_content = "PlayerName先森、薇絲姐姐、卡蓮姐姐早啊！",
  ui_story_5038_50380101_23_dialog_content = "哦，塔塔！早安啊！",
  ui_story_5038_50380101_24_dialog_content = "妳的工作怎麼樣了，還忙嗎？",
  ui_story_5038_50380101_25_dialog_content = "不用擔心，偶滴工作節奏已經回歸正軌了！",
  ui_story_5038_50380101_26_dialog_content = "眼下，只剩一封信沒有送出呢！",
  ui_story_5038_50380101_27_dialog_content = "哦？還需要我們幫忙嗎，明天之前我還有空哦～",
  ui_story_5038_50380101_28_dialog_content = "謝謝薇絲姐姐，這次塔塔自己就可以送，而且……",
  ui_story_5038_50380101_29_dialog_content = "偶已經買好蜃風號滴<color=#FFB400>船票</color>嘍！",
  ui_story_5038_50380101_30_dialog_content = "總之，這次偶拿到滴是一封越洋信件，目的地是海那邊滴龍洲大陸！",
  ui_story_5038_50380101_31_dialog_content = "偶這幾天特意把其他信件提前送完了，就是為了能夠按時上船！",
  ui_story_5038_50380101_32_dialog_content = "這也算是一次不錯的旅行機會啊。",
  ui_story_5038_50380101_33_dialog_content = "嘿嘿，偶也已經迫不及待了～",
  ui_story_5038_50380101_34_dialog_content = "這兩天街上的人也在議論紛紛，似乎也都是為了蜃風號即將啟程的事。",
  ui_story_5038_50380101_35_dialog_content = "嗯，大家會感到擔心是理所當然的囉。",
  ui_story_5038_50380101_36_dialog_content = "我可是知道林家航線斷航半年的<color=#FFB400>內幕</color>哦！",
  ui_story_5038_50380101_37_dialog_content = "你……你四誰啊？",
  ui_story_5038_50380101_38_dialog_content = "哦，想起來了，你四那天熱心幫助輪椅大叔的哥哥！",
  ui_story_5038_50380101_39_dialog_content = "哈哈！我那不叫「熱心幫助」啦，仲胥是我的朋友，同時也是我的患者。",
  ui_story_5038_50380101_40_dialog_content = "我們是之前一起乘著林家的船從龍洲大陸過來的。",
  ui_story_5038_50380101_41_dialog_content = "我叫厘青，是個到處治病救人的「赤腳貓醫生」。",
  ui_story_5038_50380101_42_dialog_content = "喵嗚——",
  ui_story_5038_50380101_43_dialog_content = "嘰？！！",
  ui_story_5038_50380101_44_dialog_content = "則、則則則則……則裡有貓哇！",
  ui_story_5038_50380101_45_dialog_content = "噓……小尾巴，不要搗亂！對、對不起啊，牠不是故意的！",
  ui_story_5038_50380101_46_dialog_content = "小尾巴，來，到我這邊來。",
  ui_story_5038_50380101_47_dialog_content = "牠果然還是更喜歡待在我這裡。",
  ui_story_5038_50380101_48_dialog_content = "牠只是喜歡你身邊的這群貓吧……",
  ui_story_5038_50380101_49_dialog_content = "打擾，我來確認一下登船乘客的資訊。",
  ui_story_5038_50380101_50_dialog_content = "在場諸位，塔塔、仲胥、厘青，確認要跟隨此次返程航線前往龍洲，沒錯吧？",
  ui_story_5038_50380101_51_dialog_content = "沒錯。",
  ui_story_5038_50380101_52_dialog_content = "好的，在出發之前，我還有幾句話要交代。",
  ui_story_5038_50380101_53_dialog_content = "二位龍洲人一定聽說過林家「海航法寶」的傳聞。",
  ui_story_5038_50380101_54_dialog_content = "林家此前也確實是依靠著這樣一個東西，才在海外航行裡處於不敗之地。",
  ui_story_5038_50380101_55_dialog_content = "可現如今，這個獨一無二的法寶已經遺失了，至今還沒有找到。",
  ui_story_5038_50380101_56_dialog_content = "之前我也提到了，請諸位務必知悉此行的危險性。",
  ui_story_5038_50380101_57_dialog_content = "沒有了法寶，意味著我們沒有可以依憑的經驗，此行是一場對航路的探索。",
  ui_story_5038_50380101_58_dialog_content = "來時路上風調雨順，蜃風號順利抵達了這裡。",
  ui_story_5038_50380101_59_dialog_content = "但我不能保證返航的路程能夠同樣順利，我要保證每個乘客都知曉這件事。",
  ui_story_5038_50380101_60_dialog_content = "如果沒有必要的緊急事件，我還是<color=#FFB400>不建議</color>你們登上蜃風號。",
  ui_story_5038_50380101_61_dialog_content = "（這就是林家半年前的變故之一嗎……）",
  ui_story_5038_50380101_62_dialog_content = "偶、偶不害怕！偶相信月白姐姐的能力！",
  ui_story_5038_50380101_63_dialog_content = "呵呵，妳的膽子很大啊。",
  ui_story_5038_50380101_64_dialog_content = "該說是巧合還是怎樣呢，在我挨家挨戶做這種宣告的時候……",
  ui_story_5038_50380101_65_dialog_content = "買過船票的乘客，無一例外全都退票了。",
  ui_story_5038_50380101_66_dialog_content = "有的說因為要留下來照顧家庭，有的說是因為臨時計畫有變。",
  ui_story_5038_50380101_67_dialog_content = "想來也是沒有人願意真的拿自己的生命冒險吧。",
  ui_story_5038_50380101_68_dialog_content = "可是話說回來，月白姐姐就是在「用生命冒險」啊！",
  ui_story_5038_50380101_69_dialog_content = "……我相信我自己可以處理好這些。而且，這就是我的職責所在。",
  ui_story_5038_50380101_70_dialog_content = "看起來妳也並沒有十足的信心啊。",
  ui_story_5038_50380101_71_dialog_content = "妳對<color=#FFB400>「羅盤」</color>的下落不好奇嗎？",
  ui_story_5038_50380101_72_dialog_content = "？！",
  ui_story_5038_50380101_73_dialog_content = "你是林家人？還是……",
  ui_story_5038_50380101_74_dialog_content = "船長姐姐，不要緊張，我們是半年前<color=#FFB400>那場事件</color>的親歷者。",
  ui_story_5038_50380101_75_dialog_content = "不可能……據我所知，沒有人從賊船的手中活下來……",
  ui_story_5038_50380101_76_dialog_content = "你不知道，那些賊船才能更不知道啊～",
  ui_story_5038_50380101_77_dialog_content = "而且，沒有沉入海裡的，可不只有我和仲胥老哥。",
  ui_story_5038_50380101_78_dialog_content = "您是仲胥大人？",
  ui_story_5038_50380101_79_dialog_content = "正是鄙人。",
  ui_story_5038_50380101_80_dialog_content = "家主對您的安危很是掛念，若是知道您還活著，他一定很高興。",
  ui_story_5038_50380101_81_dialog_content = "呵呵，看來他也從他們手中成功脫身了。",
  ui_story_5038_50380101_82_dialog_content = "妳是一名很有膽量的船長，我很敬佩妳恢復航線的勇氣。",
  ui_story_5038_50380101_83_dialog_content = "除了來雙榭城通商之外，妳的身上一定還有尋找「羅盤」的使命吧。",
  ui_story_5038_50380101_84_dialog_content = "……沒錯。",
  ui_story_5038_50380101_85_dialog_content = "如果你們執意要登船，就請助我一臂之力吧。",
  ui_story_5038_50380101_86_dialog_content = "那是當然，上船再細說吧，不能一直把內陸的客人們晾在這裡。",
  ui_story_5038_50380101_87_dialog_content = "是、是在說我們吧？其實不用在意我們來著……",
  ui_story_5038_50380101_88_dialog_content = "總之，啟程的時間是兩日後，到時候我們在港口見吧。",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>兩日後</color>",
  ui_story_5038_50380101_90_dialog_content = "哇？這不是PlayerName嗎！",
  ui_story_5038_50380101_91_dialog_content = "你是來和我們道別的嗎？",
  ui_story_5038_50380101_92_dialog_content = "嗯，卡蓮和薇絲已經離開雙榭城了，他們託我一定要把話帶給你們。",
  ui_story_5038_50380101_93_dialog_content = "「希望你們的航行一切順利，並再來艾斯特拉大陸做客」。",
  ui_story_5038_50380101_94_dialog_content = "這些話其實也是我想說的。",
  ui_story_5038_50380101_95_dialog_content = "雖然我們認識的時間不長，但一想到要說再見，還有點捨不得。",
  ui_story_5038_50380101_96_dialog_content = "呵呵，艾斯特拉大陸人的表達方式還真是坦率呢。",
  ui_story_5038_50380101_97_dialog_content = "丹棠殿下也要試著說一說嗎？",
  ui_story_5038_50380101_98_dialog_content = "唔……我，我也會……",
  ui_story_5038_50380101_99_dialog_content = "我也會記住PlayerName公子的。",
  ui_story_5038_50380101_100_dialog_content = "仲胥老哥和李天閑已經登船了，我們也差不多該走啦。",
  ui_story_5038_50380101_101_dialog_content = "話說回來，怎麼不見那天那個白色小山雀啊？",
  ui_story_5038_50380101_102_dialog_content = "……是啊，我還想送一送塔塔呢。",
  ui_story_5038_50380101_103_dialog_content = "<size=50>嗚哇哇哇哇哇——</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerName！救救偶！</size>",
  ui_story_5038_50380101_105_dialog_content = "啊！塔塔，你總算來了！",
  ui_story_5038_50380101_106_dialog_content = "偶滴信件和包裹要送不完了！",
  ui_story_5038_50380101_107_dialog_content = "偶突然接到了一個發往北境的加急信件！信使公會其他人也協調不開了！",
  ui_story_5038_50380101_108_dialog_content = "北境天寒地凍，道路隱蔽，也只有偶熟悉送信的路！",
  ui_story_5038_50380101_109_dialog_content = "所以……難道是要……",
  ui_story_5038_50380101_110_dialog_content = "所以……塔塔這次來，是想拜託PlayerName先森幫個忙。",
  ui_story_5038_50380101_111_dialog_content = "塔塔想，雇傭PlayerName先森替偶去龍洲一程。",
  ui_story_5038_50380101_112_dialog_content = "塔塔會付傭金滴！等下個月滴薪水發了，全都給你！",
  ui_story_5038_50380101_113_dialog_content = "（怎麼感覺這個對話似曾相識……）",
  ui_story_5038_50380101_114_dialog_content = "我、我倒是很想幫妳，可傭金不是重點吧！",
  ui_story_5038_50380101_115_dialog_content = "關鍵是，我可以用妳的船票登船嗎？",
  ui_story_5038_50380101_116_dialog_content = "出了什麼狀況？",
  ui_story_5038_50380101_117_dialog_content = "月白姐姐——！",
  ui_story_5038_50380101_118_dialog_content = "唔……嗯……好的，我明白了。",
  ui_story_5038_50380101_119_dialog_content = "按理來說，這種頂替乘客的事情是不允許發生的。",
  ui_story_5038_50380101_120_dialog_content = "嗚……這樣啊……",
  ui_story_5038_50380101_121_dialog_content = "那偶就去拜託其他有船票的人幫偶送信吧……",
  ui_story_5038_50380101_122_dialog_content = "不過——PlayerName，我想以船長的身分，邀請你跟我們同行。",
  ui_story_5038_50380101_123_dialog_content = "咦？！為什麼這麼突然……",
  ui_story_5038_50380101_124_dialog_content = "應該說，這是仲胥大人的意思。",
  ui_story_5038_50380101_125_dialog_content = "我從兩天前的談話裡，才突然重新堅定了找「羅盤」的決心。",
  ui_story_5038_50380101_126_dialog_content = "仲胥大人說，如果有你這個空裔的幫助，也許會讓這件事變得更加順利。",
  ui_story_5038_50380101_127_dialog_content = "（順利……？難道……我的感應能力還能感應這種東西嗎？）",
  ui_story_5038_50380101_128_dialog_content = "在此次返程的過程中，我們已經擁有了來時的經驗。",
  ui_story_5038_50380101_129_dialog_content = "同時還有親歷過「羅盤」失蹤的仲胥先生、厘青作陪。",
  ui_story_5038_50380101_130_dialog_content = "丹棠殿下、阿玖和李天閑，也會用他們的能力盡量保護船上的一切。",
  ui_story_5038_50380101_131_dialog_content = "如果你能信任我來掌舵，就請幫幫我吧。",
  ui_story_5038_50380101_132_dialog_content = "（從前，林家商會還跟我有過幾次往來，我也結識過林家的朋友……）",
  ui_story_5038_50380101_133_dialog_content = "（如果這次可以能多多少少幫到他們的話……）",
  ui_story_5038_50380101_134_option_content = "我答應妳！",
  ui_story_5038_50380101_135_dialog_content = "感謝你的慷慨施援，我在上面等你，PlayerName。",
  ui_story_5038_50380101_136_dialog_content = "謝、謝謝PlayerName先森！",
  ui_story_5038_50380101_137_dialog_content = "那就還等什麼，快上來吧，PlayerName公子！",
  ui_story_5038_50380101_138_dialog_content = "知、知道了！我這就來！",
  ui_story_5038_50380101_139_dialog_content = "嗷嗚——！",
  ui_story_5038_50380101_140_dialog_content = "哦！小尾巴看到海魚了！",
  ui_story_5038_50380101_141_dialog_content = "不可以哦小尾巴，不能跳下去！",
  ui_story_5038_50380101_142_dialog_content = "嗚……",
  ui_story_5038_50380101_143_dialog_content = "艾斯特拉大陸的海風似乎比龍洲的更加凜冽呢……",
  ui_story_5038_50380101_144_dialog_content = "這正是出海的好天氣。",
  ui_story_5038_50380101_145_dialog_content = "風正在鼓動蜃風號的船帆，風向是……西南風。",
  ui_story_5038_50380101_146_dialog_content = "我要把兩側的甲板收起來了，諸位，都坐穩了！",
  ui_story_5038_50380101_147_dialog_content = "蜃風號，啟程！",
  ui_story_5038_50380201_1_dialog_content = "（林家商船的構造還真是驚人，比我坐過的任何一艘船都要大。）",
  ui_story_5038_50380201_2_dialog_content = "（而且連甲板的設計都充滿了華麗的東方色彩。）",
  ui_story_5038_50380201_3_dialog_content = "（從甲板上看下去的視野也很開闊……）",
  ui_story_5038_50380201_4_dialog_content = "（啊～藍天、海浪、清爽的海風……）",
  ui_story_5038_50380201_5_dialog_content = "嗯？",
  ui_story_5038_50380201_6_dialog_content = "仲胥大人，您為什麼要獨自看著海發呆？",
  ui_story_5038_50380201_7_dialog_content = "仲某在看海水。",
  ui_story_5038_50380201_8_dialog_content = "海水……有什麼奇特的地方嗎？",
  ui_story_5038_50380201_9_dialog_content = "恰是因為無論哪裡的海水，都是一個樣子，看著就會讓我想起故鄉的港口。",
  ui_story_5038_50380201_10_dialog_content = "原來您這麼想家。",
  ui_story_5038_50380201_11_dialog_content = "說起來，在出發之前，我還以為會有很多在雙榭城旅居已久的人和我們同行。",
  ui_story_5038_50380201_12_dialog_content = "沒想到到最後，只有您和厘青登上了這艘船。",
  ui_story_5038_50380201_13_dialog_content = "人在外面漂泊久了，總是會誕生出想家的想法。",
  ui_story_5038_50380201_14_dialog_content = "那些退掉船票的人並非不想，而是一顆「鄉」的種子已經在雙榭城紮了新根。",
  ui_story_5038_50380201_15_dialog_content = "他們在雙榭城擁有新的家人、新的朋友，思鄉之情最終也只能是一朵鏡中花。",
  ui_story_5038_50380201_16_dialog_content = "只有像仲某這種人，了無牽掛，才可以赤條條地來去自由罷了。",
  ui_story_5038_50380201_17_dialog_content = "我似乎可以理解您的這種想法……",
  ui_story_5038_50380201_18_dialog_content = "呵呵，小友，沒想到你小小年紀，居然也喜歡聽我說這些話。",
  ui_story_5038_50380201_19_dialog_content = "跟你聊天很是投緣，你也不必稱呼我為「大人」了。",
  ui_story_5038_50380201_20_dialog_content = "仲某很希望跟你交個朋友，你我之間也不需要使用敬稱。",
  ui_story_5038_50380201_21_dialog_content = "像厘青老弟一樣，叫我的名字就可以了。",
  ui_story_5038_50380201_22_dialog_content = "好呀，我很榮幸，也很樂意……",
  ui_story_5038_50380201_23_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5038_50380201_24_dialog_content = "嗚哇？！",
  ui_story_5038_50380201_25_dialog_content = "什麼東西？！突然濺了我一臉的水！",
  ui_story_5038_50380201_26_dialog_content = "是成群結隊的海魚哦。",
  ui_story_5038_50380201_27_dialog_content = "如果看到了尾巴像龍尾一樣的魚，那就是<color=#FFB400>螭龍魚</color>！",
  ui_story_5038_50380201_28_dialog_content = "真、真是驚人啊……居然能隔著這麼高的船體把水花濺在我的臉上！",
  ui_story_5038_50380201_29_dialog_content = "因為冬季正是牠們的活躍期，也就是繁殖期。",
  ui_story_5038_50380201_30_dialog_content = "牠們一出生就會成群結隊地往深海中游去。",
  ui_story_5038_50380201_31_dialog_content = "不管遊到了多遠的地方，一到冬季，牠們就會和附近的同伴們聚集在一起。",
  ui_story_5038_50380201_32_dialog_content = "然後一起向龍洲的海港洄游，在龍洲的淺海產卵，周而復始。",
  ui_story_5038_50380201_33_dialog_content = "厘青似乎對這種魚非常瞭解？",
  ui_story_5038_50380201_34_dialog_content = "哼哼～因為，螭龍魚是林家商會信仰的動物。",
  ui_story_5038_50380201_35_dialog_content = "算是圖騰那一類的東西吧？",
  ui_story_5038_50380201_36_dialog_content = "嗯，好像可以理解，林家是想和這些魚一樣，每次出海都能平安地返航吧。",
  ui_story_5038_50380201_37_dialog_content = "卜子曰，孺子可教也～PlayerName很聰明～",
  ui_story_5038_50380201_38_dialog_content = "不要拿出一副大人的態度跟我說話啊！",
  ui_story_5038_50380201_39_dialog_content = "別看我這樣，說不定我是PlayerName的長輩呢。",
  ui_story_5038_50380201_40_dialog_content = "PlayerName最好還是拿出跟長輩說話的態度哦……",
  ui_story_5038_50380201_41_dialog_content = "哇？嗅嗅……嗅嗅……好香！怎麼有魚香味？！",
  ui_story_5038_50380201_42_dialog_content = "因為到了吃午膳的時間啦。",
  ui_story_5038_50380201_43_dialog_content = "今天是我們出海的第一天，所以要好好地補充補充士氣。",
  ui_story_5038_50380201_44_dialog_content = "PlayerName公子也來嚐嚐吧，這是龍洲的特色菜——<color=#FFB400>松鼠魚</color>！",
  ui_story_5038_50380201_45_dialog_content = "把捕來的魚去骨、打上花刀，用油炸過之後再淋上酸甜的醬汁……",
  ui_story_5038_50380201_46_dialog_content = "等一下！妳、妳捉的是什麼魚啊？！",
  ui_story_5038_50380201_47_dialog_content = "螭龍魚啊，很嫩的。",
  ui_story_5038_50380201_48_dialog_content = "什麼？！！！",
  ui_story_5038_50380201_49_dialog_content = "呵呵，逗你的啦，是貨艙裡的商品魚。",
  ui_story_5038_50380201_50_dialog_content = "兩位快點隨我去客艙吧，其他人都已經到了。",
  ui_story_5038_50380201_51_dialog_content = "<color=#e8d9bb>蜃風號 客艙</color>",
  ui_story_5038_50380201_52_dialog_content = "唷，丹棠殿下好手藝啊，這條魚的味道好正宗！",
  ui_story_5038_50380201_53_dialog_content = "騙子大人這個誇獎我可受不住。",
  ui_story_5038_50380201_54_dialog_content = "這些菜全都是阿玖做的。",
  ui_story_5038_50380201_55_dialog_content = "丹棠殿下也在烹飪過程中幫了些忙。",
  ui_story_5038_50380201_56_dialog_content = "這麼相敬如賓的主僕二人，全濟國都找不出第二對了吧？",
  ui_story_5038_50380201_57_dialog_content = "……",
  ui_story_5038_50380201_58_dialog_content = "抱歉，殿下並不願意談及濟國的話題。",
  ui_story_5038_50380201_59_dialog_content = "還是請雙榭城的兩位林家人，講講他們<color=#FFB400>當時</color>的見聞吧。",
  ui_story_5038_50380201_60_dialog_content = "啊呣啊呣……好香好香……",
  ui_story_5038_50380201_61_dialog_content = "來，小尾巴，你也來一口！",
  ui_story_5038_50380201_62_dialog_content = "喵～",
  ui_story_5038_50380201_63_dialog_content = "這個小醫生看起來一時半會也抬不起頭。",
  ui_story_5038_50380201_64_dialog_content = "仲胥大人，請吧。",
  ui_story_5038_50380201_65_dialog_content = "船長這是願意信我。但事情已經過了半年之久，細節上或許有所偏差。",
  ui_story_5038_50380201_66_dialog_content = "仲某現在把事故發生前後的經過講出來，諸位就當聽故事吧。",
  ui_story_5038_50380201_67_dialog_content = "求之不得！在下走南闖北，最喜歡聽這些奇聞軼事。",
  ui_story_5038_50380201_68_dialog_content = "我接下要講的東西，可能沒有那麼輕鬆。",
  ui_story_5038_50380201_69_dialog_content = "我和厘青老弟嚴格來說並不是林家的人，這位船長才是林家的子弟。",
  ui_story_5038_50380201_70_dialog_content = "仲胥大人不必如此客氣。",
  ui_story_5038_50380201_71_dialog_content = "頂著「木」的姓氏，我算什麼真正的林家人呢。",
  ui_story_5038_50380201_72_dialog_content = "抱歉抱歉，是仲某思慮不周，我本無意拿妳的姓氏做文章。",
  ui_story_5038_50380201_73_dialog_content = "總之，我只是林家的故交，厘青老弟則是林府的清客。",
  ui_story_5038_50380201_74_dialog_content = "這種身分，反而讓我們在事故之後留下了性命。",
  ui_story_5038_50380201_75_dialog_content = "半年之前，林家究竟發生了什麼變故？",
  ui_story_5038_50380201_76_dialog_content = "這個事件因「羅盤」而起，也止於「羅盤」。",
  ui_story_5038_50380201_77_dialog_content = "林家依靠「羅盤」壟斷了海上貿易，自然也惹來了不懷好意的側目。",
  ui_story_5038_50380201_78_dialog_content = "在某個商會的牽頭之下，幾個小族聯合起來，想要覆滅林家。",
  ui_story_5038_50380201_79_dialog_content = "雖然他們的勢力不能與林家抗衡，卻根本不怕做那些丟臉面的事。",
  ui_story_5038_50380201_80_dialog_content = "那一日，我和厘青前往林家的宅子裡赴宴，宴席上還來了很多林家的親信。",
  ui_story_5038_50380201_81_dialog_content = "觥籌交錯之際，一群亂賊突然殺了進來……",
  ui_story_5038_50380202_1_dialog_content = "老哥！快來這邊！",
  ui_story_5038_50380202_2_dialog_content = "你沒受傷吧！",
  ui_story_5038_50380202_3_dialog_content = "一點小傷，無妨。",
  ui_story_5038_50380202_4_dialog_content = "至少把老林護出去了。",
  ui_story_5038_50380202_5_dialog_content = "林家家主沒事！那太好了！",
  ui_story_5038_50380202_6_dialog_content = "老林保住了，可其他人就……",
  ui_story_5038_50380202_7_dialog_content = "今日一過，恐怕商界再無林家的名號了。",
  ui_story_5038_50380202_8_dialog_content = "怎麼這樣……堂而皇之闖入府中作惡，沒有王法了嗎？",
  ui_story_5038_50380202_9_dialog_content = "那都是幫亡命之徒，腦袋早就掛在褲腰帶上了。",
  ui_story_5038_50380202_10_dialog_content = "有人給他們天大的好處，拼上性命來下這黑手。",
  ui_story_5038_50380202_11_dialog_content = "如果我沒猜錯，是為找「羅盤」而來的。",
  ui_story_5038_50380202_12_dialog_content = "「羅盤」？可「羅盤」又不在府中……",
  ui_story_5038_50380202_13_dialog_content = "他們還不知道。",
  ui_story_5038_50380202_14_dialog_content = "老林已經安排了後手，盡力保「羅盤」周全。",
  ui_story_5038_50380202_15_dialog_content = "如若不成……且由我為林家消災。",
  ui_story_5038_50380202_16_dialog_content = "厘青老弟，隨我來。",
  ui_story_5038_50380202_17_dialog_content = "在那之後，我們勉強從戰鬥中脫身。",
  ui_story_5038_50380202_18_dialog_content = "那時我們才知道，這群人的目標並不是林家的家主。",
  ui_story_5038_50380202_19_dialog_content = "為了保護「羅盤」不被摧毀或奪走，老林立刻決定，讓重要的親眷護送其離開。",
  ui_story_5038_50380202_20_dialog_content = "於是承載著「羅盤」的舊船，立即從港口啟程，向深海駛去。",
  ui_story_5038_50380202_21_dialog_content = "帶著羅盤出海？我不明白……出海不是更容易遭遇不測嗎？",
  ui_story_5038_50380202_22_dialog_content = "把這個寶貝「羅盤」藏在林家的什麼保險櫃之類的地方不是更好嗎？",
  ui_story_5038_50380202_23_dialog_content = "從海裡生長出來的東西，當然要放在海裡才最保險。",
  ui_story_5038_50380202_24_dialog_content = "唔？這是什麼意思……",
  ui_story_5038_50380202_25_dialog_content = "只要有「羅盤」護航，船隻不僅不會迷失方向，還會順風順水，絕無意外。",
  ui_story_5038_50380202_26_dialog_content = "可是……",
  ui_story_5038_50380202_27_dialog_content = "可是「羅盤」還是遺失了，船長姐姐是要問這個吧？",
  ui_story_5038_50380202_28_dialog_content = "因為「羅盤」的遺失不是天災，而是人禍。",
  ui_story_5038_50380202_29_dialog_content = "……",
  ui_story_5038_50380202_30_dialog_content = "這群亂賊划著船，緊隨蜃風號舊船其後。",
  ui_story_5038_50380202_31_dialog_content = "他們惡意製造的騷亂，使我和厘青雙雙落水，再也沒有登上蜃風號。",
  ui_story_5038_50380202_32_dialog_content = "你也知道，那群亂賊並沒有成功取走「羅盤」，不然航線斷不了這麼久。",
  ui_story_5038_50380202_33_dialog_content = "但在那之後，我們和賊船全都遭遇了<color=#FFB400>巨大的風暴</color>。",
  ui_story_5038_50380202_34_dialog_content = "除我和厘青老弟之外，全船人等盡數遇難。",
  ui_story_5038_50380202_35_dialog_content = "我的雙腿，也是在那個時候受傷的。",
  ui_story_5038_50380202_36_dialog_content = "那是在哪一片海域發生的事情？",
  ui_story_5038_50380202_37_dialog_content = "不知道，我沒有海客這麼敏銳的方位判斷力。",
  ui_story_5038_50380202_38_dialog_content = "可能是得益於祟靈天然的靈性吧，厘青老弟帶著我，來到了艾斯特拉大陸。",
  ui_story_5038_50380202_39_dialog_content = "等一下……<color=#FFB400>「祟靈」</color>又是個什麼東西？",
  ui_story_5038_50380202_40_dialog_content = "好沒禮貌啊PlayerName，祟靈不是普通的「東西」哦。",
  ui_story_5038_50380202_41_dialog_content = "我來教教你吧，祟靈說白了就是我這種長了尾巴或耳朵的光靈。",
  ui_story_5038_50380202_42_dialog_content = "順便一提，「小尾巴」其實是我的哥哥來著。",
  ui_story_5038_50380202_43_dialog_content = "哈——！",
  ui_story_5038_50380202_44_dialog_content = "啊，我大致明白了。",
  ui_story_5038_50380202_45_dialog_content = "（總之就是具備亞人血統的光靈吧，這可能就是龍洲對亞人族獨特的叫法吧。）",
  ui_story_5038_50380202_46_dialog_content = "按照林家的記錄，「羅盤」從來沒有丟失過的先例。",
  ui_story_5038_50380202_47_dialog_content = "雖然我並沒有親眼見過它，但據說是個<color=#FFB400>「與船共生，與船共死」</color>的寶物。",
  ui_story_5038_50380202_48_dialog_content = "諸位，我還是想試一試，即使是只能找到船骸也好，我要找到它的下落。",
  ui_story_5038_50380202_49_dialog_content = "我也不希望諸位再碰到如仲胥大人所說那樣的海難了。",
  ui_story_5038_50380202_50_dialog_content = "我明白了，為了船上的各位，也不應該率先放棄希望。",
  ui_story_5038_50380202_51_dialog_content = "就算船長姐姐不這麼說，我也是一定要找到「羅盤」的。",
  ui_story_5038_50380202_52_dialog_content = "快入夜了，今天的蜃風號就這麼收帆吧。",
  ui_story_5038_50380202_53_dialog_content = "諸位可以安心休息，我和船工們會擔任守夜的工作。",
  ui_story_5038_50380202_54_dialog_content = "我也來！",
  ui_story_5038_50380202_55_dialog_content = "小孩子快去好好睡覺。",
  ui_story_5038_50380202_56_dialog_content = "都說了我不是小孩子了！",
  ui_story_5038_50380202_57_dialog_content = "而且，我和小尾巴本來在晚上就不容易睡著嘛。",
  ui_story_5038_50380202_58_dialog_content = "讓他去吧，不然他也會忍不住干擾各位睡覺。",
  ui_story_5038_50380202_59_dialog_content = "嗷！我才不會做這種事！",
  ui_story_5038_50380202_60_dialog_content = "好吧，那就麻煩厘青一會跟著我一起去甲板吧。",
  ui_story_5038_50380202_61_dialog_content = "寢榻在客艙的裡間，都是獨立的廂房。仲胥大人、PlayerName，這邊請吧。",
  ui_story_5038_50380301_1_dialog_content = "<color=#e8d9bb>半夜</color>",
  ui_story_5038_50380301_2_dialog_content = "呼……",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>轟隆隆……</color>",
  ui_story_5038_50380301_4_dialog_content = "（唔？是打雷嗎……）",
  ui_story_5038_50380301_5_dialog_content = "（好晃……外面下雨了嗎……）",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5038_50380301_7_dialog_content = "哇？！",
  ui_story_5038_50380301_8_dialog_content = "剛才是什麼聲音？！",
  ui_story_5038_50380301_9_dialog_content = "<color=#e8d9bb>喵——！</color>",
  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>喵嗷——！！！</color>",
  ui_story_5038_50380301_11_dialog_content = "不怕、不怕……一心乖，不怕。",
  ui_story_5038_50380301_12_dialog_content = "抱歉，驚擾小友睡覺了。",
  ui_story_5038_50380301_13_dialog_content = "一心、一夢、一諾這三隻貓曾陪著仲某出生入死，經歷過蜃風號舊船的海難……",
  ui_story_5038_50380301_14_dialog_content = "這種景象對他們來說，就像舊日的噩夢重現一樣可怕。",
  ui_story_5038_50380301_15_dialog_content = "重點不是貓的叫聲吧！剛才的聲音你聽見了嗎！",
  ui_story_5038_50380301_16_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5038_50380301_17_dialog_content = "諸位醒了嗎？都沒事吧？！",
  ui_story_5038_50380301_18_dialog_content = "阿玖最先聽到了這個聲音，我正在和她一起叫醒那些還在熟睡的乘客。",
  ui_story_5038_50380301_19_dialog_content = "到底發生了什麼事？",
  ui_story_5038_50380301_20_dialog_content = "不知道，只能感覺到有什麼東西正在撞擊蜃風的船體！",
  ui_story_5038_50380301_21_dialog_content = "而且……似乎並不只是<color=#FFB400>一個</color>東西。",
  ui_story_5038_50380301_22_dialog_content = "（難道是暗鬼嗎……出現在這種深夜的海面？）",
  ui_story_5038_50380301_23_dialog_content = "我去甲板看看！",
  ui_story_5038_50380301_24_dialog_content = "在下也隨PlayerName同去。",
  ui_story_5038_50380301_25_dialog_content = "那仲胥先生就跟著我和丹棠殿下去避難吧。",
  ui_story_5038_50380301_26_dialog_content = "如果我沒有記錯的話，到下一層客艙之間有一個滑坡。",
  ui_story_5038_50380301_27_dialog_content = "咦？您怎麼……",
  ui_story_5038_50380301_28_dialog_content = "畢竟這個新的蜃風號內部構造和舊船一模一樣。",
  ui_story_5038_50380301_29_dialog_content = "好了，我們快走吧。",
  ui_story_5038_50380301_30_dialog_content = "小友，別的話不必說了，只是如果憑你們的力量也幫不了厘青和月白……",
  ui_story_5038_50380301_31_dialog_content = "就快些帶著他們一同來下層避難，不要逞強。",
  ui_story_5038_50380301_32_dialog_content = "好的，請放心吧。",
  ui_story_5038_50380301_33_dialog_content = "<color=#e8d9bb>蜃風號 甲板</color>",
  ui_story_5038_50380301_34_dialog_content = "好大的雨……",
  ui_story_5038_50380301_35_dialog_content = "月白——厘青——！",
  ui_story_5038_50380301_36_dialog_content = "月白船長——小貓咪——！",
  ui_story_5038_50380301_37_dialog_content = "不行啊PlayerName，雨聲太大了，他們根本聽不到。",
  ui_story_5038_50380301_38_dialog_content = "試一試感應他們呢？傳說中的空裔！",
  ui_story_5038_50380301_39_option_content = "強制感應",
  ui_story_5038_50380301_40_dialog_content = "唔……也不行，只有微弱的光能和暗能交織在一起。",
  ui_story_5038_50380301_41_dialog_content = "嗯？！",
  ui_story_5038_50380301_42_dialog_content = "除了這些之外，好像還有一種我從來沒有見識過的氣息……",
  ui_story_5038_50380301_43_dialog_content = "就像丹棠的護衛所說的一樣……是成群結隊的東西！",
  ui_story_5038_50380301_44_dialog_content = "除此之外，還能「感應」到一股很強的能量……",
  ui_story_5038_50380301_45_dialog_content = "再加把勁兒啊，PlayerName！",
  ui_story_5038_50380301_46_dialog_content = "不行，完全感應不到他們……",
  ui_story_5038_50380301_47_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5038_50380301_48_dialog_content = "<size=50><color=#e8d9bb>砰！！！！！！</color></size>",
  ui_story_5038_50380301_49_dialog_content = "哇——小心一點！",
  ui_story_5038_50380301_50_dialog_content = "PlayerName，我們去瞧瞧這個聲音的源頭吧！",
  ui_story_5038_50380301_51_dialog_content = "好……！",
  ui_story_5038_50380301_52_dialog_content = "這、這是……",
  ui_story_5038_50380301_53_dialog_content = "小尾巴！不、不要掙扎！",
  ui_story_5038_50380301_54_dialog_content = "我要抱不住你了！",
  ui_story_5038_50380301_55_dialog_content = "船長姐姐……妳那邊怎麼樣！",
  ui_story_5038_50380301_56_dialog_content = "厘青，你先穩住自己，抓好了！不要亂動！",
  ui_story_5038_50380301_57_dialog_content = "厘青！月白！",
  ui_story_5038_50380301_58_dialog_content = "嗚哇？！PlayerName，還有李天閑！",
  ui_story_5038_50380301_59_dialog_content = "你們怎麼上來了？！",
  ui_story_5038_50380301_60_dialog_content = "快去安全的地方躲著，把厘青帶下去！",
  ui_story_5038_50380301_61_dialog_content = "<size=50><color=#e8d9bb>砰！！！</color></size>",
  ui_story_5038_50380301_62_dialog_content = "啊……<color=#FFB400>螭龍魚</color>！",
  ui_story_5038_50380301_63_dialog_content = "螭龍魚在撞蜃風的船腹！船工——！",
  ui_story_5038_50380301_64_dialog_content = "是、是！",
  ui_story_5038_50380301_65_dialog_content = "帶著人去最底層的船艙裡開啟應急措施，防止漏水！",
  ui_story_5038_50380301_66_dialog_content = "明白！",
  ui_story_5038_50380301_67_dialog_content = "螭龍魚……",
  ui_story_5038_50380301_68_dialog_content = "為什麼……為什麼牠們要撞擊蜃風？",
  ui_story_5038_50380301_69_dialog_content = "（原來厘青所說的螭龍魚就是這些生物……）",
  ui_story_5038_50380301_70_dialog_content = "（明明聚集在一起的樣子像銀環一樣漂亮……力氣卻大得恐怖！）",
  ui_story_5038_50380301_71_dialog_content = "<size=50><color=#e8d9bb>砰！！！</color></size>",
  ui_story_5038_50380301_72_dialog_content = "別愣著了小貓咪！離船舷遠一點，別掉下去！",
  ui_story_5038_50380301_73_dialog_content = "厘青，我們應該怎麼阻止牠們？",
  ui_story_5038_50380301_74_dialog_content = "不、不行……沒有「羅盤」的話，根本做不到……",
  ui_story_5038_50380301_75_dialog_content = "<size=50><color=#e8d9bb>咚——</color></size>",
  ui_story_5038_50380301_76_dialog_content = "糟了……",
  ui_story_5038_50380301_77_dialog_content = "你們快走，我去穩住船頭，還能再拖一點時間！",
  ui_story_5038_50380301_78_dialog_content = "船身開始傾斜了，你們跟著船工去坐救生艇！",
  ui_story_5038_50380301_79_dialog_content = "等一下！",
  ui_story_5038_50380301_80_dialog_content = "還等什麼？！",
  ui_story_5038_50380301_81_dialog_content = "蜃風號的傾斜另有原因！我能感覺到，好像……",
  ui_story_5038_50380301_82_dialog_content = "好像有什麼東西大批地登上了船……",
  ui_story_5038_50380301_83_dialog_content = "吼……",
  ui_story_5038_50380301_84_dialog_content = "嘎！！！",
  ui_story_5038_50380301_85_dialog_content = "果然是這群趁虛而入的暗鬼！",
  ui_story_5038_50380301_86_dialog_content = "……PlayerName，你能上來幫忙還真是蜃風號的運氣。",
  ui_story_5038_50380301_87_dialog_content = "那就請跟我一起把牠們解決掉吧！",
  ui_story_5038_50380302_1_dialog_content = "這下就全都幹掉了！",
  ui_story_5038_50380302_2_dialog_content = "幫大忙了，PlayerName。",
  ui_story_5038_50380302_3_dialog_content = "可是，在下看這船還是在不斷地傾斜啊……",
  ui_story_5038_50380302_4_dialog_content = "<color=#e8d9bb>吱嘎——</color>",
  ui_story_5038_50380302_5_dialog_content = "船工，搬來重物和貨品去船尾平衡船身！",
  ui_story_5038_50380302_6_dialog_content = "是！",
  ui_story_5038_50380302_7_dialog_content = "有魚咬住了船頭的繩索，才方便了那群暗鬼登船。",
  ui_story_5038_50380302_8_dialog_content = "PlayerName、厘青、天閑，方便的話，你們也跟著船工前往船尾吧。",
  ui_story_5038_50380302_9_dialog_content = "好！",
  ui_story_5038_50380302_10_dialog_content = "來，拿著吧，PlayerName！",
  ui_story_5038_50380302_11_dialog_content = "嗚哇？！好重！這是什麼？",
  ui_story_5038_50380302_12_dialog_content = "這是蜃風從龍洲運來的鐵秤砣，滿滿一箱都是。",
  ui_story_5038_50380302_13_dialog_content = "……怎麼會運這種東西啊！",
  ui_story_5038_50380302_14_dialog_content = "算帳、稱重、行商必備嘛，反正總有用上的時候！",
  ui_story_5038_50380302_15_dialog_content = "您瞧，現在不就用上了嗎。",
  ui_story_5038_50380302_16_dialog_content = "在下跟您一人拿了一箱，我們這就挪去船尾，給蜃風「配重」吧！",
  ui_story_5038_50380302_17_dialog_content = "小貓咪，你就甭拿了，在下看你這身板也拿不動。",
  ui_story_5038_50380302_18_dialog_content = "我要留在這裡。",
  ui_story_5038_50380302_19_dialog_content = "開什麼玩笑，乖，聽話啊。",
  ui_story_5038_50380302_20_dialog_content = "我都說了我要留在這裡。",
  ui_story_5038_50380302_21_dialog_content = "（厘青一直在向著海裡的方向看，好像在尋找著什麼……）",
  ui_story_5038_50380302_22_dialog_content = "厘青，你有主意嗎？你知道這些螭龍魚暴動的原因嗎？",
  ui_story_5038_50380302_23_dialog_content = "不，我完全沒有頭緒……",
  ui_story_5038_50380302_24_dialog_content = "但是螭龍魚從來不會無緣無故地擅自襲擊人！",
  ui_story_5038_50380302_25_dialog_content = "牠們一定在聽從牠們之中的那條「頭魚」。",
  ui_story_5038_50380302_26_dialog_content = "「頭魚」為什麼要襲擊這條船，牠的目標是什麼……",
  ui_story_5038_50380302_27_dialog_content = "你想把這條「頭魚」找到？",
  ui_story_5038_50380302_28_dialog_content = "至少……我要看清楚牠們遊來的<color=#FFB400>方向</color>。",
  ui_story_5038_50380302_29_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5038_50380302_30_dialog_content = "（這群螭龍魚愈來愈躁動了，再這樣下去……）",
  ui_story_5038_50380302_31_option_content = "強制感應！",
  ui_story_5038_50380302_32_dialog_content = "這樣也行？！",
  ui_story_5038_50380302_33_dialog_content = "不、不知道啊！試一試總沒有壞處！",
  ui_story_5038_50380302_34_dialog_content = "（就像我剛才「看」到的一樣……）",
  ui_story_5038_50380302_35_dialog_content = "（試著感受這群來自東方的動物……試著安撫牠們……）",
  ui_story_5038_50380302_36_dialog_content = "（糟了，這次好像並沒有什麼用處！）",
  ui_story_5038_50380302_37_dialog_content = "牠們好像真的停下來了，PlayerName你看！",
  ui_story_5038_50380302_38_dialog_content = "真的嗎！讓我歪打正著了？！",
  ui_story_5038_50380302_39_dialog_content = "牠們突然集體調轉了方向，匯成了帶子形狀的魚群……",
  ui_story_5038_50380302_40_dialog_content = "……不對！不對勁！！！",
  ui_story_5038_50380302_41_dialog_content = "什、什麼意思？！",
  ui_story_5038_50380302_42_dialog_content = "你們！抓好船舷，快趴下！",
  ui_story_5038_50380302_43_dialog_content = "牠們……衝過來了！！！",
  ui_story_5038_50380302_44_dialog_content = "船長姐姐，快讓蜃風轉向！",
  ui_story_5038_50380302_45_dialog_content = "（螭龍魚的衝擊已經給蜃風造成了重創，再加上現在的暴風雨……）",
  ui_story_5038_50380302_46_dialog_content = "（方向盤根本難以操控……）",
  ui_story_5038_50380302_47_dialog_content = "諸位，抓穩抓牢，保護好頭部！",
  ui_story_5038_50380302_48_dialog_content = "（大海……你要再一次拒絕蜃風這個名字嗎……）",
  ui_story_5038_50380302_49_dialog_content = "<size=45><color=#e8d9bb>砰！！！！！！</color></size>",
  ui_story_5038_50380402_1_dialog_content = "嘶——！",
  ui_story_5038_50380402_2_dialog_content = "（身上好酸，背也好痛……）",
  ui_story_5038_50380402_3_dialog_content = "（我活下來了……嗎？）",
  ui_story_5038_50380402_4_dialog_content = "PlayerName，你還好嗎？",
  ui_story_5038_50380402_5_dialog_content = "月、月白，妳還活著！",
  ui_story_5038_50380402_6_dialog_content = "還有……大家？",
  ui_story_5038_50380402_7_dialog_content = "別睡啦PlayerName，太陽要曬屁股啦！",
  ui_story_5038_50380402_8_dialog_content = "小友，你身上沒有大礙吧。",
  ui_story_5038_50380402_9_dialog_content = "太讓人擔心了，PlayerName。",
  ui_story_5038_50380402_10_dialog_content = "我的頭還是有點痛……昨天晚上到最後究竟發生了什麼？",
  ui_story_5038_50380402_11_dialog_content = "昨天晚上，蜃風號在激烈的撞擊下險些失控。",
  ui_story_5038_50380402_12_dialog_content = "最後撞上了海中的暗礁。",
  ui_story_5038_50380402_13_dialog_content = "在昨晚的螭龍魚散去之後，風浪也逐漸平息了。",
  ui_story_5038_50380402_14_dialog_content = "你和李天閑在激烈的晃動之中暈了過去，船工把你們挪去了客艙。",
  ui_story_5038_50380402_15_dialog_content = "不過，厘青這個小醫生給你們開了藥方，已經分別給你們倆對症下藥了。",
  ui_story_5038_50380402_16_dialog_content = "把你扛回甲板曬太陽也是我的主意哦。",
  ui_story_5038_50380402_17_dialog_content = "身上好像確實覺得暖洋洋的……",
  ui_story_5038_50380402_18_dialog_content = "唔？！",
  ui_story_5038_50380402_19_dialog_content = "嘔——好苦，我、我嘴裡放著什麼！",
  ui_story_5038_50380402_20_dialog_content = "哦！先不要吐掉，這是治療暈船的含片！",
  ui_story_5038_50380402_21_dialog_content = "裡面含有一味東莨菪堿，一味金銀花，一味薄荷片。",
  ui_story_5038_50380402_22_dialog_content = "良藥苦口，PlayerName堅持住哦！",
  ui_story_5038_50380402_23_dialog_content = "知、知道了……",
  ui_story_5038_50380402_24_dialog_content = "不過既然你已經可以站起來活動了，那也沒什麼好擔心的。",
  ui_story_5038_50380402_25_dialog_content = "比起這個，經過昨天一晚，蜃風號的情況到底怎麼樣了？",
  ui_story_5038_50380402_26_dialog_content = "不太妙。",
  ui_story_5038_50380402_27_dialog_content = "桅杆被風浪刮斷了，船艙裡也滲了水。",
  ui_story_5038_50380402_28_dialog_content = "蜃風現在脆弱不堪，無法再經歷任何一次風浪。",
  ui_story_5038_50380402_29_dialog_content = "這麼嚴重？！",
  ui_story_5038_50380402_30_dialog_content = "別說航行了，這樣連活命都成問題吧！",
  ui_story_5038_50380402_31_dialog_content = "……此情此景，正與仲某當年的遭遇一模一樣。",
  ui_story_5038_50380402_32_dialog_content = "我曾經一意孤行，認為只靠我自己復通航路、把船開到艾斯特拉大陸也沒問題。",
  ui_story_5038_50380402_33_dialog_content = "甚至還僥倖覺得即使此次找不到「羅盤」，也可以平安無事。",
  ui_story_5038_50380402_34_dialog_content = "現在看來……林家果然還是需要「羅盤」的庇佑。",
  ui_story_5038_50380402_35_dialog_content = "昨天晚上的那群螭龍魚，回想起來非常蹊蹺。",
  ui_story_5038_50380402_36_dialog_content = "船長姐姐作為林家人，想必也知道螭龍魚的習性。",
  ui_story_5038_50380402_37_dialog_content = "牠們是一群極度喜歡群居活動的動物，如果沒有頭魚的引導，不會盲目襲擊。",
  ui_story_5038_50380402_38_dialog_content = "那是從前的記載了。",
  ui_story_5038_50380402_39_dialog_content = "這半年來，這些遊蕩在海中的螭龍魚也性情大變。",
  ui_story_5038_50380402_40_dialog_content = "牠們會無緣無故地攻擊海裡過往的船隻，直至船毀人亡。",
  ui_story_5038_50380402_41_dialog_content = "我不怕做那些孤注一擲的事情，可此處有一船人的性命。",
  ui_story_5038_50380402_42_dialog_content = "接下來的航行，我們恐怕……",
  ui_story_5038_50380402_43_dialog_content = "這、這是什麼意思？既不能前行，又無法長久地原地不動……",
  ui_story_5038_50380402_44_dialog_content = "豈不是只剩下坐以待斃嗎？",
  ui_story_5038_50380402_45_dialog_content = "……",
  ui_story_5038_50380402_46_dialog_content = "船長姐姐……",
  ui_story_5038_50380402_47_dialog_content = "怎麼大中午的，全都哭喪著臉？",
  ui_story_5038_50380402_48_dialog_content = "在下剛剛求得三簽，諸位要不要聽聽？",
  ui_story_5038_50380402_49_dialog_content = "都什麼時候了，你還想著這些裝神弄鬼的生意。",
  ui_story_5038_50380402_50_dialog_content = "這可不是裝神弄鬼。船長，旁人都可以不信，但妳一定要聽一聽。",
  ui_story_5038_50380402_51_dialog_content = "為何是我？",
  ui_story_5038_50380402_52_dialog_content = "話說剛才在下大夢初醒之時，忽然發現眼皮一陣異動。",
  ui_story_5038_50380402_53_dialog_content = "每每回想昨晚的遭遇，便發覺，在絕境的冥冥之中，自有啟示。",
  ui_story_5038_50380402_54_dialog_content = "麻煩你說重點。",
  ui_story_5038_50380402_55_dialog_content = "好吧，好吧，總而言之，在下為蜃風號的未來算了三卦。",
  ui_story_5038_50380402_56_dialog_content = "在下的萬類天斗卦表，以簡單的陰陽與生肖作為表面的卦象，內裡卻大有乾坤。",
  ui_story_5038_50380402_57_dialog_content = "只可惜在下雖然懂得算卦占卜，卻不懂蜃風號。",
  ui_story_5038_50380402_58_dialog_content = "還要請月白船長指點在下，才能破解這三卦的真正含義。",
  ui_story_5038_50380402_59_dialog_content = "不要賣關子了，你儘管說就行。",
  ui_story_5038_50380402_60_dialog_content = "按蜃風現在的狀況，也是死馬當活馬醫。",
  ui_story_5038_50380402_61_dialog_content = "這三卦怪異至極，分別是「首鼠兩端」、「猿猴取月」、「狡兔三窟」。",
  ui_story_5038_50380402_62_dialog_content = "在下行走江湖多年，還沒有碰到過這麼難解的卦象。",
  ui_story_5038_50380402_63_dialog_content = "三個陰陽完全相同的卦象，看起來像是指向了同一件事。",
  ui_story_5038_50380402_64_dialog_content = "鼠、猴、兔……？",
  ui_story_5038_50380402_65_dialog_content = "天閑，你怎麼看？",
  ui_story_5038_50380402_66_dialog_content = "依在下這個外行人暫時的推測，這些卦像是「以物易物」的意思。",
  ui_story_5038_50380402_67_dialog_content = "正所謂假作真時真亦假，這三簽是告訴在下，要尋找合適的<color=#FFB400>替代品</color>。",
  ui_story_5038_50380402_68_dialog_content = "「合適的替代品」……",
  ui_story_5038_50380402_69_dialog_content = "我好像明白了！",
  ui_story_5038_50380402_70_dialog_content = "按照龍洲的習俗，會用十二生肖的屬相，為船身的重要部件做命名。",
  ui_story_5038_50380402_71_dialog_content = "靠這種方式，賦予吉祥的寓意，祈求船隻航行過程中能像這些動物們一樣如履平地。",
  ui_story_5038_50380402_72_dialog_content = "在昨晚的風浪中，不少船體上的零部件受創。",
  ui_story_5038_50380402_73_dialog_content = "蜃風船尾的「鼠尾」、船頭的「猴頭」正在此列，前者遺失後者損壞……",
  ui_story_5038_50380402_74_dialog_content = "可是，「兔耳」並無大礙。",
  ui_story_5038_50380402_75_dialog_content = "「兔耳」這一簽我再琢磨琢磨。",
  ui_story_5038_50380402_76_dialog_content = "不過只要找到前兩個玩意的替代品，蜃風是不是就可以正常航行了？",
  ui_story_5038_50380402_77_dialog_content = "會對船隻的修繕工作有所幫助，但並非一錘定音。",
  ui_story_5038_50380402_78_dialog_content = "船體受損處眾多，沒有取巧的餘地，只能一處處修起。",
  ui_story_5038_50380402_79_dialog_content = "況且，這些零部件的替代品要去哪找呢。",
  ui_story_5038_50380402_80_dialog_content = "如此說來，仲某倒覺得此事可成。",
  ui_story_5038_50380402_81_dialog_content = "畢竟，我們腳下的大海，就是廣袤的「寶庫」啊。",
  ui_story_5038_50380501_1_dialog_content = "（在仲胥和月白的提議下，我們並沒有啟用救生艇，而是繼續用蜃風號。）",
  ui_story_5038_50380501_2_dialog_content = "（船工們甚至把船錨都提了上來。）",
  ui_story_5038_50380501_3_dialog_content = "（難道我們已經可以……重新起航了嗎？）",
  ui_story_5038_50380501_4_dialog_content = "這是一個非常冒險的決定。",
  ui_story_5038_50380501_5_dialog_content = "大海裡沉沒著無數船隻，如果蜃風能行駛到我們半年前失事的區域……",
  ui_story_5038_50380501_6_dialog_content = "也許可以撈到可用的零部件。",
  ui_story_5038_50380501_7_dialog_content = "仲某也知道，這種方法無異於大海撈針。",
  ui_story_5038_50380501_8_dialog_content = "但這已經是所有下策中最好的辦法了。",
  ui_story_5038_50380501_9_dialog_content = "仲胥大人說得是。",
  ui_story_5038_50380501_10_dialog_content = "蜃風攜帶的救生艇不具備面對大風大浪的能力。",
  ui_story_5038_50380501_11_dialog_content = "我們也不可能長期滯留在海上。",
  ui_story_5038_50380501_12_dialog_content = "如果選擇在順風順水的時候緩慢地向前划行，也好過原地等死。",
  ui_story_5038_50380501_13_dialog_content = "諸位船工，有勞各位把碎帆收起來，在船兩側支起船槳。",
  ui_story_5038_50380501_14_dialog_content = "根據海圖的指引和標記，我們划向當時的事發之地。",
  ui_story_5038_50380501_15_dialog_content = "就算船長這麼說，這樣還是太冒險了……",
  ui_story_5038_50380501_16_dialog_content = "人在船上，我們也別說這種話了，小心得罪人。",
  ui_story_5038_50380501_17_dialog_content = "真到了大難臨頭的時候，這條命也從來都由不得我們。",
  ui_story_5038_50380501_18_dialog_content = "月白船長豈是由你們隨便私下議論的？",
  ui_story_5038_50380501_19_dialog_content = "丹、丹棠殿下……",
  ui_story_5038_50380501_20_dialog_content = "真要有什麼怨氣，大大方方跟她說便是，諸位再一起想解決的辦法。",
  ui_story_5038_50380501_21_dialog_content = "在這種風雲不測的海上，死都不怕，還怕什麼得罪？",
  ui_story_5038_50380501_22_dialog_content = "你們這邊在吵什麼？",
  ui_story_5038_50380501_23_dialog_content = "月白，他們有話要跟妳說。",
  ui_story_5038_50380501_24_dialog_content = "沒、沒有這回事，我沒什麼要說的。",
  ui_story_5038_50380501_25_dialog_content = "我也沒有，丹棠殿下不要為難人。",
  ui_story_5038_50380501_26_dialog_content = "……",
  ui_story_5038_50380501_27_dialog_content = "<color=#e8d9bb>颯——颯！</color>",
  ui_story_5038_50380501_28_dialog_content = "船船船長大人饒命！我……",
  ui_story_5038_50380501_29_dialog_content = "看看你們背後。",
  ui_story_5038_50380501_30_dialog_content = "咦……？",
  ui_story_5038_50380501_31_dialog_content = "嘎……",
  ui_story_5038_50380501_32_dialog_content = "青天白日的就想登船作惡？這也太不成體統了！",
  ui_story_5038_50380501_33_dialog_content = "跟這群東西講什麼體統。",
  ui_story_5038_50380501_34_dialog_content = "你們兩個，站我背後去。",
  ui_story_5038_50380501_35_dialog_content = "我可不會讓你們隨隨便便去送死。",
  ui_story_5038_50380501_36_dialog_content = "是……是！船長大人！",
  ui_story_5038_50380602_1_dialog_content = "「鼠尾」、「猴頭」、「兔耳」……",
  ui_story_5038_50380602_2_dialog_content = "真是隔行如隔山，只看名字完全不知道是什麼東西喵。",
  ui_story_5038_50380602_3_dialog_content = "簡單來說，分別就是風向標、滑輪和木板。",
  ui_story_5038_50380602_4_dialog_content = "<color=#FFB400>風向標</color>需要固定在桅杆的最頂端。",
  ui_story_5038_50380602_5_dialog_content = "因為尾部綁著的繩子像老鼠尾巴，而被稱為「鼠尾」。",
  ui_story_5038_50380602_6_dialog_content = "「鼠尾」的重量很輕，即使入水也會迅速浮起來。",
  ui_story_5038_50380602_7_dialog_content = "<color=#FFB400>滑輪</color>就是最常見的那種滑輪，需要依靠它把船帆升起來。",
  ui_story_5038_50380602_8_dialog_content = "因為形狀大小很像猴子的腦袋，所以叫「猴頭」。",
  ui_story_5038_50380602_9_dialog_content = "只要找到這兩個東西的替代品，船帆就可以重新使用了。",
  ui_story_5038_50380602_10_dialog_content = "哇，聽起來好像還挺容易的嘛！",
  ui_story_5038_50380602_11_dialog_content = "那麼，最後那個「兔耳」呢？",
  ui_story_5038_50380602_12_dialog_content = "……這個比較特殊，不是能輕易替換的東西。",
  ui_story_5038_50380602_13_dialog_content = "所幸蜃風的「兔耳」並未損壞，還是先找到「鼠尾」和「猴頭」吧。",
  ui_story_5038_50380602_14_dialog_content = "好，我明白了！",
  ui_story_5038_50380602_15_dialog_content = "PlayerName、丹棠，你們也會幫忙的吧？",
  ui_story_5038_50380602_16_dialog_content = "那是當然！",
  ui_story_5038_50380602_17_dialog_content = "（完、完全聽不明白……！）",
  ui_story_5038_50380602_18_dialog_content = "殿下不必逞強，殿下身在濟國的時候幾乎沒有出過府。",
  ui_story_5038_50380602_19_dialog_content = "聽不明白也是很正常的事。",
  ui_story_5038_50380602_20_dialog_content = "……就算妳這麼說，我也想為大家做些事情。",
  ui_story_5038_50380602_21_dialog_content = "妳既然覺得我不用逞強，那妳接下來也先不必跟著我了。",
  ui_story_5038_50380602_22_dialog_content = "丹、丹棠殿下……",
  ui_story_5038_50380602_23_dialog_content = "還真是任性喵～",
  ui_story_5038_50380602_24_dialog_content = "請不要這麼無禮地評價丹棠殿下。",
  ui_story_5038_50380602_25_dialog_content = "知道啦知道啦，那我們就先行動起來吧，PlayerName。",
  ui_story_5038_50380602_26_dialog_content = "可是……該去哪裡，又該怎麼找，我完全沒有頭緒啊。",
  ui_story_5038_50380602_27_dialog_content = "唔，我覺得……",
  ui_story_5038_50380602_28_dialog_content = "就先憑我和小尾巴的嗅覺，去甲板另一邊聞一聞吧！",
  ui_story_5038_50380602_29_dialog_content = "我們狸花貓對鼠尾巴的味道可是很敏感的！",
  ui_story_5038_50380602_30_dialog_content = "這完全不是一回事吧……！",
  ui_story_5038_50380602_31_dialog_content = "<color=#e8d9bb>蜃風號 客艙</color>",
  ui_story_5038_50380602_32_dialog_content = "嘿咻……",
  ui_story_5038_50380602_33_dialog_content = "（這裡也找一找……）",
  ui_story_5038_50380602_34_dialog_content = "丹棠殿下，您在找什麼？",
  ui_story_5038_50380602_35_dialog_content = "不甘你事。",
  ui_story_5038_50380602_36_dialog_content = "別這麼說呀，與其這麼悶頭瞎找，不妨讓在下給您算一卦吧。",
  ui_story_5038_50380602_37_dialog_content = "……你這個人對於這種行騙之事還真是執著。",
  ui_story_5038_50380602_38_dialog_content = "究竟是不是行騙，難道剛才的事情還不能為在下證明嗎？",
  ui_story_5038_50380602_39_dialog_content = "好吧……就算你是蒙出來的，也確實很有蒙的本事。",
  ui_story_5038_50380602_40_dialog_content = "我所找的東西正是船長口中遺失的「鼠尾」。",
  ui_story_5038_50380602_41_dialog_content = "在船上找？",
  ui_story_5038_50380602_42_dialog_content = "是的，根據我能理解的資訊，我暫時做出了這種推斷。",
  ui_story_5038_50380602_43_dialog_content = "船長說了，「鼠尾」很輕，即使掉進水裡也會浮起來。",
  ui_story_5038_50380602_44_dialog_content = "從昨晚的事故一直到現在，這群來來往往的船工們就沒有停下過巡視工作。",
  ui_story_5038_50380602_45_dialog_content = "按照林家商會隨行船工的本事，一根針掉進海裡都能被他們發現。",
  ui_story_5038_50380602_46_dialog_content = "所以，這個東西只能在船上。",
  ui_story_5038_50380602_47_dialog_content = "丹棠殿下好生聰明～在下也認同您的想法。",
  ui_story_5038_50380602_48_dialog_content = "既然如此，我們就在船上搜尋一番吧。",
  ui_story_5038_50380602_49_dialog_content = "多言、多語——",
  ui_story_5038_50380602_50_dialog_content = "知道了知道了。",
  ui_story_5038_50380602_51_dialog_content = "別催了別催了。",
  ui_story_5038_50380602_52_dialog_content = "會說話的八哥？！",
  ui_story_5038_50380602_53_dialog_content = "只是被在下訓練得很會模仿我們的語言罷了。",
  ui_story_5038_50380602_54_dialog_content = "去吧，多言多語，找一找綁著「老鼠尾巴」的風向標。",
  ui_story_5038_50380602_55_dialog_content = "找到之後有你們的好處。",
  ui_story_5038_50380602_56_dialog_content = "<color=#e8d9bb>撲啦啦……撲啦啦……</color>",
  ui_story_5038_50380602_57_dialog_content = "怎麼你這一次沒有堅持著「算一卦」了？",
  ui_story_5038_50380602_58_dialog_content = "良禽擇木而棲。這種時候，從高空俯瞰的鳥眼比卦象好使多了。",
  ui_story_5038_50380602_59_dialog_content = "走吧，丹棠殿下，我們快跟上牠們兩個。",
  ui_story_5038_50380602_60_dialog_content = "老鼠尾巴快要藏不住了。",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>嘎嘎——嘎嘎——</color>",
  ui_story_5038_50380602_62_dialog_content = "要千年古樹結的棗子！",
  ui_story_5038_50380602_63_dialog_content = "要金燦燦香噴噴的瓜子！",
  ui_story_5038_50380602_64_dialog_content = "知道知道，少不了你倆的獎勵。找到了嗎？",
  ui_story_5038_50380602_65_dialog_content = "這是……",
  ui_story_5038_50380602_66_dialog_content = "形狀好像一條尾巴，這就是船長說的「鼠尾」吧！",
  ui_story_5038_50380602_67_dialog_content = "嘿！依在下看，絕對沒錯了。",
  ui_story_5038_50380602_68_dialog_content = "也真虧了你們倆能在這堆沒清理乾淨的泥沙裡看到它。",
  ui_story_5038_50380602_69_dialog_content = "等著，一會兒就給你們吃上好的棗子、桂圓和瓜子。",
  ui_story_5038_50380602_70_dialog_content = "拿著吧，丹棠殿下。",
  ui_story_5038_50380602_71_dialog_content = "快拿著「鼠尾」去跟月白船長交差吧。",
  ui_story_5038_50380701_1_dialog_content = "（自從丹棠把「鼠尾」交給月白之後……）",
  ui_story_5038_50380701_2_dialog_content = "（船隻的修繕工作不斷進展，部分桅杆已經復原。）",
  ui_story_5038_50380701_3_dialog_content = "（蜃風的航行效率高了不少，甚至幾乎和先前沒有區別。）",
  ui_story_5038_50380701_4_dialog_content = "（只是……）",
  ui_story_5038_50380701_5_dialog_content = "風向變了，立即停擺船槳，準備拋錨！",
  ui_story_5038_50380701_6_dialog_content = "是！",
  ui_story_5038_50380701_7_dialog_content = "（只是仍要時不時地面對這種緊急停航的狀況。）",
  ui_story_5038_50380701_8_dialog_content = "小友看起來頗為懸心？",
  ui_story_5038_50380701_9_dialog_content = "不。不如說……我很相信月白的判斷力。",
  ui_story_5038_50380701_10_dialog_content = "不必這麼掩飾自己的心情，仲某也有著和你同樣的想法。",
  ui_story_5038_50380701_11_dialog_content = "（被看穿了……）",
  ui_story_5038_50380701_12_dialog_content = "雖然按照林家海圖的指引，我們正在一路前往「羅盤」遺失之地。",
  ui_story_5038_50380701_13_dialog_content = "但船隻的狀況太差了，臨時修繕讓它無法稱得上協調，只是在四處將就。",
  ui_story_5038_50380701_14_dialog_content = "航海是一件精密的事情，容不得一點疏漏。",
  ui_story_5038_50380701_15_dialog_content = "只靠許願是沒法讓事情順利進行的。",
  ui_story_5038_50380701_16_dialog_content = "……話雖這麼說，這也只是我的一點憂慮。",
  ui_story_5038_50380701_17_dialog_content = "小友不必介意。",
  ui_story_5038_50380701_18_dialog_content = "嗯，我會試著調整我的心情，仲胥，你也不要過分擔心了。",
  ui_story_5038_50380701_19_dialog_content = "蜃風號出生入死抵達了艾斯特拉，就絕不會讓我們輕易死在海上。",
  ui_story_5038_50380701_20_dialog_content = "忌諱！",
  ui_story_5038_50380701_21_dialog_content = "什、什麼？！",
  ui_story_5038_50380701_22_dialog_content = "……不好意思，是我失態。",
  ui_story_5038_50380701_23_dialog_content = "那個字在新年來臨之際，尤其會被我故鄉的人所忌諱。",
  ui_story_5038_50380701_24_dialog_content = "雖然這只是無關痛癢的風俗，但希望小友能諒解。",
  ui_story_5038_50380701_25_dialog_content = "失陪了。",
  ui_story_5038_50380701_26_dialog_content = "（是指……「死」這個字啊。）",
  ui_story_5038_50380701_27_dialog_content = "難得見到仲胥老哥的情緒這麼激烈。",
  ui_story_5038_50380701_28_dialog_content = "他果然還是在擔心重蹈半年之前的覆轍呢。",
  ui_story_5038_50380701_29_dialog_content = "PlayerName，你可以過來幫我一個忙嗎？",
  ui_story_5038_50380701_30_dialog_content = "我要把蜃風號的這艘木質的小救生船悄悄搬來船舷旁邊。",
  ui_story_5038_50380701_31_dialog_content = "哎？等一下，這個說白了，就是<color=#FFB400>偷</color>吧？！",
  ui_story_5038_50380701_32_dialog_content = "哎呀，不要說得這麼難聽喵。",
  ui_story_5038_50380701_33_dialog_content = "你看，船長姐姐和仲胥老哥正在那邊商討著防滲防漏的事。",
  ui_story_5038_50380701_34_dialog_content = "我不想再特意去麻煩他們。",
  ui_story_5038_50380701_35_dialog_content = "可是，你獨自用救生船做什麼？",
  ui_story_5038_50380701_36_dialog_content = "出海打撈「猴頭」啊。",
  ui_story_5038_50380701_37_dialog_content = "絕、絕對不行！這樣也太危險了！",
  ui_story_5038_50380701_38_dialog_content = "聽我說，PlayerName。就像人一樣，蜃風現在也「生了病」。",
  ui_story_5038_50380701_39_dialog_content = "治病還需對症下藥。有的草藥，輕輕鬆鬆就能夠得到。",
  ui_story_5038_50380701_40_dialog_content = "而有的草藥，往往生長在極為惡劣險峻的地方，不能被人隨便採集。",
  ui_story_5038_50380701_41_dialog_content = "「猴頭」已經損壞，船上並無替代之物。",
  ui_story_5038_50380701_42_dialog_content = "想醫治此病，需得潛入海中。",
  ui_story_5038_50380701_43_dialog_content = "潛入海中？船上沒有的東西，海裡更不會有了啊！",
  ui_story_5038_50380701_44_dialog_content = "不知道你有沒有注意看，四周的海面上有有些零星的殘骸。",
  ui_story_5038_50380701_45_dialog_content = "那是不知何時在海上遇難的船隻所留下的痕跡。",
  ui_story_5038_50380701_46_dialog_content = "若是能從中找到其他船的「猴頭」，定能補上蜃風上的缺損。",
  ui_story_5038_50380701_47_dialog_content = "在船帆拉起來之後，航行就能順利多了！到時候再擔心「兔耳」的事情！",
  ui_story_5038_50380701_48_dialog_content = "雖然確實是這樣的道理……但真的可行嗎？",
  ui_story_5038_50380701_49_dialog_content = "總覺得又是一項大海撈針的工作。",
  ui_story_5038_50380701_50_dialog_content = "我說可行，就一定可行，PlayerName，我可是「崇靈」啊。",
  ui_story_5038_50380701_51_dialog_content = "<color=#FFB400>海中的「朋友」</color>，自然會給我指示和訊號。",
  ui_story_5038_50380701_52_dialog_content = "真的有這麼靈？",
  ui_story_5038_50380701_53_dialog_content = "當然啊，我坐船的時候經常會跟牠們說話。",
  ui_story_5038_50380701_54_dialog_content = "只要我提出需求，牠們一定會幫我的。",
  ui_story_5038_50380701_55_dialog_content = "幫你找尋其他船的「猴頭」嗎？",
  ui_story_5038_50380701_56_dialog_content = "可是……牠們怎麼知道「猴頭」長什麼樣呢？",
  ui_story_5038_50380701_57_dialog_content = "沒問題的，我會描述給牠們聽。",
  ui_story_5038_50380701_58_dialog_content = "總之辛苦你了PlayerName！接下來就讓我獨自下去吧！",
  ui_story_5038_50380701_59_dialog_content = "雖然還是覺得有點擔心，不會我會隨時感應你的位置的。",
  ui_story_5038_50380701_60_dialog_content = "如果碰到了什麼不測，一定要第一時間透過感應告訴我啊。",
  ui_story_5038_50380701_61_dialog_content = "知道啦知道啦，你就等著我的好消息吧！",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5038_50380701_63_dialog_content = "嗷——！",
  ui_story_5038_50380701_64_dialog_content = "怎麼了怎麼了？！厘青！",
  ui_story_5038_50380701_65_option_content = "強制感應！",
  ui_story_5038_50380701_66_dialog_content = "（好多水！好多水、好多水、好多水……好多水！）",
  ui_story_5038_50380701_67_dialog_content = "嗚嗚……PlayerName！我四周全是水！",
  ui_story_5038_50380701_68_dialog_content = "廢話……因為你在海裡啊！",
  ui_story_5038_50380701_69_dialog_content = "等一下，難道說你害怕水？！",
  ui_story_5038_50380701_70_dialog_content = "這、這是當然的哇！狸花貓怕水不是很正常嗎？！",
  ui_story_5038_50380701_71_dialog_content = "（啊，厘青發抖得厲害，半年前的事故果然給他留下了很大的陰影。）",
  ui_story_5038_50380701_72_dialog_content = "那、那你就快上來吧！你別亂動啊，我把你和救生船吊上來……",
  ui_story_5038_50380701_73_dialog_content = "嘿……哈……",
  ui_story_5038_50380701_74_dialog_content = "嗚……",
  ui_story_5038_50380701_75_dialog_content = "你也太胡來了，怕水為什麼還硬要下去呢？",
  ui_story_5038_50380701_76_dialog_content = "我以為我自己一個人可以……",
  ui_story_5038_50380701_77_dialog_content = "咳咳，PlayerName，這樣的話，我可能還要拜託你一件事。",
  ui_story_5038_50380701_78_dialog_content = "知道了，我跟你一起坐著救生船下去，這樣就行了吧？",
  ui_story_5038_50380701_79_dialog_content = "其他人忙著修船沒有工夫，我們兩個快去快回。",
  ui_story_5038_50380701_80_dialog_content = "好！",
  ui_story_5038_50380701_81_dialog_content = "（那麼在出發之前，再確認一遍船上的安全措施……）",
  ui_story_5038_50380701_82_dialog_content = "嘎咕！！！",
  ui_story_5038_50380701_83_dialog_content = "太過分了……",
  ui_story_5038_50380701_84_dialog_content = "怎麼這麼一會的時間就順著吊繩爬上來了啊！",
  ui_story_5038_50380702_1_dialog_content = "聽好了朋友們，我想找一個像猴子腦袋一樣的東西。",
  ui_story_5038_50380702_2_dialog_content = "尺寸大約是這麼大，圓圓的、硬硬的。",
  ui_story_5038_50380702_3_dialog_content = "除此之外說不定上面還纏著些繩子……",
  ui_story_5038_50380702_X3_dialog_content = "原來，你的朋友是……這些魚嗎？",
  ui_story_5038_50380702_4_dialog_content = "唔……咳……",
  ui_story_5038_50380702_5_dialog_content = "怎麼樣，厘青？還是感覺噁心嗎？",
  ui_story_5038_50380702_6_dialog_content = "卜子曰，「醫者不能自醫」，說的應該就是我現在這副樣子吧。",
  ui_story_5038_50380702_7_dialog_content = "需要我做什麼來安慰你一下嗎？",
  ui_story_5038_50380702_8_dialog_content = "你要是問這個的話，撓撓下巴就是最好不過的了——",
  ui_story_5038_50380702_9_dialog_content = "但是！！！咳咳，撓下巴什麼的，都是小尾巴才喜歡的招式！",
  ui_story_5038_50380702_10_dialog_content = "我可不是什麼還沒化型的狸花貓，當然不會喜歡這種事情了。",
  ui_story_5038_50380702_11_dialog_content = "（還真是可愛呢……）",
  ui_story_5038_50380702_12_dialog_content = "說起來，PlayerName的故鄉那邊，是沒有「崇靈」的吧？",
  ui_story_5038_50380702_13_dialog_content = "唔，我倒是認識一些亞人血統的光靈朋友。",
  ui_story_5038_50380702_14_dialog_content = "他們多數是亞人和光靈的後代，在艾斯特拉大陸算是數量較為稀少的種族。",
  ui_story_5038_50380702_15_dialog_content = "原來如此，聽起來還是跟「崇靈」有所不同。",
  ui_story_5038_50380702_16_dialog_content = "PlayerName知道的吧，小尾巴其實是我的哥哥。",
  ui_story_5038_50380702_17_dialog_content = "哥、哥哥？！",
  ui_story_5038_50380702_18_dialog_content = "這樣的話，李天閑一直叫你「小貓咪」，也是因為你本來就是貓？",
  ui_story_5038_50380702_19_dialog_content = "他、他那樣叫我也太不尊重人了。",
  ui_story_5038_50380702_20_dialog_content = "但你說得沒錯，在龍洲，「崇靈」是一群由動物修煉而成的光靈。",
  ui_story_5038_50380702_21_dialog_content = "龍洲那些崇尚和諧的顯赫世家，還會時常邀請「崇靈」來家裡做客。",
  ui_story_5038_50380702_22_dialog_content = "這些客人，被稱為「清客」。",
  ui_story_5038_50380702_23_dialog_content = "我就是這樣認識的林家家主。",
  ui_story_5038_50380702_24_dialog_content = "看來林家家主是一位重視情誼的人啊。",
  ui_story_5038_50380702_25_dialog_content = "哎老實說，那群大人聊天時說的那些買賣交易，我是一個字也聽不懂。",
  ui_story_5038_50380702_26_dialog_content = "林家把我請來府上，是希望我能幫他們<color=#FFB400>照顧魚</color>。",
  ui_story_5038_50380702_27_dialog_content = "雖說貓吃魚已經是最尋常的世俗之見了，但海裡的魚，卻和我是朋友。",
  ui_story_5038_50380702_28_dialog_content = "你是說，你能跟那些螭龍魚溝通？",
  ui_story_5038_50380702_29_dialog_content = "算是吧。雖是這樣，但碰到那天晚上的緊急情況，我卻還是沒能幫上忙……",
  ui_story_5038_50380702_30_dialog_content = "唔，海裡的朋友們回應了。",
  ui_story_5038_50380702_31_dialog_content = "PlayerName，「猴頭」就在我們腳下。",
  ui_story_5038_50380702_32_dialog_content = "真的嗎？",
  ui_story_5038_50380702_33_dialog_content = "嗯，應該是被海草纏住了。",
  ui_story_5038_50380702_34_dialog_content = "稍等啊，我來把漁網放下去，然後再向上一撈……",
  ui_story_5038_50380702_35_dialog_content = "嘿、咻——",
  ui_story_5038_50380702_36_dialog_content = "你瞧，PlayerName。",
  ui_story_5038_50380702_37_dialog_content = "好、好厲害啊！",
  ui_story_5038_50380702_38_dialog_content = "簡直像變魔術一樣！",
  ui_story_5038_50380702_39_dialog_content = "我說過的吧，海裡的朋友能幫上忙的。",
  ui_story_5038_50380702_40_dialog_content = "有了這個新的「猴頭」，我們也能為修船提供些幫助了！",
  ui_story_5038_50380702_41_dialog_content = "嗯，那我們現在就回去吧！",
  ui_story_5038_50380702_42_dialog_content = "船上的大家一定也會感到振奮的。",
  ui_story_5038_50380702_43_dialog_content = "好。",
  ui_story_5038_50380702_44_dialog_content = "（不知道他的情況怎麼樣了……）",
  ui_story_5038_50380702_45_dialog_content = "<color=#e8d9bb>蜃風號 甲板</color>",
  ui_story_5038_50380702_46_dialog_content = "啊……厘青和PlayerName公子回來了！",
  ui_story_5038_50380702_47_dialog_content = "我就說，他們兩個人不會有事。",
  ui_story_5038_50380702_48_dialog_content = "呵呵，仲先生雖是這麼說，剛才可一下都沒有動筷子呢。",
  ui_story_5038_50380702_49_dialog_content = "PlayerName、厘青，你們太冒險了！",
  ui_story_5038_50380702_50_dialog_content = "你們出發之前有沒有想過後果？",
  ui_story_5038_50380702_51_dialog_content = "船長姐姐，妳看。",
  ui_story_5038_50380702_52_dialog_content = "……！",
  ui_story_5038_50380702_53_dialog_content = "「猴頭」？！",
  ui_story_5038_50380702_54_dialog_content = "被海水浸泡的痕跡非常明顯，但是清理一下的話基本還能夠使用。",
  ui_story_5038_50380702_55_dialog_content = "你們從哪裡找到的？",
  ui_story_5038_50380702_56_dialog_content = "從海裡！",
  ui_story_5038_50380702_57_dialog_content = "你們兩個偷偷下船了？",
  ui_story_5038_50380702_58_dialog_content = "這可是很危險的事情，現在大家都很忙，萬一發生意外沒人來得及救你們。",
  ui_story_5038_50380702_59_dialog_content = "你看，我們倆不是好好的嗎，什麼意外都沒有發生！",
  ui_story_5038_50380702_60_dialog_content = "哈哈，雖然有點冒險，但是結果是好的嘛。",
  ui_story_5038_50380702_61_dialog_content = "月白不是也說過，這場返航本來就是一種冒險。",
  ui_story_5038_50380702_62_dialog_content = "多虧厘青才找到了新的「猴頭」，應該誇誇他才對！",
  ui_story_5038_50380702_63_dialog_content = "你們……",
  ui_story_5038_50380702_64_dialog_content = "好吧，能找到新的「猴頭」確實對船隻修繕很有幫助，謝謝你們。",
  ui_story_5038_50380702_65_dialog_content = "但是擅自下船這種危險的事情以後別再做了。",
  ui_story_5038_50380702_66_dialog_content = "去吧，快吃飯去吧。",
  ui_story_5038_50380702_67_dialog_content = "是啊，快過來吧～",
  ui_story_5038_50380702_68_dialog_content = "趁剛才眾人忙碌之際，阿玖又準備了龍洲的菜式。",
  ui_story_5038_50380702_69_dialog_content = "哇，我正好也餓了！",
  ui_story_5038_50380702_70_dialog_content = "好香哇，丹棠殿下，今天難道吃紅燒肉嗎？",
  ui_story_5038_50380702_71_dialog_content = "好靈的鼻子，今天中午的主菜就是——<color=#FFB400>紅燒肉</color>！",
  ui_story_5038_50380702_72_dialog_content = "把方方正正的一塊好肉上捆，加入各色香料在鍋中燜煮……",
  ui_story_5038_50380702_73_dialog_content = "雖然船上的用料有限，但味道不比龍洲本土的差哦。",
  ui_story_5038_50380702_74_dialog_content = "你們先吃吧，我還有修繕工作要做。",
  ui_story_5038_50380702_75_dialog_content = "找到了新的「猴頭」，與桅杆相關聯的修復應該很快就能完成。",
  ui_story_5038_50380702_76_dialog_content = "蜃風號的航速馬上就要恢復正常了。",
  ui_story_5038_50380702_77_dialog_content = "我也去幫忙！",
  ui_story_5038_50380702_78_dialog_content = "<color=#e8d9bb>咕嚕……</color>",
  ui_story_5038_50380702_79_dialog_content = "呵呵，你還是先跟著他們進去吧。",
  ui_story_5038_50380702_80_dialog_content = "讓客人餓著肚子幫忙，也不是林家待客的規矩。",
  ui_story_5038_50380801_1_dialog_content = "（我們的航行速度恢復了，可船體狀況沒法讓人放心。）",
  ui_story_5038_50380801_2_dialog_content = "（大家一刻不停地忙碌著，好像任何一個停頓都會令蜃風沉沒。）",
  ui_story_5038_50380801_3_dialog_content = "（我們把疲勞當作焦慮的解藥。）",
  ui_story_5038_50380801_4_dialog_content = "船工，把船帆再往左轉一些，風向變了。",
  ui_story_5038_50380801_5_dialog_content = "是！",
  ui_story_5038_50380801_6_dialog_content = "貨艙的情況怎麼樣了？",
  ui_story_5038_50380801_7_dialog_content = "還在漏水，只能一直派人將水舀出去。",
  ui_story_5038_50380801_8_dialog_content = "所幸情況沒有加重，目前還應對得過來。",
  ui_story_5038_50380801_9_dialog_content = "我知道了。給大家排好班，輪流去休息。",
  ui_story_5038_50380801_10_dialog_content = "不知道這樣的狀況會持續多久，我們必須保持耐力。",
  ui_story_5038_50380801_11_dialog_content = "是！",
  ui_story_5038_50380801_12_dialog_content = "希望航向沒偏，我再去船頭看看。",
  ui_story_5038_50380801_13_dialog_content = "（月白一直在四處走，連說話都不曾停步。）",
  ui_story_5038_50380801_14_dialog_content = "（她是思忖最多的人，因而承受的壓力比我們更加具體。）",
  ui_story_5038_50380801_15_dialog_content = "（蜃風百孔千瘡，尚能被她的腳步聲填補。）",
  ui_story_5038_50380801_16_dialog_content = "又出現了……",
  ui_story_5038_50380801_17_dialog_content = "阿玖，我們數到多少了來著？",
  ui_story_5038_50380801_18_dialog_content = "數到四十二了，殿下。",
  ui_story_5038_50380801_19_dialog_content = "竟然這麼多了。",
  ui_story_5038_50380801_20_dialog_content = "它們出現在前行的方向上……好令人不安啊。",
  ui_story_5038_50380801_21_dialog_content = "（從今天早上開始，海面上出現了許多浮木。）",
  ui_story_5038_50380801_22_dialog_content = "（昨天找到的猴頭就像是冰山一角，引出了無數失事於此的殘骸。）",
  ui_story_5038_50380801_23_dialog_content = "（丹棠會在休息的時候靠在船舷上看海，一個個數著浮木的數量。）",
  ui_story_5038_50380801_24_dialog_content = "（對那些海上的棄兒來說，這就是唯一的一點關注了。）",
  ui_story_5038_50380801_25_dialog_content = "有什麼可不安的，我反倒覺得是好事。",
  ui_story_5038_50380801_26_dialog_content = "前面有船隻失事，說明我們走對了航線。",
  ui_story_5038_50380801_27_dialog_content = "不覺得空無一物的海面更可怕嗎？",
  ui_story_5038_50380801_28_dialog_content = "（厘青叼著魚幹從旁邊走了過去。）",
  ui_story_5038_50380801_29_dialog_content = "（他一直在幫忙，但是看起來又漫不經心。）",
  ui_story_5038_50380801_30_dialog_content = "（也許他只是拿幹活當消遣。）",
  ui_story_5038_50380801_31_dialog_content = "哎喲，可累死在下了。",
  ui_story_5038_50380801_32_dialog_content = "那貨艙裡的水啊，怎麼舀都舀不完。",
  ui_story_5038_50380801_33_dialog_content = "PlayerName，你也上來了？",
  ui_story_5038_50380801_34_dialog_content = "嗯，船工說讓我休息一會。",
  ui_story_5038_50380801_35_dialog_content = "（李天閑還是一樣，永遠是最健談的那個。）",
  ui_story_5038_50380801_36_dialog_content = "就是說呢，累壞了也不好。",
  ui_story_5038_50380801_37_dialog_content = "今天把水舀完了，明天還是會漏。",
  ui_story_5038_50380801_38_dialog_content = "這航海啊，得比大海有耐心。",
  ui_story_5038_50380801_39_dialog_content = "你還真是什麼時候都能講出道理啊。",
  ui_story_5038_50380801_40_dialog_content = "當然，在下得說服自己擺出平常心，日子長著呢。",
  ui_story_5038_50380801_41_dialog_content = "只要那位坐輪椅的大人還沒被逼著幹活，情況就不算太糟。",
  ui_story_5038_50380801_42_dialog_content = "看來有人嫌我遊手好閒了啊。",
  ui_story_5038_50380801_43_dialog_content = "哎呀呀呀！仲胥大人！",
  ui_story_5038_50380801_44_dialog_content = "難得您上甲板透氣來了！",
  ui_story_5038_50380801_45_dialog_content = "用不著把我當老爺供著，我在地上沒那個權勢，在船上更擔待不起。",
  ui_story_5038_50380801_46_dialog_content = "您這麼說就過謙了，老虎失了爪牙仍有三分威風，何況堂堂平野大將軍呢。",
  ui_story_5038_50380801_47_dialog_content = "好了好了，你牙尖嘴利。",
  ui_story_5038_50380801_48_dialog_content = "其實仲某有個想法，也許可以緩解如今的困局。",
  ui_story_5038_50380801_49_dialog_content = "若要實施，還需諸位助力。",
  ui_story_5038_50380801_50_dialog_content = "真的嗎！什麼辦法？",
  ui_story_5038_50380801_51_dialog_content = "我一定幫忙！",
  ui_story_5038_50380801_52_dialog_content = "仲胥大人雄才大略，在下必鼎力相助！",
  ui_story_5038_50380801_53_dialog_content = "不是什麼困難的事，我想拜託諸位幫我打撈些浮木上來。",
  ui_story_5038_50380801_54_dialog_content = "打撈浮木？",
  ui_story_5038_50380801_55_dialog_content = "聽起來是挺簡單的，用漁網就可以吧。",
  ui_story_5038_50380801_56_dialog_content = "是啊，面前這片海域，最不缺的就是浮木。",
  ui_story_5038_50380801_57_dialog_content = "並不是每塊浮木都有用，還請打撈我指定的那些。",
  ui_story_5038_50380801_58_dialog_content = "欸？這些浮木還有區別啊？",
  ui_story_5038_50380801_59_dialog_content = "先別問這些了，聽仲胥大人的準沒錯。",
  ui_story_5038_50380801_60_dialog_content = "我們去找船工取漁網吧。",
  ui_story_5038_50380801_61_dialog_content = "嗨……嗨……",
  ui_story_5038_50380801_62_dialog_content = "快拉上來了，再來一次！",
  ui_story_5038_50380801_63_dialog_content = "哈——",
  ui_story_5038_50380801_64_dialog_content = "<color=#e8d9bb>梆梆、梆——</color>",
  ui_story_5038_50380801_65_dialog_content = "呼，成功了！",
  ui_story_5038_50380801_66_dialog_content = "成功什麼啊？",
  ui_story_5038_50380801_67_dialog_content = "一網子下去半條魚都沒有，就一塊破木板也叫成功？",
  ui_story_5038_50380801_68_dialog_content = "厘青？沒有，這不是……",
  ui_story_5038_50380801_69_dialog_content = "是我讓他們撈木板上來的。",
  ui_story_5038_50380801_70_dialog_content = "啊？真是奇怪了，木板有什麼好撈的？",
  ui_story_5038_50380801_71_dialog_content = "你看他們撈上來的這塊，並不是尋常木板。",
  ui_story_5038_50380801_72_dialog_content = "在船體上，一般把它叫做「兔耳」。",
  ui_story_5038_50380801_73_dialog_content = "哦！這麼說來形狀真的像兔子耳朵呢。",
  ui_story_5038_50380801_74_dialog_content = "這就對了！仲胥大人的想法與在下不謀而合！",
  ui_story_5038_50380801_75_dialog_content = "「兔耳」正是我算出的三樣東西中最後一件！",
  ui_story_5038_50380801_76_dialog_content = "它是做什麼用的？",
  ui_story_5038_50380801_77_dialog_content = "它是裝在船舷外側的披水板，一艘船上往往只有兩塊。",
  ui_story_5038_50380801_78_dialog_content = "相比起船上其他木材，它的做工更加精緻，也擁有較強的防水性。",
  ui_story_5038_50380801_79_dialog_content = "所以我才要撈它上來。",
  ui_story_5038_50380801_80_dialog_content = "您是……看中了它的防水性？",
  ui_story_5038_50380801_81_dialog_content = "不錯。",
  ui_story_5038_50380801_82_dialog_content = "何謂「防水」？即是讓不該有水的地方，沒有水。",
  ui_story_5038_50380801_83_dialog_content = "不該有水……",
  ui_story_5038_50380801_84_dialog_content = "哦！我懂了！是船底的貨艙！",
  ui_story_5038_50380801_85_dialog_content = "您想用它們解決漏水的問題！",
  ui_story_5038_50380801_86_dialog_content = "小友果然聰慧。",
  ui_story_5038_50380801_87_dialog_content = "將「兔耳」覆在船底漏水處，再將其釘牢。",
  ui_story_5038_50380801_88_dialog_content = "雖只是臨時的補丁，但好歹能緩解些壓力，不至讓整船人焦頭爛額。",
  ui_story_5038_50380801_89_dialog_content = "妙哉，妙哉。用「兔耳」替其他部位解圍，移花接木。",
  ui_story_5038_50380801_90_dialog_content = "原來那一簽是這般意思！",
  ui_story_5038_50380801_91_dialog_content = "聽起來是個好辦法！",
  ui_story_5038_50380801_92_dialog_content = "真能把漏水問題解決的話，好多人都能騰出手幹其他事情了。",
  ui_story_5038_50380801_93_dialog_content = "快，我們再多撈幾塊！",
  ui_story_5038_50380801_94_dialog_content = "我盯著呢，PlayerName。",
  ui_story_5038_50380801_95_dialog_content = "看那邊，又一塊「兔耳」。",
  ui_story_5038_50380801_96_dialog_content = "快，快點下網！",
  ui_story_5038_50380801_97_dialog_content = "水又上來了？",
  ui_story_5038_50380801_98_dialog_content = "對，真是一刻都走不開啊。",
  ui_story_5038_50380801_99_dialog_content = "別愣神了，快幫著往外舀。",
  ui_story_5038_50380801_100_dialog_content = "哦哦，好……",
  ui_story_5038_50380801_101_dialog_content = "喂，有沒有人幫忙搭把手啊。",
  ui_story_5038_50380801_102_dialog_content = "嗯？是厘青的聲音。",
  ui_story_5038_50380801_103_dialog_content = "快點接一下，我要扛不住了！",
  ui_story_5038_50380801_104_dialog_content = "好，我來了！要接什麼……",
  ui_story_5038_50380801_105_dialog_content = "<color=#e8d9bb>梆梆、梆——</color>",
  ui_story_5038_50380801_106_dialog_content = "咦？！",
  ui_story_5038_50380801_107_dialog_content = "哎喲，實在是太沉了。",
  ui_story_5038_50380801_108_dialog_content = "不過送到這裡就算是完成任務了。",
  ui_story_5038_50380801_109_dialog_content = "厘青，你怎麼扛著塊木板過來了？",
  ui_story_5038_50380801_110_dialog_content = "都怪仲胥，非讓我做這苦差事。",
  ui_story_5038_50380801_111_dialog_content = "他說木板可以封住漏水的地方。",
  ui_story_5038_50380801_112_dialog_content = "木板？從海裡撈上來的嗎？",
  ui_story_5038_50380801_113_dialog_content = "那些東西恐怕早就被海水泡爛了，派不上用場的。",
  ui_story_5038_50380801_114_dialog_content = "泡爛了倒不至於，它沉得很呢。",
  ui_story_5038_50380801_115_dialog_content = "你摸摸？",
  ui_story_5038_50380801_116_dialog_content = "是你力氣太小吧，一塊木板都搬不動。",
  ui_story_5038_50380801_117_dialog_content = "讓我看看——",
  ui_story_5038_50380801_118_dialog_content = "等一下？！這是「兔耳」？",
  ui_story_5038_50380801_119_dialog_content = "怎麼樣，對它刮目相看了吧。",
  ui_story_5038_50380801_120_dialog_content = "「兔耳」……對，「兔耳」說不定真的能用。",
  ui_story_5038_50380801_121_dialog_content = "錘子呢？給我把錘子拿來！",
  ui_story_5038_50380801_122_dialog_content = "三、二、一——",
  ui_story_5038_50380801_123_dialog_content = "<color=#e8d9bb>梆梆、梆——</color>",
  ui_story_5038_50380801_124_dialog_content = "哦！又撈上來一塊！",
  ui_story_5038_50380801_125_dialog_content = "嗨，輕輕鬆鬆。",
  ui_story_5038_50380801_126_dialog_content = "輕、輕鬆嗎？你讓我喘口氣……",
  ui_story_5038_50380801_127_dialog_content = "你們在做什麼呢？",
  ui_story_5038_50380801_128_dialog_content = "船長大人！您也看見了，我們在打撈海裡的木板。",
  ui_story_5038_50380801_129_dialog_content = "仲胥大人說了，這些沉船的「兔耳」也許能給漏水的地方打個補丁。",
  ui_story_5038_50380801_130_dialog_content = "「兔耳」……",
  ui_story_5038_50380801_131_dialog_content = "成功了！漏水的地方真的能被「兔耳」補上！",
  ui_story_5038_50380801_132_dialog_content = "哇，厘青回來了！成功了嗎！",
  ui_story_5038_50380801_133_dialog_content = "嗯，剛才搬下去那塊「兔耳」，已經堵上了一處漏水的地方。",
  ui_story_5038_50380801_134_dialog_content = "不過船底漏水處還有許多，船工說急需更多「兔耳」。",
  ui_story_5038_50380801_135_dialog_content = "你們別閒著呀，再去多撈點上來！",
  ui_story_5038_50380801_136_dialog_content = "知道了知道了，我這就去……",
  ui_story_5038_50380801_137_dialog_content = "不勞煩諸位了，請去旁邊休息吧。",
  ui_story_5038_50380801_138_dialog_content = "既然真的有效，我會安排船工來打撈「兔耳」。",
  ui_story_5038_50380801_139_dialog_content = "讓客人累死累活可不是蜃風的待客之道。",
  ui_story_5038_50380801_140_dialog_content = "來，用力！",
  ui_story_5038_50380801_141_dialog_content = "嘿——咻！",
  ui_story_5038_50380801_142_dialog_content = "<color=#e8d9bb>梆梆、梆——</color>",
  ui_story_5038_50380801_143_dialog_content = "這邊也有一塊！",
  ui_story_5038_50380801_144_dialog_content = "<color=#e8d9bb>梆梆、梆——</color>",
  ui_story_5038_50380801_145_dialog_content = "把這幾塊搬下去！",
  ui_story_5038_50380801_146_dialog_content = "釘子不夠了，再取一些過來。",
  ui_story_5038_50380801_147_dialog_content = "別急別急，一個個走！",
  ui_story_5038_50380801_148_dialog_content = "大家都來幫忙之後，效率提高了好多啊。",
  ui_story_5038_50380801_149_dialog_content = "已經數不清撈上來多少塊「兔耳」了。",
  ui_story_5038_50380801_150_dialog_content = "看這架勢，今天之內就能把船底補好吧！",
  ui_story_5038_50380801_151_dialog_content = "咦，這塊「兔耳」……",
  ui_story_5038_50380801_152_dialog_content = "老劉，你過來看看。",
  ui_story_5038_50380801_153_dialog_content = "怎麼了？它有問題？",
  ui_story_5038_50380801_154_dialog_content = "不是，我看它有些眼熟。",
  ui_story_5038_50380801_155_dialog_content = "哦！你這麼說還真是！",
  ui_story_5038_50380801_156_dialog_content = "這不是六哥的漁船嗎！",
  ui_story_5038_50380801_157_dialog_content = "嗯……我記得他春天出海，說要去遠海捕魚，然後就再沒了消息。",
  ui_story_5038_50380801_158_dialog_content = "沒想到會在這看到……",
  ui_story_5038_50380801_159_dialog_content = "欸？他們是……認出了失事的船隻？",
  ui_story_5038_50380801_160_dialog_content = "嗯。",
  ui_story_5038_50380801_161_dialog_content = "只憑一塊木板就能分辨出來嗎……",
  ui_story_5038_50380801_162_dialog_content = "「兔耳」是船上一個很特殊的部件。",
  ui_story_5038_50380801_163_dialog_content = "每艘船上只有兩塊，位置又比較顯眼。",
  ui_story_5038_50380801_164_dialog_content = "船主人喜歡為它刻上自己喜歡的花紋來代表這艘船隻。",
  ui_story_5038_50380801_165_dialog_content = "原來如此，他們是靠花紋認出來的！",
  ui_story_5038_50380801_166_dialog_content = "對於經常出海的龍洲人來說，這是一種普遍的習慣。",
  ui_story_5038_50380801_167_dialog_content = "我看月白船長也盯著那些「兔耳」端詳了許久。",
  ui_story_5038_50380801_168_dialog_content = "想必你能認出來的船隻，比船工更多吧。",
  ui_story_5038_50380801_169_dialog_content = "嗯……",
  ui_story_5038_50380801_170_dialog_content = "有幾艘是客船，夏天撞上了海上的颱風，沒能返回港口。",
  ui_story_5038_50380801_171_dialog_content = "它們的「兔耳」裝飾得很招搖，一眼就能認出來。",
  ui_story_5038_50380801_172_dialog_content = "漁船的數量很少，因為漁民們知道遠海的厲害。",
  ui_story_5038_50380801_173_dialog_content = "不過今年行情不好，還是有人選擇鋌而走險。",
  ui_story_5038_50380801_174_dialog_content = "最多的是商船。",
  ui_story_5038_50380801_175_dialog_content = "他們覬覦著遠方大陸的利益，一次次嘗試跟隨蜃風舊船出海。",
  ui_story_5038_50380801_176_dialog_content = "但時至今日，能平安往返於兩片大陸之間的，仍只有蜃風。",
  ui_story_5038_50380801_177_dialog_content = "啊……",
  ui_story_5038_50380801_178_dialog_content = "我好像剛反應過來打撈「兔耳」是多沉重的事情……",
  ui_story_5038_50380801_179_dialog_content = "一艘船只有兩塊「兔耳」。",
  ui_story_5038_50380801_180_dialog_content = "換句話說，每撈上來兩塊「兔耳」，就見證了一艘船的沉沒。",
  ui_story_5038_50380801_181_dialog_content = "有的能被認出來，一下子牽動某人的回憶。",
  ui_story_5038_50380801_182_dialog_content = "而那些不被人認出來的，只是默默將數字疊高。",
  ui_story_5038_50380801_183_dialog_content = "是啊，我們已經撈起了那麼多「兔耳」……",
  ui_story_5038_50380801_184_dialog_content = "這就是航海最原始的樣子。",
  ui_story_5038_50380801_185_dialog_content = "大海無所依憑，前人便成為後人的依憑。",
  ui_story_5038_50380801_186_dialog_content = "我們的船底快補好了。",
  ui_story_5038_50380801_187_dialog_content = "這是商船，這是漁船，這是商船。",
  ui_story_5038_50380801_188_dialog_content = "然後這是商船，又一艘商船……",
  ui_story_5038_50380801_189_dialog_content = "丹棠，妳在寫什麼呢？",
  ui_story_5038_50380801_190_dialog_content = "哦，我呀，我在統計這些「兔耳」所屬的船隻。",
  ui_story_5038_50380801_191_dialog_content = "船長說，回到龍洲之後，多少算是給它們一個交代。",
  ui_story_5038_50380801_192_dialog_content = "原來是這樣……",
  ui_story_5038_50380801_193_dialog_content = "搬去貨艙的我應該統計完了，還有新撈上來的「兔耳」嗎？",
  ui_story_5038_50380801_194_dialog_content = "沒有了，我們剛剛駛出了遍布浮木的海域。",
  ui_story_5038_50380801_195_dialog_content = "而且，現在這些已經夠用了。",
  ui_story_5038_50380801_196_dialog_content = "船底貨艙被修補得差不多了，大家正在進行最後的收尾工作。",
  ui_story_5038_50380801_197_dialog_content = "這樣啊，那也不錯，看起來我可以收工了。",
  ui_story_5038_50380801_198_dialog_content = "可惜的是沒幫大家找到什麼線索。",
  ui_story_5038_50380801_199_dialog_content = "線索？",
  ui_story_5038_50380801_200_dialog_content = "嗯，本來想試著找找「羅盤」的線索。",
  ui_story_5038_50380801_201_dialog_content = "我看這些沉船裡，許多都是當年與蜃風舊船同行的商船。",
  ui_story_5038_50380801_202_dialog_content = "既然都是在海上落難，也許蜃風舊船的「兔耳」也能被撈起。",
  ui_story_5038_50380801_203_dialog_content = "現在看來，還是我想得太簡單了。",
  ui_story_5038_50380801_204_dialog_content = "說得對哦，蜃風舊船的線索說不定就藏在那些殘骸裡面。",
  ui_story_5038_50380801_205_dialog_content = "既然「羅盤」如此重要，是不是該仔細找找？",
  ui_story_5038_50380801_206_dialog_content = "要去跟船長說說嗎？",
  ui_story_5038_50380801_207_dialog_content = "可是……現在想來，仲胥從不在意那些「兔耳」的所屬。",
  ui_story_5038_50380801_208_dialog_content = "也許，他是認定蜃風舊船不在其中的。",
  ui_story_5038_50380801_209_dialog_content = "不在其中？這該怎麼認定？",
  ui_story_5038_50380801_210_dialog_content = "比如說，蜃風舊船的「兔耳」形狀特殊，隔著很遠就能看見？",
  ui_story_5038_50380801_211_dialog_content = "好像有些誇張。",
  ui_story_5038_50380801_212_dialog_content = "茫茫海面上，動輒相隔百里，任誰也沒法一眼看個清楚。",
  ui_story_5038_50380801_213_dialog_content = "嗯，不對。要麼是蜃風舊船上沒有「兔耳」？",
  ui_story_5038_50380801_214_dialog_content = "也不對，就算真有特例也該找找看其他部位的殘骸。",
  ui_story_5038_50380801_215_dialog_content = "但是，仲胥對殘骸根本就沒有興趣……",
  ui_story_5038_50380801_216_dialog_content = "難道說……",
  ui_story_5038_50380801_217_dialog_content = "殘骸中找不到蜃風舊船的痕跡很正常啊。",
  ui_story_5038_50380801_218_dialog_content = "因為它還未化作殘骸呢。",
  ui_story_5038_50380801_219_dialog_content = "欸？！厘青你、你從哪冒出來的！",
  ui_story_5038_50380801_220_dialog_content = "未化作殘骸……",
  ui_story_5038_50380801_221_dialog_content = "失事和沉沒是不一樣的。",
  ui_story_5038_50380801_222_dialog_content = "你想想，護航船平安的寶貝「羅盤」就在上面，它怎麼會沉沒呢。",
  ui_story_5038_50380801_223_dialog_content = "「羅盤」有這麼神奇？",
  ui_story_5038_50380801_224_dialog_content = "那當然啦，不然就犯不上讓這麼多人挖空腦筋去找它了。",
  ui_story_5038_50380801_225_dialog_content = "好了好了，現在不是說這種事的時候。",
  ui_story_5038_50380801_226_dialog_content = "馬上要開飯了，全船人都在等你們呢。",
  ui_story_5038_50380801_227_dialog_content = "快跟我過去吧。",
  ui_story_5038_50380801_228_dialog_content = "全船人？！大家要一起吃飯嗎？",
  ui_story_5038_50380801_229_dialog_content = "是啊，修補工作已經完成，難得有大家一起休息的時候。",
  ui_story_5038_50380801_230_dialog_content = "你們可不許掃興啊，連我老哥仲胥都去了。",
  ui_story_5038_50380801_231_dialog_content = "快點快點！",
  ui_story_5038_50380801_232_dialog_content = "哎喲，您幾位總算是過來了！",
  ui_story_5038_50380801_233_dialog_content = "等到上菜才出現，聞著味來的吧！",
  ui_story_5038_50380801_234_dialog_content = "這邊坐這邊坐！",
  ui_story_5038_50380801_235_dialog_content = "哇好熱鬧！",
  ui_story_5038_50380801_236_dialog_content = "哇好香！",
  ui_story_5038_50380801_237_dialog_content = "那可不，後廚使出了渾身解數。",
  ui_story_5038_50380801_238_dialog_content = "不然怎麼叫「慶功宴」呢。",
  ui_story_5038_50380801_239_dialog_content = "慶功宴？",
  ui_story_5038_50380801_240_dialog_content = "是啊，慶祝我們蜃風修復如常，航行回到正軌。",
  ui_story_5038_50380801_241_dialog_content = "不對，這話不該我說。船長，您來說兩句吧！",
  ui_story_5038_50380801_242_dialog_content = "我？我……",
  ui_story_5038_50380801_243_dialog_content = "對不起，我不擅長說這些話。",
  ui_story_5038_50380801_244_dialog_content = "大家就……開開心心吃飯吧。",
  ui_story_5038_50380801_245_dialog_content = "只要是船上有的東西，今天想吃什麼都可以。",
  ui_story_5038_50380801_246_dialog_content = "真的嗎！那我想吃倉庫裡的臘肉！",
  ui_story_5038_50380801_247_dialog_content = "天天吃魚已經吃膩了！",
  ui_story_5038_50380801_248_dialog_content = "喂，魚有什麼不好的？",
  ui_story_5038_50380801_249_dialog_content = "不想吃的話全留給我吃！",
  ui_story_5038_50380801_250_dialog_content = "仲胥大人，您坐得離大家好遠。",
  ui_story_5038_50380801_251_dialog_content = "需要我為您端些菜品過來嗎？",
  ui_story_5038_50380801_252_dialog_content = "不必了，坐在這清清靜靜的剛好。",
  ui_story_5038_50380801_253_dialog_content = "看來您不喜歡宴會的吵鬧。",
  ui_story_5038_50380801_254_dialog_content = "沒有，我挺喜歡的。",
  ui_story_5038_50380801_255_dialog_content = "在我為官的時候，也曾參與過許多宴會。",
  ui_story_5038_50380801_256_dialog_content = "只是退下來之後發現，那些喧囂是更宜擺在遠處觀瞧的景。",
  ui_story_5038_50380801_257_dialog_content = "坐在這裡把所有人的情緒納入眼中，我比那些歡呼的人更加享受。",
  ui_story_5038_50380801_258_dialog_content = "是嗎？大人的意思好難以捉摸……",
  ui_story_5038_50380801_259_dialog_content = "阿玖！原來妳在這啊！",
  ui_story_5038_50380801_260_dialog_content = "小、小姐！您嚇著我了……",
  ui_story_5038_50380801_261_dialog_content = "那邊的船工說要一起跳舞，妳去不去？",
  ui_story_5038_50380801_262_dialog_content = "阿玖跳舞最好看了！",
  ui_story_5038_50380801_263_dialog_content = "小姐謬贊了，我的舞步上不了台面……",
  ui_story_5038_50380801_264_dialog_content = "那就一起吃東西去！他們正在上菜呢！",
  ui_story_5038_50380801_265_dialog_content = "待會好菜全被搶光了！",
  ui_story_5038_50380801_266_dialog_content = "哈哈，丹棠妳看起來好亢奮啊。",
  ui_story_5038_50380801_267_dialog_content = "嗯！因為我真的很開心！",
  ui_story_5038_50380801_268_dialog_content = "你看，頭頂的帆是我們自己支起來的，腳下的船是我們自己修補好的。",
  ui_story_5038_50380801_269_dialog_content = "不覺得這樣很幸福嗎？",
  ui_story_5038_50380801_270_dialog_content = "我們構成了這一次航行，我們都屬於同一條船。",
  ui_story_5038_50380801_271_dialog_content = "嗯，你說得對。我好像也對蜃風產生歸屬感了。",
  ui_story_5038_50380801_272_dialog_content = "是吧，這是只有我們這樣的乘客才能共情的感受。",
  ui_story_5038_50380801_273_dialog_content = "當然了，還有另一層快樂是船上所有人都能懂的。",
  ui_story_5038_50380801_274_dialog_content = "你看大家。",
  ui_story_5038_50380801_275_dialog_content = "真不容易啊，忙活了這麼長時間。",
  ui_story_5038_50380801_276_dialog_content = "睡不好覺的日子總算要結束了。",
  ui_story_5038_50380801_277_dialog_content = "是啊，明天不用再修理桅杆，也不用再去船底舀水。",
  ui_story_5038_50380801_278_dialog_content = "我們終於能回到龍洲了。",
  ui_story_5038_50380901_1_dialog_content = "<color=#e8d9bb>五天後</color>",
  ui_story_5038_50380901_2_dialog_content = "船長，全船的部件都檢查完了，沒什麼問題。",
  ui_story_5038_50380901_3_dialog_content = "貨艙還是有輕微的漏水，不過相比昨天並沒有加重。",
  ui_story_5038_50380901_4_dialog_content = "明白了，沒問題就好。",
  ui_story_5038_50380901_5_dialog_content = "受潮的貨物處理掉了嗎？",
  ui_story_5038_50380901_6_dialog_content = "處理掉了，完全不能用的全都丟進了海裡，受潮不嚴重的正在甲板上曬乾。",
  ui_story_5038_50380901_7_dialog_content = "但是……經過處理之後，我們剩下的食物不多了。",
  ui_story_5038_50380901_8_dialog_content = "食物啊……",
  ui_story_5038_50380901_9_dialog_content = "水呢？我們的淡水還有多少？",
  ui_story_5038_50380901_10_dialog_content = "淡水要多一些，能用半個月左右。",
  ui_story_5038_50380901_11_dialog_content = "船長，我們距離靠岸還有多久？",
  ui_story_5038_50380901_12_dialog_content = "對不起，現在還無法判斷。",
  ui_story_5038_50380901_13_dialog_content = "大洋腹地的海圖並不不完整，中途又遭遇了一場襲擊。",
  ui_story_5038_50380901_14_dialog_content = "我們陷入了海圖中的空白地帶，方向和距離都只能依靠估量。",
  ui_story_5038_50380901_15_dialog_content = "最近讓大家多從海裡打魚吃吧，屯儲的食物省著點用。",
  ui_story_5038_50380901_16_dialog_content = "淡水也是，飲用之外的用途盡量控制。",
  ui_story_5038_50380901_17_dialog_content = "去吧。",
  ui_story_5038_50380901_18_dialog_content = "……是，船長。",
  ui_story_5038_50380901_19_dialog_content = "<color=#e8d9bb>又五天後</color>",
  ui_story_5038_50380901_20_dialog_content = "今天的午飯又變少了啊。",
  ui_story_5038_50380901_21_dialog_content = "是的，這也是沒辦法的事情。",
  ui_story_5038_50380901_22_dialog_content = "厘青吃飽了嗎？",
  ui_story_5038_50380901_23_dialog_content = "不只是吃不飽，甚至一口都沒吃到。",
  ui_story_5038_50380901_24_dialog_content = "我的那份全餵給小尾巴了。",
  ui_story_5038_50380901_25_dialog_content = "哎呀，那怎麼行，不吃飯該長不高了。",
  ui_story_5038_50380901_26_dialog_content = "你、你們的觀念好老土！只有長得高才好嗎？",
  ui_story_5038_50380901_27_dialog_content = "我去甲板上看看。",
  ui_story_5038_50380901_28_dialog_content = "要是運氣好的話，你晚上就有魚吃了。",
  ui_story_5038_50380901_29_dialog_content = "有魚吃！真的喵！",
  ui_story_5038_50380901_30_dialog_content = "嗯！運氣好的話。",
  ui_story_5038_50380901_31_dialog_content = "我……我打魚技術不太好。",
  ui_story_5038_50380901_32_dialog_content = "總之你……等我……",
  ui_story_5038_50380901_33_dialog_content = "你怎麼了？好像站不穩的樣子。",
  ui_story_5038_50380901_34_dialog_content = "欸？沒有……",
  ui_story_5038_50380901_35_dialog_content = "把手給我。",
  ui_story_5038_50380901_36_dialog_content = "那個，我……",
  ui_story_5038_50380901_37_dialog_content = "你生病了。",
  ui_story_5038_50380901_38_dialog_content = "<color=#e8d9bb>又五天後</color>",
  ui_story_5038_50380901_39_dialog_content = "小尾巴，別亂跑！",
  ui_story_5038_50380901_40_dialog_content = "掉到海裡去了可怎麼辦！",
  ui_story_5038_50380901_41_dialog_content = "喵。",
  ui_story_5038_50380901_42_dialog_content = "別嫌我多管閒事啊，你看現在這麼大的風。",
  ui_story_5038_50380901_43_dialog_content = "誰知道會不會突然一下子把你吹飛呢。",
  ui_story_5038_50380901_44_dialog_content = "快跟我回船艙去。",
  ui_story_5038_50380901_45_dialog_content = "喵嗚——",
  ui_story_5038_50380901_46_dialog_content = "呼，呼。好能跑啊，追不上牠。",
  ui_story_5038_50380901_47_dialog_content = "別擔心了，動物對危險的感知比人要敏銳。",
  ui_story_5038_50380901_48_dialog_content = "真等危險來臨的時候，反而是人要依靠牠們。",
  ui_story_5038_50380901_49_dialog_content = "哦！月白妳也在這呢！",
  ui_story_5038_50380901_50_dialog_content = "妳看見過厘青嗎？今天他一直沒露面。",
  ui_story_5038_50380901_51_dialog_content = "要是他在的話，我也不會擔心小尾巴亂跑。",
  ui_story_5038_50380901_52_dialog_content = "他去照顧病人了。",
  ui_story_5038_50380901_53_dialog_content = "昨天又有兩個船工生病倒下，似乎是得了熱病。",
  ui_story_5038_50380901_54_dialog_content = "辛苦他了。",
  ui_story_5038_50380901_55_dialog_content = "又有人生病……",
  ui_story_5038_50380901_56_dialog_content = "月白，我們還要多久才能抵達龍洲啊？",
  ui_story_5038_50380901_57_dialog_content = "……",
  ui_story_5038_50380901_58_dialog_content = "我……不知道……",
  ui_story_5038_50380901_59_dialog_content = "（我突然在她身上看到一股堅硬的悲哀。）",
  ui_story_5038_50380901_60_dialog_content = "（也許這個問題根本就沒有答案。）",
  ui_story_5038_50380901_61_dialog_content = "（我們可以去問月白，可是月白該去問誰呢？）",
  ui_story_5038_50380901_62_dialog_content = "海面很大，我看不到龍洲那麼遠的地方。",
  ui_story_5038_50380901_63_dialog_content = "我只能看到一些很近的東西。",
  ui_story_5038_50380901_64_dialog_content = "回船艙去吧，風暴要來了。",
  ui_story_5038_50380901_65_dialog_content = "<color=#e8d9bb>次日</color>",
  ui_story_5038_50380901_66_dialog_content = "船長，甲板上的東西收拾完畢，船員也全都安頓好了。",
  ui_story_5038_50380901_67_dialog_content = "壓艙物檢查了嗎？",
  ui_story_5038_50380901_68_dialog_content = "檢查過了，重量沒問題，應該禁得起風浪。",
  ui_story_5038_50380901_69_dialog_content = "好，準備工作這樣就差不多了。",
  ui_story_5038_50380901_70_dialog_content = "你去船尾等我的命令吧。",
  ui_story_5038_50380901_71_dialog_content = "呃……等一下船長，船帆是不是該收了？",
  ui_story_5038_50380901_72_dialog_content = "不用收，把它迎風張到最大。",
  ui_story_5038_50380901_73_dialog_content = "要在風暴裡滿帆行船嗎？！",
  ui_story_5038_50380901_74_dialog_content = "這、這太危險了！我們會控制不住船身的！",
  ui_story_5038_50380901_75_dialog_content = "而且……說不定會有暗鬼乘著浪頭來到船上，就像之前那樣！",
  ui_story_5038_50380901_76_dialog_content = "我知道，但是我們等不起了。",
  ui_story_5038_50380901_77_dialog_content = "追趕著我們的不只是大海，還有時間。",
  ui_story_5038_50380901_78_dialog_content = "一旦蜃風停下，恐怕就徹底失去了靠岸的機會。",
  ui_story_5038_50380901_79_dialog_content = "這……",
  ui_story_5038_50380901_80_dialog_content = "我們只能乘上每一陣風，哪怕它是一場風暴。",
  ui_story_5038_50380901_81_dialog_content = "至於暗鬼，要是牠們真敢趁機登上甲板，該害怕的是牠們。",
  ui_story_5038_50380901_82_dialog_content = "有不少乘客正有力沒處使呢。",
  ui_story_5038_50380901_83_dialog_content = "既然您這麼說了……",
  ui_story_5038_50380901_84_dialog_content = "哎，不管了！我是船工，我聽船長的！",
  ui_story_5038_50380901_85_dialog_content = "好，立刻去船尾就位。",
  ui_story_5038_50380901_86_dialog_content = "海浪很快就會打過來，隨時聽我命令。",
  ui_story_5038_50380901_87_dialog_content = "是！！！",
  ui_story_5038_50381001_1_dialog_content = "（蜃風在風暴裡顛簸了一整天。）",
  ui_story_5038_50381001_2_dialog_content = "（我們遭遇了不少麻煩，暈船、磕碰還有暗鬼。）",
  ui_story_5038_50381001_3_dialog_content = "（不過就在剛剛，狂風撕扯船帆的可怕聲音漸漸小了下去。）",
  ui_story_5038_50381001_4_dialog_content = "（我們都知道，蜃風挺過來了。）",
  ui_story_5038_50381001_5_dialog_content = "甲板上好像沒什麼危險了欸。",
  ui_story_5038_50381001_6_dialog_content = "看起來是的，我們已經穿過風暴了嗎？",
  ui_story_5038_50381001_7_dialog_content = "嗯，最艱難的一段行程已經扛過去了。",
  ui_story_5038_50381001_8_dialog_content = "接下來會有些小風小浪，別大意就好。",
  ui_story_5038_50381001_9_dialog_content = "謝天謝地，可算是結束了。",
  ui_story_5038_50381001_10_dialog_content = "再搖晃下去，在下這五臟六腑都要翻個底朝天了。",
  ui_story_5038_50381001_11_dialog_content = "你還好嗎李天閑？臉色很差的樣子。",
  ui_story_5038_50381001_12_dialog_content = "還行，來甲板上透透氣舒服了許多。",
  ui_story_5038_50381001_13_dialog_content = "船長，我們是不是該開頓飯了？",
  ui_story_5038_50381001_14_dialog_content = "在風暴裡顛三倒四的一整天沒吃上東西，身體吃不消啊。",
  ui_story_5038_50381001_15_dialog_content = "嗯，你說得對。",
  ui_story_5038_50381001_16_dialog_content = "船工，去叫廚房準備晚飯吧。",
  ui_story_5038_50381001_17_dialog_content = "好。",
  ui_story_5038_50381001_18_dialog_content = "不過……船長，剩下的糧食不多，要按日子分。",
  ui_story_5038_50381001_19_dialog_content = "您得告訴我航行還剩幾日啊。",
  ui_story_5038_50381001_20_dialog_content = "……目前尚無定數。",
  ui_story_5038_50381001_21_dialog_content = "今日先讓大家吃飽。",
  ui_story_5038_50381001_22_dialog_content = "不，七成飽吧。",
  ui_story_5038_50381001_23_dialog_content = "喂，我們還有多少糧食？",
  ui_story_5038_50381001_24_dialog_content = "……",
  ui_story_5038_50381001_25_dialog_content = "你肯定知道，跟我說說唄。",
  ui_story_5038_50381001_26_dialog_content = "我明白，情況一定不好，就是想心裡有個底。",
  ui_story_5038_50381001_27_dialog_content = "不能這麼下去了。",
  ui_story_5038_50381001_28_dialog_content = "啊？",
  ui_story_5038_50381001_29_dialog_content = "走，叫大家一起抓魚去。",
  ui_story_5038_50381001_30_dialog_content = "現在嗎？可是我還有活沒幹完……",
  ui_story_5038_50381001_31_dialog_content = "不重要的活先放一邊。",
  ui_story_5038_50381001_32_dialog_content = "接下來，讓大家多騰出時間抓魚。",
  ui_story_5038_50381001_33_dialog_content = "不然的話，過幾天可不只是吃不飽了。",
  ui_story_5038_50381001_34_dialog_content = "這麼嚴重……",
  ui_story_5038_50381001_35_dialog_content = "好，我去把船工們都叫來。",
  ui_story_5038_50381001_36_dialog_content = "這邊收網了！",
  ui_story_5038_50381001_37_dialog_content = "快，幫忙往上拽一下！",
  ui_story_5038_50381001_38_dialog_content = "嘿、咻——",
  ui_story_5038_50381001_39_dialog_content = "怎麼船工們都來甲板上抓魚了！",
  ui_story_5038_50381001_40_dialog_content = "是……食物的原因嗎？",
  ui_story_5038_50381001_41_dialog_content = "肯定啊，吃不飽飯是最原始的焦慮。",
  ui_story_5038_50381001_42_dialog_content = "船被大家修好了，可人能扛得住嗎？",
  ui_story_5038_50381001_43_dialog_content = "哎……",
  ui_story_5038_50381001_44_dialog_content = "該說幸好這裡是海上嗎，至少魚是取之不盡的。",
  ui_story_5038_50381001_45_dialog_content = "沒那麼簡單。",
  ui_story_5038_50381001_46_dialog_content = "就算大家願意每天吃魚，可淡水也在一天天減少。",
  ui_story_5038_50381001_47_dialog_content = "等它消耗沒了，這場航行就會徹底失去希望。",
  ui_story_5038_50381001_48_dialog_content = "人啊，終究是陸地上的動物。",
  ui_story_5038_50381001_49_dialog_content = "一旦入了大海，每一天都在倒數。",
  ui_story_5038_50381001_50_dialog_content = "倒數……",
  ui_story_5038_50381001_51_dialog_content = "不知道我們的時間還剩多少。",
  ui_story_5038_50381001_52_dialog_content = "又抓到一條！這條好大的力氣！",
  ui_story_5038_50381001_53_dialog_content = "都過來都過來，一起往上面拽！",
  ui_story_5038_50381001_54_dialog_content = "三、二、一——",
  ui_story_5038_50381001_55_dialog_content = "<color=#e8d9bb>嘭——</color>",
  ui_story_5038_50381001_56_dialog_content = "哇這條也太大了！",
  ui_story_5038_50381001_57_dialog_content = "哈哈哈哈！這下發了！",
  ui_story_5038_50381001_58_dialog_content = "好傢伙，夠五六個人吃了吧！",
  ui_story_5038_50381001_59_dialog_content = "哇真的好大！",
  ui_story_5038_50381001_60_dialog_content = "哦喲！在下還從沒見過這麼大的魚！",
  ui_story_5038_50381001_61_dialog_content = "走走走，趕緊拿去廚房。",
  ui_story_5038_50381001_62_dialog_content = "今天晚飯沒吃飽，現在就給大家加餐！",
  ui_story_5038_50381001_63_dialog_content = "<size=50>好！！！</size>",
  ui_story_5038_50381001_64_dialog_content = "把牠放了。",
  ui_story_5038_50381001_65_dialog_content = "啊？誰？！",
  ui_story_5038_50381001_66_dialog_content = "是我，我讓你把牠放了。",
  ui_story_5038_50381001_67_dialog_content = "仲胥大人？你……",
  ui_story_5038_50381001_68_dialog_content = "我老哥說得沒錯，快點把牠放了。",
  ui_story_5038_50381001_69_dialog_content = "你仔細看看，那可是螭龍魚！",
  ui_story_5038_50381001_70_dialog_content = "螭龍魚？！",
  ui_story_5038_50381001_X70_dialog_content = "糟了，剛才沒有注意，這不就是之前襲擊我們的……",
  ui_story_5038_50381001_71_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5038_50381001_72_dialog_content = "哎喲喲喲——",
  ui_story_5038_50381001_73_dialog_content = "嗚哇——",
  ui_story_5038_50381001_74_dialog_content = "怎麼回事？船被撞了嗎？！",
  ui_story_5038_50381001_75_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5038_50381001_76_dialog_content = "又、又來了！",
  ui_story_5038_50381001_77_dialog_content = "你們往底下看！",
  ui_story_5038_50381001_78_dialog_content = "有魚！好多魚在撞過來！",
  ui_story_5038_50381001_79_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5038_50381001_80_dialog_content = "小心！！！牠們要跳到甲板上來了！",
  ui_story_5038_50381002_1_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5038_50381002_2_dialog_content = "啊！！！",
  ui_story_5038_50381002_3_dialog_content = "怎麼辦，那些魚還在撞擊我們！",
  ui_story_5038_50381002_4_dialog_content = "船底是修補過的，要是被它們撞壞……",
  ui_story_5038_50381002_5_dialog_content = "快把大魚給我！",
  ui_story_5038_50381002_6_dialog_content = "欸？",
  ui_story_5038_50381002_7_dialog_content = "我的祖宗姑奶奶唷，你可趕緊回去吧。",
  ui_story_5038_50381002_8_dialog_content = "走吧！",
  ui_story_5038_50381002_9_dialog_content = "<color=#e8d9bb>噗通！</color>",
  ui_story_5038_50381002_10_dialog_content = "好了，這下就沒事了。",
  ui_story_5038_50381002_11_dialog_content = "是牠引發的魚群襲擊？",
  ui_story_5038_50381002_12_dialog_content = "嗯，螭龍魚這個族群的集體意識非常強。",
  ui_story_5038_50381002_13_dialog_content = "只要有一條魚被困，整個魚群都會來救牠。",
  ui_story_5038_50381002_14_dialog_content = "在海上惹到螭龍魚是件非常可怕的事情。",
  ui_story_5038_50381002_15_dialog_content = "集體意識……好奇特的習性。",
  ui_story_5038_50381002_16_dialog_content = "多謝厘青和仲胥大人的提醒。",
  ui_story_5038_50381002_17_dialog_content = "是我們太莽撞了，差點惹出大事。",
  ui_story_5038_50381002_18_dialog_content = "沒事沒事，大家都是一條船上的，不必如此客氣。",
  ui_story_5038_50381002_19_dialog_content = "既然沒釀成大禍，剛才這點麻煩就讓它過去吧。",
  ui_story_5038_50381002_20_dialog_content = "這附近竟然來了螭龍魚，不會又要襲擊我們船隻吧。",
  ui_story_5038_50381002_21_dialog_content = "再來一次可頂不住啊……",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>次日</color>",
  ui_story_5038_50381002_23_dialog_content = "又是螭龍魚！快給牠放了！",
  ui_story_5038_50381002_24_dialog_content = "我知道我知道，又不是第一次了。",
  ui_story_5038_50381002_25_dialog_content = "哎，這些大爺能不能別來為難我們捕魚的了。",
  ui_story_5038_50381002_26_dialog_content = "第七條……",
  ui_story_5038_50381002_27_dialog_content = "月白！妳在這呢！",
  ui_story_5038_50381002_28_dialog_content = "午飯做好了，他們讓我來叫妳過去。",
  ui_story_5038_50381002_29_dialog_content = "今天午飯還挺豐盛的，雖然滿桌都是魚，哈哈哈哈。",
  ui_story_5038_50381002_30_dialog_content = "我先不吃了，你們吃吧。",
  ui_story_5038_50381002_31_dialog_content = "嗯？不吃嗎？",
  ui_story_5038_50381002_32_dialog_content = "有……有煩心事？",
  ui_story_5038_50381002_33_dialog_content = "有件事讓我覺得很奇怪，我要想明白心裡才踏實。",
  ui_story_5038_50381002_34_dialog_content = "欸？奇怪是指……",
  ui_story_5038_50381002_35_dialog_content = "這些螭龍魚太反常了。",
  ui_story_5038_50381002_36_dialog_content = "牠們是跨洋洄游的族群，終年往返於龍洲與艾斯特拉之間。",
  ui_story_5038_50381002_37_dialog_content = "牠們從不在大海中任何一處駐足，只有接近陸地時會短暫停留。",
  ui_story_5038_50381002_38_dialog_content = "可現在，成群的螭龍魚卻在這片海域徘徊。",
  ui_story_5038_50381002_39_dialog_content = "是哦，今天船工好像總能捕到螭龍魚。",
  ui_story_5038_50381002_40_dialog_content = "牠們不會又要襲擊我們吧？",
  ui_story_5038_50381002_41_dialog_content = "目前看來還沒有這個動向。",
  ui_story_5038_50381002_42_dialog_content = "我在盡力繞開魚群，不會重蹈之前的覆轍。",
  ui_story_5038_50381002_43_dialog_content = "但螭龍魚的奇怪行徑，至少說明面前的海域不尋常。",
  ui_story_5038_50381002_44_dialog_content = "它竟然比龍洲更能吸引螭龍魚。",
  ui_story_5038_50381002_45_dialog_content = "唔……",
  ui_story_5038_50381002_46_dialog_content = "你回去吃飯吧，我要去看看海圖。",
  ui_story_5038_50381002_47_dialog_content = "蜃風到底開到了什麼地方……",
  ui_story_5038_50381002_48_dialog_content = "昨日的航向、風速……",
  ui_story_5038_50381002_49_dialog_content = "不對，應該再往北方偏一些。",
  ui_story_5038_50381002_50_dialog_content = "<color=#e8d9bb>叩、叩。</color>",
  ui_story_5038_50381002_51_dialog_content = "誰？",
  ui_story_5038_50381002_52_dialog_content = "仲某求見。",
  ui_story_5038_50381002_53_dialog_content = "仲胥大人？您來找我是……",
  ui_story_5038_50381002_54_dialog_content = "在海上已然顛簸多日，可仲某分辨不清方向。",
  ui_story_5038_50381002_55_dialog_content = "敢問閣下，如今蜃風行至何處了？",
  ui_story_5038_50381002_56_dialog_content = "何處……",
  ui_story_5038_50381002_57_dialog_content = "仲胥大人，海圖尚不完整，我也無法說出準確位置。",
  ui_story_5038_50381002_58_dialog_content = "待我再估量一番，晚些告知您一個大概。",
  ui_story_5038_50381002_59_dialog_content = "無妨，我於航行無助，只是隨便問問。",
  ui_story_5038_50381002_60_dialog_content = "您是船長，接下來的航行，您心裡有數便可。",
  ui_story_5038_50381002_61_dialog_content = "……",
  ui_story_5038_50381002_62_dialog_content = "就怕，您也與仲某一樣，心中並無定數。",
  ui_story_5038_50381002_63_dialog_content = "哎……",
  ui_story_5038_50381002_64_dialog_content = "仲胥大人，我沒有在大海面前討個定數的狂悖之心。",
  ui_story_5038_50381002_65_dialog_content = "能說出口的，唯有盡力而為。",
  ui_story_5038_50381002_66_dialog_content = "此去茫茫，莫問前路。",
  ui_story_5038_50381002_67_dialog_content = "木船長的決意，仲某很是佩服。",
  ui_story_5038_50381002_68_dialog_content = "不過這大海上，也未必沒有定數。",
  ui_story_5038_50381002_69_dialog_content = "……",
  ui_story_5038_50381002_70_dialog_content = "您是想說「羅盤」，對嗎？",
  ui_story_5038_50381002_71_dialog_content = "正是。仲某知道，木船長始終以完成航行為重。",
  ui_story_5038_50381002_72_dialog_content = "可如今蜃風物資枯竭、方位不明，唯有找到「羅盤」能解如今困局。",
  ui_story_5038_50381002_73_dialog_content = "找到「羅盤」……",
  ui_story_5038_50381002_74_dialog_content = "就算它真如仲胥大人所言，有神通廣大的力量。",
  ui_story_5038_50381002_75_dialog_content = "以現在的局面，哪還有餘力去四海尋它啊……",
  ui_story_5038_50381002_76_dialog_content = "若是不必踏遍四海呢？",
  ui_story_5038_50381002_77_dialog_content = "林家的寶物「羅盤」，就在眼前的海域。",
  ui_story_5038_50381002_78_dialog_content = "什麼？！",
  ui_story_5038_50381002_79_dialog_content = "哎……",
  ui_story_5038_50381002_80_dialog_content = "又一箱食物變質了……",
  ui_story_5038_50381002_81_dialog_content = "要不……別扔了吧？",
  ui_story_5038_50381002_82_dialog_content = "變質了也比沒得吃好啊。",
  ui_story_5038_50381002_83_dialog_content = "淡水呢……",
  ui_story_5038_50381002_84_dialog_content = "<color=#e8d9bb>匡當——</color>",
  ui_story_5038_50381002_85_dialog_content = "這一桶已經空了。",
  ui_story_5038_50381002_86_dialog_content = "老天啊，下點雨讓我們接一些吧。",
  ui_story_5038_50381002_87_dialog_content = "剩下的還有一、二、三……",
  ui_story_5038_50381002_88_dialog_content = "哎喲，可算找到了，在這呢！",
  ui_story_5038_50381002_89_dialog_content = "嗯？你怎麼來了？",
  ui_story_5038_50381002_90_dialog_content = "快跟我上去，船長有急事找你！",
  ui_story_5038_50381101_1_dialog_content = "別光顧著抓魚了，盯著點遠處的海面！",
  ui_story_5038_50381101_2_dialog_content = "船長說了，要把這片海域搜尋個乾淨。",
  ui_story_5038_50381101_3_dialog_content = "有發現立刻報告給我！",
  ui_story_5038_50381101_4_dialog_content = "明白！",
  ui_story_5038_50381101_5_dialog_content = "厘青，我們是在找「羅盤」對吧？",
  ui_story_5038_50381101_6_dialog_content = "當然，不然光禿禿的海面上有什麼值得全船人盯著看的。",
  ui_story_5038_50381101_7_dialog_content = "「羅盤」應該出現在林家舊船上……",
  ui_story_5038_50381101_8_dialog_content = "對了，我記得你之前跟我說，林家舊船並沒有沉沒？",
  ui_story_5038_50381101_9_dialog_content = "至少在我和老哥離開的時候，它還沒有沉沒。",
  ui_story_5038_50381101_10_dialog_content = "那它會一直孤零零地漂在海上？",
  ui_story_5038_50381101_11_dialog_content = "想一想感覺怪嚇人的……",
  ui_story_5038_50381101_12_dialog_content = "這樣不好嗎？找起來多方便啊。",
  ui_story_5038_50381101_13_dialog_content = "可是……這麼長時間漂在海上，難免遭遇些大風大浪。",
  ui_story_5038_50381101_14_dialog_content = "船上沒人，很容易沉入海底吧。",
  ui_story_5038_50381101_15_dialog_content = "不會的不會的。",
  ui_story_5038_50381101_16_dialog_content = "別忘了，我們要找的寶貝「羅盤」可是在上面呢。",
  ui_story_5038_50381101_17_dialog_content = "哎，天都黑了……",
  ui_story_5038_50381101_18_dialog_content = "不然，今天先算了吧？",
  ui_story_5038_50381101_19_dialog_content = "天一黑，大家什麼都看不清了。",
  ui_story_5038_50381101_20_dialog_content = "可是今天什麼收穫都沒有……",
  ui_story_5038_50381101_21_dialog_content = "剩下的日子可不多了啊。",
  ui_story_5038_50381101_22_dialog_content = "那邊有東西！",
  ui_story_5038_50381101_23_dialog_content = "嗯？什麼？！",
  ui_story_5038_50381101_24_dialog_content = "你們看你們看！我手指的地方！",
  ui_story_5038_50381101_25_dialog_content = "真的是！有東西在漂過來！",
  ui_story_5038_50381101_26_dialog_content = "那是……一塊木板嗎？",
  ui_story_5038_50381101_27_dialog_content = "再近一點……再近一點……",
  ui_story_5038_50381101_28_dialog_content = "我、我好像能看清了！",
  ui_story_5038_50381101_29_dialog_content = "那是塊木牌！上面寫著……",
  ui_story_5038_50381101_30_dialog_content = "是林字！！！",
  ui_story_5038_50381101_31_dialog_content = "那是林家的牌匾！",
  ui_story_5038_50381101_32_dialog_content = "林家牌匾？！難道是蜃風舊船……",
  ui_story_5038_50381101_33_dialog_content = "看樣子它剛落入水中不久！",
  ui_story_5038_50381101_34_dialog_content = "錯不了，舊船一定就在附近！",
  ui_story_5038_50381101_35_dialog_content = "小船在哪裡？我要坐小船下去！",
  ui_story_5038_50381101_36_dialog_content = "現在嗎？！",
  ui_story_5038_50381101_37_dialog_content = "要不先等等，跟月白商量下怎麼找比較快……",
  ui_story_5038_50381101_38_dialog_content = "不必了。",
  ui_story_5038_50381101_39_dialog_content = "欸？月白你……",
  ui_story_5038_50381101_40_dialog_content = "<color=#e8d9bb>噗通——</color>",
  ui_story_5038_50381101_41_dialog_content = "她她她她她、她跳進海裡了？！",
  ui_story_5038_50381101_42_dialog_content = "不怕水的傢伙，真叫人羡慕啊！",
  ui_story_5038_50381101_43_dialog_content = "不行，我不能落下！",
  ui_story_5038_50381101_44_dialog_content = "快！快把小船放下去！",
  ui_story_5038_50381101_45_dialog_content = "（海水裡有木頭的味道。）",
  ui_story_5038_50381101_46_dialog_content = "（在下面，在更深的地方。）",
  ui_story_5038_50381101_47_dialog_content = "（林家舊船沉沒在這裡了嗎？）",
  ui_story_5038_50381101_48_dialog_content = "（「羅盤」……不會被海水損壞吧？）",
  ui_story_5038_50381101_49_dialog_content = "（哎，到頭來還是只能依靠其他東西。）",
  ui_story_5038_50381101_50_dialog_content = "（繼續下潛吧。）",
  ui_story_5038_50381101_51_dialog_content = "（我需要去到更深的地方。）",
  ui_story_5038_50381101_52_dialog_content = "（去到海底……）",
  ui_story_5038_50381101_53_dialog_content = "（嗯？那是……）",
  ui_story_5038_50381101_54_dialog_content = "（！！！）",
  ui_story_5038_50381101_55_dialog_content = "（沉船……不止一艘……）",
  ui_story_5038_50381101_56_dialog_content = "（司空見慣的船隻，放在海底竟然是這樣的感覺。）",
  ui_story_5038_50381101_57_dialog_content = "（它們好平靜，異樣的平靜。）",
  ui_story_5038_50381101_58_dialog_content = "（無論失事時經歷了怎樣的波濤，沉入海底後也只剩平靜。）",
  ui_story_5038_50381101_59_dialog_content = "（平靜到讓人感到有些後怕。）",
  ui_story_5038_50381101_60_dialog_content = "（被大海吞沒的不只是船隻，還有人們的情緒和尖叫。）",
  ui_story_5038_50381101_61_dialog_content = "（海洋將腹中的每一樣東西同化，直至連波紋都趨於一致。）",
  ui_story_5038_50381101_62_dialog_content = "（這裡是沉船的墳塚，也像它們的港口。）",
  ui_story_5038_50381101_63_dialog_content = "（船隻停泊在這裡，不再有出發之日。）",
  ui_story_5038_50381101_64_dialog_content = "（我要遊過去看看嗎？）",
  ui_story_5038_50381101_65_dialog_content = "（可……我好像沒看到林家舊船。）",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_5038_50381101_67_dialog_content = "成了，小船已經給您備好。",
  ui_story_5038_50381101_68_dialog_content = "您現在就出發嗎？",
  ui_story_5038_50381101_69_dialog_content = "嗯，現在就走！",
  ui_story_5038_50381101_70_dialog_content = "厘青，我陪你一起去吧。",
  ui_story_5038_50381101_71_dialog_content = "讓你自己去我有點……",
  ui_story_5038_50381101_72_dialog_content = "你、你不是怕水嗎。",
  ui_story_5038_50381101_73_dialog_content = "唔……",
  ui_story_5038_50381101_74_dialog_content = "好吧，你跟我一起上船。",
  ui_story_5038_50381101_75_dialog_content = "船槳太長了，我自己划著費勁。",
  ui_story_5038_50381101_76_dialog_content = "嗯！我們一起走吧！",
  ui_story_5038_50381101_77_dialog_content = "船工，把小船……",
  ui_story_5038_50381101_78_dialog_content = "嘎……",
  ui_story_5038_50381101_79_dialog_content = "嗚哇，什麼聲音？！",
  ui_story_5038_50381101_80_dialog_content = "有……有東西在拽著小船！",
  ui_story_5038_50381101_81_dialog_content = "什麼？！",
  ui_story_5038_50381101_82_dialog_content = "是哪個不長眼的……",
  ui_story_5038_50381101_83_dialog_content = "嘎嗷——！！！",
  ui_story_5038_50381101_84_dialog_content = "哇、哇、哇、哇！",
  ui_story_5038_50381101_85_dialog_content = "哪裡蹦出來的髒東西！",
  ui_story_5038_50381101_86_dialog_content = "下、下面！你們看小船的繩索上！",
  ui_story_5038_50381101_87_dialog_content = "好多暗鬼爬上來了！",
  ui_story_5038_50381102_1_dialog_content = "嗷……",
  ui_story_5038_50381102_2_dialog_content = "晦氣，把我的手都弄髒了。",
  ui_story_5038_50381102_3_dialog_content = "還有其他暗鬼嗎？",
  ui_story_5038_50381102_4_dialog_content = "沒了，全都被消滅掉了。",
  ui_story_5038_50381102_5_dialog_content = "那就好。走吧走吧，我們快出發。",
  ui_story_5038_50381102_6_dialog_content = "你們……真的還要下去嗎？",
  ui_story_5038_50381102_7_dialog_content = "甲板上就遭遇了暗鬼，海裡說不定有更多危險。",
  ui_story_5038_50381102_8_dialog_content = "你們船長都直接跳進海裡了。",
  ui_story_5038_50381102_9_dialog_content = "比起擔心我們，不如先擔心下她。",
  ui_story_5038_50381102_10_dialog_content = "走吧，PlayerName。",
  ui_story_5038_50381102_11_dialog_content = "嗯！",
  ui_story_5038_50381102_12_dialog_content = "小尾巴，你不要跟上來。",
  ui_story_5038_50381102_13_dialog_content = "喵嗚？",
  ui_story_5038_50381102_14_dialog_content = "坐在小船上才覺得海面好大啊。",
  ui_story_5038_50381102_15_dialog_content = "厘青，我們真的能找到林家舊船嗎？",
  ui_story_5038_50381102_16_dialog_content = "難得有了線索，它距離不會太遠。",
  ui_story_5038_50381102_17_dialog_content = "可是……",
  ui_story_5038_50381102_18_dialog_content = "你擔心它沉入海底了？",
  ui_story_5038_50381102_19_dialog_content = "嗯……",
  ui_story_5038_50381102_20_dialog_content = "剛才的牌匾單獨漂在海上，就像我們之前見過的那些殘骸一樣。",
  ui_story_5038_50381102_21_dialog_content = "也許是大風刮的。",
  ui_story_5038_50381102_22_dialog_content = "或者是暗鬼跑到船上，把牌匾扯了下來。",
  ui_story_5038_50381102_23_dialog_content = "不重要，重要的是它就在附近。",
  ui_story_5038_50381102_24_dialog_content = "我們要找到它。",
  ui_story_5038_50381102_25_dialog_content = "哈哈，你倒是對那艘船滿有信心的嘛。",
  ui_story_5038_50381102_26_dialog_content = "當然，因為「羅盤」在那艘船上。",
  ui_story_5038_50381102_27_dialog_content = "（總覺得，厘青對於尋找「羅盤」有一種獨特的急切。）",
  ui_story_5038_50381102_28_dialog_content = "（但他的急切又和月白的不太一樣。）",
  ui_story_5038_50381102_29_dialog_content = "（我能懂月白著急的原因。但是看著厘青認真的表情，我其實並不理解。）",
  ui_story_5038_50381102_30_dialog_content = "（也許是我更習慣於他漫不經心的那張臉吧。）",
  ui_story_5038_50381102_31_dialog_content = "怎麼回事？這是……",
  ui_story_5038_50381102_32_dialog_content = "起霧了？",
  ui_story_5038_50381102_33_dialog_content = "好像是哦，愈來愈看不清了。",
  ui_story_5038_50381102_34_dialog_content = "好煩人啊，能不能趕緊來一陣風。",
  ui_story_5038_50381102_35_dialog_content = "這樣下去該怎麼找東西啊！",
  ui_story_5038_50381102_36_dialog_content = "等一下，我突然有了更擔心的事情……",
  ui_story_5038_50381102_37_dialog_content = "看不清遠處的話……我們該怎麼回到蜃風啊？",
  ui_story_5038_50381102_38_dialog_content = "你、你還記得蜃風在哪個方向嗎？",
  ui_story_5038_50381102_39_dialog_content = "唔，應該是後面吧？",
  ui_story_5038_50381102_40_dialog_content = "不對，左邊？",
  ui_story_5038_50381102_41_dialog_content = "那就是不記得了啊！",
  ui_story_5038_50381102_42_dialog_content = "海面這麼大，萬一方向跟蜃風錯過了……",
  ui_story_5038_50381102_43_dialog_content = "哎呀，別那麼擔心。",
  ui_story_5038_50381102_44_dialog_content = "小船上有魚竿，靠釣魚我們都能活上好些天呢。",
  ui_story_5038_50381102_45_dialog_content = "我可不滿足於只活個「好些天」啊……",
  ui_story_5038_50381102_46_dialog_content = "而且，要是我們找到了林家舊船和「羅盤」。",
  ui_story_5038_50381102_47_dialog_content = "說不定是我們先抵達龍洲呢。",
  ui_story_5038_50381102_48_dialog_content = "這麼大的霧，想在海面上找什麼都無從說起啊。",
  ui_story_5038_50381102_49_dialog_content = "要不先停在原處，平安地等霧氣過去再說？",
  ui_story_5038_50381102_50_dialog_content = "嗯，也有道理……",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_5038_50381102_52_dialog_content = "嗚啊啊啊啊啊啊！！！",
  ui_story_5038_50381102_53_dialog_content = "什、什麼東西！",
  ui_story_5038_50381102_54_dialog_content = "渾身都濕了啊啊啊啊！",
  ui_story_5038_50381102_55_dialog_content = "厘青！你先躲在我後面……",
  ui_story_5038_50381102_56_dialog_content = "別大喊大叫了，是我。",
  ui_story_5038_50381102_57_dialog_content = "欸……月白？",
  ui_story_5038_50381102_58_dialog_content = "妳從海裡冒出來的？",
  ui_story_5038_50381102_59_dialog_content = "這周圍除了海也沒有其他東西了吧。",
  ui_story_5038_50381102_60_dialog_content = "妳、妳一定要用這種方式上船嗎？",
  ui_story_5038_50381102_61_dialog_content = "呃……濕乎乎的好噁心……",
  ui_story_5038_50381102_62_dialog_content = "對不起，我還沒習慣在海上照顧怕水之人。",
  ui_story_5038_50381102_63_dialog_content = "妳……",
  ui_story_5038_50381102_64_dialog_content = "說些正事。",
  ui_story_5038_50381102_65_dialog_content = "我剛才潛入海中，在海底發現了一處沉船塚。",
  ui_story_5038_50381102_66_dialog_content = "嘶，這底下果然有沉船啊……",
  ui_story_5038_50381102_67_dialog_content = "等等，月白妳竟然能潛到海底？！",
  ui_story_5038_50381102_68_dialog_content = "若是水性不佳，我也不敢貿然躍入海中。",
  ui_story_5038_50381102_69_dialog_content = "說回船塚，那裡面的沉船不少，基本都是商船。",
  ui_story_5038_50381102_70_dialog_content = "但我查看了一圈，沒有林家舊船的痕跡。",
  ui_story_5038_50381102_71_dialog_content = "還是沒有啊……",
  ui_story_5038_50381102_72_dialog_content = "你們在海面上有收穫嗎？",
  ui_story_5038_50381102_73_dialog_content = "也沒有。",
  ui_story_5038_50381102_74_dialog_content = "本來黑夜裡就看不清，後來又起了霧。",
  ui_story_5038_50381102_75_dialog_content = "現在別說林家舊船，連蜃風都不知道在哪。",
  ui_story_5038_50381102_76_dialog_content = "原來如此。",
  ui_story_5038_50381102_77_dialog_content = "有這場霧在，今日恐怕難有收穫了。",
  ui_story_5038_50381102_78_dialog_content = "我們回去吧，把船槳遞給我。",
  ui_story_5038_50381102_79_dialog_content = "好！月白妳知道蜃風的方位？",
  ui_story_5038_50381102_80_dialog_content = "那是自然，船長可不能把船給弄丟。",
  ui_story_5038_50381102_81_dialog_content = "太好了，這下就安心多了！",
  ui_story_5038_50381102_82_dialog_content = "妳、妳划快點，我要趕緊去廚房烤火。",
  ui_story_5038_50381102_83_dialog_content = "嗯，我不會耽擱。",
  ui_story_5038_50381102_84_dialog_content = "（船槳撥動起海水，月白划起船來比我和厘青熟練多了。）",
  ui_story_5038_50381102_85_dialog_content = "（四周白茫茫的，我分不清方向，甚至難以確認小船是不是在前進。）",
  ui_story_5038_50381102_86_dialog_content = "（月白真能在濃霧中辨明方向嗎？）",
  ui_story_5038_50381102_87_dialog_content = "（想想也是，她連我們這艘小船都能找到，蜃風那般巨大肯定沒有問題。）",
  ui_story_5038_50381102_88_dialog_content = "哈啾——",
  ui_story_5038_50381102_89_dialog_content = "嗚……回去要給自己煎上一副……",
  ui_story_5038_50381102_90_dialog_content = "嗯？那是……",
  ui_story_5038_50381102_91_dialog_content = "喔哦哦哦！我們回來了！",
  ui_story_5038_50381102_92_dialog_content = "真的是啊，竟然到了這麼近才看清。",
  ui_story_5038_50381102_93_dialog_content = "是啊。而且，第一次從這個角度看蜃風。",
  ui_story_5038_50381102_94_dialog_content = "好壯觀啊。",
  ui_story_5038_50381102_95_dialog_content = "快叫人接我們上去吧。",
  ui_story_5038_50381102_96_dialog_content = "喂！船工！",
  ui_story_5038_50381102_97_dialog_content = "我們在這裡！",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5038_50381102_99_dialog_content = "怎麼沒人理我，睡覺去了？",
  ui_story_5038_50381102_100_dialog_content = "是哦，怎麼這麼安靜啊。",
  ui_story_5038_50381102_101_dialog_content = "喂！聽得到嗎！",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5038_50381102_103_dialog_content = "奇怪，我喊得夠大聲了啊。",
  ui_story_5038_50381102_104_dialog_content = "迷霧裡看不清就算了，難道也聽不清嗎？",
  ui_story_5038_50381102_105_dialog_content = "這船……",
  ui_story_5038_50381102_106_dialog_content = "月白，妳覺得是怎麼回事？",
  ui_story_5038_50381102_107_dialog_content = "先上去看看。",
  ui_story_5038_50381102_108_dialog_content = "前面有垂下的繩索，我們自己登上去吧。",
  ui_story_5038_50381201_1_dialog_content = "怎麼回事，突然起了好大的霧啊。",
  ui_story_5038_50381201_2_dialog_content = "可不是嘛，船長、厘青和PlayerName都在海上，這要是迷失了……",
  ui_story_5038_50381201_3_dialog_content = "大海茫茫，誰知道還能不能遇見……",
  ui_story_5038_50381201_4_dialog_content = "他們在海上？怎會如此？",
  ui_story_5038_50381201_5_dialog_content = "剛才發現了蜃風舊船的線索，三人便前後腳下船去尋覓蹤跡。",
  ui_story_5038_50381201_6_dialog_content = "誰能想到，偏偏是這時候起了霧。",
  ui_story_5038_50381201_7_dialog_content = "叫大家舉起火把，守在船舷旁看著。",
  ui_story_5038_50381201_8_dialog_content = "我已把船帆收起，讓船隻儘量減少移動。",
  ui_story_5038_50381201_9_dialog_content = "船長方向感強，就算起了霧也能原路找回來。",
  ui_story_5038_50381201_10_dialog_content = "可另外兩位小兄弟就……",
  ui_story_5038_50381201_11_dialog_content = "騙子大人，把我和阿玖叫上做什麼？",
  ui_story_5038_50381201_12_dialog_content = "如今有三人失蹤，我還想幫忙找找他們的下落呢。",
  ui_story_5038_50381201_13_dialog_content = "外面大霧彌漫，也不差你這一雙眼睛。",
  ui_story_5038_50381201_14_dialog_content = "倒不如來艙室之中，幫在下壯壯膽。",
  ui_story_5038_50381201_15_dialog_content = "壯膽？你要做什麼去？",
  ui_story_5038_50381201_16_dialog_content = "在下要去找仲胥大人。",
  ui_story_5038_50381201_17_dialog_content = "嗯？那有什麼可怕的？",
  ui_story_5038_50381201_18_dialog_content = "<color=#e8d9bb>嗒、嗒、嗒——</color>",
  ui_story_5038_50381201_19_dialog_content = "仲胥大人，您在這歇著呢。",
  ui_story_5038_50381201_20_dialog_content = "窗外起霧了，有事情發生嗎？",
  ui_story_5038_50381201_21_dialog_content = "聽船員說，船長、厘青和PlayerName公子去海上尋找舊船，如今全部失蹤了……",
  ui_story_5038_50381201_22_dialog_content = "這霧起得竟如此不巧。",
  ui_story_5038_50381201_23_dialog_content = "若是他們能找到舊船還好。",
  ui_story_5038_50381201_24_dialog_content = "找不到的話，海面上著實兇險。",
  ui_story_5038_50381201_25_dialog_content = "是啊，這附近螭龍魚環伺，誰知道他們會不會遭遇襲擊。",
  ui_story_5038_50381201_26_dialog_content = "現在看不清海裡的動向，搞不好連蜃風都要倒楣。",
  ui_story_5038_50381201_27_dialog_content = "是啊……這麼說來，我們自己也有危險……",
  ui_story_5038_50381201_28_dialog_content = "蜃風現在可遭不起又一次襲擊。",
  ui_story_5038_50381201_29_dialog_content = "既然如此，在下來給蜃風算一卦吧。",
  ui_story_5038_50381201_30_dialog_content = "若是能弄清楚遭遇襲擊的緣由，也好提前應對。",
  ui_story_5038_50381201_31_dialog_content = "這也能算出來嗎？",
  ui_story_5038_50381201_32_dialog_content = "持簽問卜講究個順應天時，如今正是好時機。",
  ui_story_5038_50381201_33_dialog_content = "即便是在下這等才疏學淺之輩，亦可管中窺豹。",
  ui_story_5038_50381201_34_dialog_content = "諸位，李天閑在此獻醜了。",
  ui_story_5038_50381201_35_dialog_content = "<color=#e8d9bb>沙沙——沙沙——</color>",
  ui_story_5038_50381201_36_dialog_content = "怎麼樣？算出什麼了？",
  ui_story_5038_50381201_37_dialog_content = "承蒙天恩，容我輩妙手偶得。",
  ui_story_5038_50381201_38_dialog_content = "歸此原初之地，探得個水落石出。",
  ui_story_5038_50381201_39_dialog_content = "蜃風遇襲的緣由已現於此處。",
  ui_story_5038_50381201_40_dialog_content = "仲胥大人，這簽上寫的可是您的名字！",
  ui_story_5038_50381201_41_dialog_content = "嘿……咻！",
  ui_story_5038_50381201_42_dialog_content = "PlayerName，爬個繩索都要我拽你，好狼狽啊。",
  ui_story_5038_50381201_43_dialog_content = "抱歉啊，不是每個人都擅長爬來爬去。",
  ui_story_5038_50381201_44_dialog_content = "上是上來了，不過……",
  ui_story_5038_50381201_45_dialog_content = "這船上一個人都沒有啊。",
  ui_story_5038_50381201_46_dialog_content = "怎麼回事，大家都下海去找我們了？",
  ui_story_5038_50381201_47_dialog_content = "去船艙裡看看吧，說不定他們進去躲避濃霧了。",
  ui_story_5038_50381201_48_dialog_content = "咦？船艙入口不是這裡嗎？",
  ui_story_5038_50381201_49_dialog_content = "呃，我剛爬上來好像有點轉向，這邊是……",
  ui_story_5038_50381201_50_dialog_content = "不對。",
  ui_story_5038_50381201_51_dialog_content = "嗯？",
  ui_story_5038_50381201_52_dialog_content = "這些東西不對。",
  ui_story_5038_50381201_53_dialog_content = "桅杆、船舷、甲板……",
  ui_story_5038_50381201_54_dialog_content = "這不是蜃風。",
  ui_story_5038_50381201_55_dialog_content = "小心後面！！！",
  ui_story_5038_50381201_56_dialog_content = "船上有暗鬼……",
  ui_story_5038_50381201_57_dialog_content = "而且不少。",
  ui_story_5038_50381201_58_dialog_content = "糟了，被包圍了……",
  ui_story_5038_50381201_59_dialog_content = "月白！先處理左邊的敵人！",
  ui_story_5038_50381201_60_dialog_content = "嗯。",
  ui_story_5038_50381201_61_dialog_content = "你好像很擅長應對這種突發情況。",
  ui_story_5038_50381201_62_dialog_content = "那是當然，我連做夢都會遇見突然出現的暗鬼。",
  ui_story_5038_50381201_63_dialog_content = "接下來要留意……",
  ui_story_5038_50381201_64_dialog_content = "我知道了！",
  ui_story_5038_50381201_65_dialog_content = "嗯？知道什麼？",
  ui_story_5038_50381201_66_dialog_content = "我認出來了！這裡我來過！",
  ui_story_5038_50381201_67_dialog_content = "這就是蜃風號！是蜃風號舊船！！！",
  ui_story_5038_50381201_68_dialog_content = "什麼？！",
  ui_story_5038_50381201_69_dialog_content = "果然如此……",
  ui_story_5038_50381201_70_dialog_content = "我們……誤打誤撞竟然找到它了？",
  ui_story_5038_50381201_71_dialog_content = "對，不會錯的！這塊欄杆就是我之前掰斷的！",
  ui_story_5038_50381201_72_dialog_content = "太好了！我們終於找到了！",
  ui_story_5038_50381201_73_dialog_content = "找是找到了，可現在這局面怎麼也說不上「好」吧……",
  ui_story_5038_50381201_74_dialog_content = "「羅盤」在船艙裡面，我知道它的位置。",
  ui_story_5038_50381201_75_dialog_content = "快跟上我，我帶你們去找它！",
  ui_story_5038_50381201_76_dialog_content = "喂，不要亂跑啊！誰知道裡面有沒有暗鬼！",
  ui_story_5038_50381201_77_dialog_content = "至少等我們……",
  ui_story_5038_50381201_78_dialog_content = "哎，已經跑沒影了。",
  ui_story_5038_50381201_79_dialog_content = "你們快點跟上來啊！",
  ui_story_5038_50381201_80_dialog_content = "看來他不會聽你的。",
  ui_story_5038_50381201_81_dialog_content = "走吧，我們跟上去。",
  ui_story_5038_50381201_82_dialog_content = "這些暗鬼拖不住我的腳步。",
  ui_story_5038_50381202_1_dialog_content = "你說是仲胥大人導致了蜃風號遇襲？怎麼可能……",
  ui_story_5038_50381202_2_dialog_content = "這占卜能靠得住嗎？",
  ui_story_5038_50381202_3_dialog_content = "呵呵。李天閑，你是衝著我來的。",
  ui_story_5038_50381202_4_dialog_content = "這一簽恐怕是提前準備的吧？",
  ui_story_5038_50381202_5_dialog_content = "仲胥大人果然聰明。",
  ui_story_5038_50381202_6_dialog_content = "自打螭龍魚再次出現，在下就卜算了一簽。",
  ui_story_5038_50381202_X6_dialog_content = "當時，抽出來的卦象為陰虎。",
  ui_story_5038_50381202_X7_dialog_content = "在下遲遲沒有想通，陰虎究竟預示著何物。",
  ui_story_5038_50381202_X8_dialog_content = "直到我突然想起句老話，「持虎者為將軍」。",
  ui_story_5038_50381202_X9_dialog_content = "您曾手持虎符號令千軍，正是此卦所指之人。",
  ui_story_5038_50381202_X10_dialog_content = "有點意思，你繼續說。",
  ui_story_5038_50381202_X11_dialog_content = "仲胥大人名字中的「胥」字，有蝴蝶的含義。",
  ui_story_5038_50381202_7_dialog_content = "或許您當初扇動翅膀，才釀就了如今的這場風暴。",
  ui_story_5038_50381202_8_dialog_content = "仲胥大人，您曾講過舊船失事的經歷。",
  ui_story_5038_50381202_9_dialog_content = "林家攜寶物出海，亂賊乘船爭搶。",
  ui_story_5038_50381202_10_dialog_content = "可事情最後，倖存下來的竟然只有您和厘青兩位林家的座上客。",
  ui_story_5038_50381202_11_dialog_content = "那麼您二位在這起事件中扮演了何種角色呢？",
  ui_story_5038_50381202_12_dialog_content = "此番種種，還望仲胥大人為在下解惑。",
  ui_story_5038_50381202_13_dialog_content = "你是來質問我的，不必如此客氣。",
  ui_story_5038_50381202_14_dialog_content = "叫上丹棠和玖一起，是怕仲某惱羞成怒嗎？",
  ui_story_5038_50381202_15_dialog_content = "怪、怪不得剛才說要我幫你壯膽。",
  ui_story_5038_50381202_16_dialog_content = "仲胥大人雖雙腿殘廢，仍有一身英武之氣。",
  ui_story_5038_50381202_17_dialog_content = "若是在下一人，恐要被壓得說不出話來。",
  ui_story_5038_50381202_18_dialog_content = "也罷。既然你問上門來，仲某就嘮叨幾句吧。",
  ui_story_5038_50381202_19_dialog_content = "其實我自己也在懷疑，螭龍魚是否因我而來。",
  ui_story_5038_50381202_20_dialog_content = "或者說，牠們的異動因我而起。",
  ui_story_5038_50381202_21_dialog_content = "此話怎講？",
  ui_story_5038_50381202_22_dialog_content = "先說回蜃風舊船吧。",
  ui_story_5038_50381202_23_dialog_content = "林家攜寶物出海，引得亂賊爭搶，這其中並無虛言。",
  ui_story_5038_50381202_24_dialog_content = "但當時仲某並不在蜃風舊船上，而是跟在亂賊身後。",
  ui_story_5038_50381202_25_dialog_content = "身後？！",
  ui_story_5038_50381202_26_dialog_content = "我答應過林家家主，會保住林家的基業。",
  ui_story_5038_50381202_27_dialog_content = "為了信守諾言，我一路尾隨亂賊，在他們之後登上了蜃風舊船。",
  ui_story_5038_50381202_28_dialog_content = "原本我想偷偷取回羅盤，再乘小船歸返大陸。",
  ui_story_5038_50381202_29_dialog_content = "可那一夜，船上之事比我想像中更加可憎。",
  ui_story_5038_50381202_30_dialog_content = "亂賊控制了蜃風舊船，可找不到「羅盤」所在。",
  ui_story_5038_50381202_31_dialog_content = "為了逼問出「羅盤」的下落，他們開始折磨林家船員，無所不用其極。",
  ui_story_5038_50381202_32_dialog_content = "身處海上，一無法度二無公道。對那幫賊子而言，簡直如魚得水。",
  ui_story_5038_50381202_33_dialog_content = "等我趕到時，林家子弟已無一倖免。",
  ui_story_5038_50381202_34_dialog_content = "我當時恍然大悟，光取回「羅盤」是沒有用的。",
  ui_story_5038_50381202_35_dialog_content = "林家勢微，身懷「羅盤」反而會招致禍患。",
  ui_story_5038_50381202_36_dialog_content = "真想保住它，唯有一條出路，那就是讓「羅盤」消失。",
  ui_story_5038_50381202_37_dialog_content = "消失？您扔了它嗎？",
  ui_story_5038_50381202_38_dialog_content = "當然不行，那是林家航海的基業，是他們東山再起的唯一希望。",
  ui_story_5038_50381202_39_dialog_content = "「羅盤」必須保住，但我要讓眾人再也不能提及。",
  ui_story_5038_50381202_40_dialog_content = "再也不能提及……",
  ui_story_5038_50381202_41_dialog_content = "等一下，莫非您……！",
  ui_story_5038_50381202_42_dialog_content = "是的，我只能把賊人全部滅口。",
  ui_story_5038_50381202_43_dialog_content = "我曾在沙場上征戰多年，可從未經歷過如此壓抑的一戰。",
  ui_story_5038_50381202_44_dialog_content = "那些賊人根本不是戰士。他們會在有機可乘時一擁而上，也會在潰敗時跪地求饒。",
  ui_story_5038_50381202_45_dialog_content = "他們會咒駡，會哭喊，會在絕望時醜態百出。",
  ui_story_5038_50381202_46_dialog_content = "他們並非真正想戰勝我，他們只是想活下去。",
  ui_story_5038_50381202_47_dialog_content = "那些人裡有的十惡不赦，有的只是為生活所迫，成為盜賊的理由各不相同。",
  ui_story_5038_50381202_48_dialog_content = "但我沒有辨別的餘地，只能把他們全部除掉。",
  ui_story_5038_50381202_49_dialog_content = "……為了保住「羅盤」，是嗎？",
  ui_story_5038_50381202_50_dialog_content = "是的，我是這麼說服自己的。",
  ui_story_5038_50381202_51_dialog_content = "但也有一兩個瞬間覺得，事情在當時失去了控制。",
  ui_story_5038_50381202_52_dialog_content = "在刀尖沾染鮮血的瞬間，我便已經無法回頭。",
  ui_story_5038_50381202_53_dialog_content = "原來是這樣……",
  ui_story_5038_50381202_54_dialog_content = "至於我說船隻遭遇了風暴的襲擊，確實是誆騙了諸位。",
  ui_story_5038_50381202_55_dialog_content = "致使我和厘青老弟落海漂流的罪魁禍首，其實是螭龍魚的襲擊。",
  ui_story_5038_50381202_56_dialog_content = "又是牠們？",
  ui_story_5038_50381202_57_dialog_content = "所以我才說，我自己也懷疑過螭龍魚是否因我而來。",
  ui_story_5038_50381202_58_dialog_content = "蜃風遇襲時的情景，與在舊船上那時極為相似。",
  ui_story_5038_50381202_59_dialog_content = "這些事與尋找「羅盤」無關，所以我本不想提。",
  ui_story_5038_50381202_60_dialog_content = "既然你今日非要問起，那我就當是與諸位分享了一樁往事吧。",
  ui_story_5038_50381202_61_dialog_content = "如此往事，任誰也不會願意提起。實在抱歉，是在下多嘴了！",
  ui_story_5038_50381202_62_dialog_content = "無妨。如此局面下，大家都需戮力同心。能消除諸位心中芥蒂便好。",
  ui_story_5038_50381202_63_dialog_content = "是的是的，戮力同心，仲胥大人所言極是。",
  ui_story_5038_50381202_64_dialog_content = "在下該多為眼前的困局動動腦子。",
  ui_story_5038_50381202_65_dialog_content = "這大霧一起，想做什麼都有心無力。",
  ui_story_5038_50381202_66_dialog_content = "不過厘青老弟對尋找「羅盤」很是上心，又有些祟靈獨有的靈性。",
  ui_story_5038_50381202_67_dialog_content = "既然他願意下海尋找，說明蜃風舊船果真就在附近。",
  ui_story_5038_50381202_68_dialog_content = "也許等迷霧散去，他就能取得「羅盤」歸來了。",
  ui_story_5038_50381202_69_dialog_content = "真要如此順利就好啊……",
  ui_story_5038_50381202_70_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5038_50381202_71_dialog_content = "怎麼……",
  ui_story_5038_50381202_72_dialog_content = "<size=45><color=#e8d9bb>轟隆隆隆——！！！</color></size>",
  ui_story_5038_50381202_73_dialog_content = "嗚啊啊啊啊啊啊！",
  ui_story_5038_50381202_74_dialog_content = "發生什麼事了？！怎麼晃得這麼厲害？",
  ui_story_5038_50381202_75_dialog_content = "仲胥大人，您……",
  ui_story_5038_50381202_76_dialog_content = "我沒事，快去甲板上看看！",
  ui_story_5038_50381202_77_dialog_content = "好！您等我……",
  ui_story_5038_50381202_78_dialog_content = "<size=45>啊啊啊啊啊啊啊啊啊啊啊啊啊！！！</size>",
  ui_story_5038_50381202_79_dialog_content = "怎麼了？！船工在叫什麼？",
  ui_story_5038_50381202_80_dialog_content = "有、有一艘船……",
  ui_story_5038_50381202_81_dialog_content = "<size=50>有一艘船撞上來了！！！</size>",
  ui_story_5038_50381301_1_dialog_content = "<color=#e8d9bb>轟隆隆隆——</color>",
  ui_story_5038_50381301_2_dialog_content = "哎喲喲喲，什麼動靜？！",
  ui_story_5038_50381301_3_dialog_content = "好像是船首發生了撞擊。你還好嗎？",
  ui_story_5038_50381301_4_dialog_content = "沒事沒事，我已經習慣船上的晃動了。",
  ui_story_5038_50381301_5_dialog_content = "撞擊……撞到了什麼？礁石嗎？",
  ui_story_5038_50381301_6_dialog_content = "快過來，前面就到了。",
  ui_story_5038_50381301_7_dialog_content = "呃不過……你們有人會開鎖嗎？",
  ui_story_5038_50381301_8_dialog_content = "這扇門好像被……",
  ui_story_5038_50381301_9_dialog_content = "我的刀會。",
  ui_story_5038_50381301_10_dialog_content = "<color=#e8d9bb>噌——</color>",
  ui_story_5038_50381301_11_dialog_content = "哇哇哇哇！妳差點砍到我！",
  ui_story_5038_50381301_12_dialog_content = "不進去嗎？",
  ui_story_5038_50381301_13_dialog_content = "哼……",
  ui_story_5038_50381301_14_dialog_content = "來吧，見識下大家尋找了一路的寶貝。",
  ui_story_5038_50381301_15_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_5038_50381301_16_dialog_content = "哇——",
  ui_story_5038_50381301_17_dialog_content = "裝飾得好精緻啊！",
  ui_story_5038_50381301_18_dialog_content = "這、這應該就是龍洲有錢人家的樣子吧！",
  ui_story_5038_50381301_19_dialog_content = "這裡的裝飾……",
  ui_story_5038_50381301_20_dialog_content = "與我記憶中的林家宅邸有八分相像。",
  ui_story_5038_50381301_21_dialog_content = "這些古玩字畫，許是家道中落後被藏在了船上。",
  ui_story_5038_50381301_22_dialog_content = "林家宅邸？是妳的家嗎？",
  ui_story_5038_50381301_23_dialog_content = "小時候我曾在那裡住過一段時間。",
  ui_story_5038_50381301_24_dialog_content = "後來林家商會沒落，財產全被典當，宅邸自然也歸了他人。",
  ui_story_5038_50381301_25_dialog_content = "真沒想到，會在這裡重見昔日的光景。",
  ui_story_5038_50381301_26_dialog_content = "兒時的家啊，那確實是很值得懷念的地方……",
  ui_story_5038_50381301_27_dialog_content = "不說這些了。",
  ui_story_5038_50381301_28_dialog_content = "厘青，「羅盤」是這些藏物中的哪一……",
  ui_story_5038_50381301_29_dialog_content = "不對啊，不該這樣的。",
  ui_story_5038_50381301_30_dialog_content = "嗯？怎麼了厘青？",
  ui_story_5038_50381301_31_dialog_content = "它不在了，它怎麼會不在呢……",
  ui_story_5038_50381301_32_dialog_content = "不在了？",
  ui_story_5038_50381301_33_dialog_content = "會不會是藏在了其他地方？",
  ui_story_5038_50381301_34_dialog_content = "厘青，把「羅盤」的樣子描述一下，我們幫你一起找。",
  ui_story_5038_50381301_35_dialog_content = "可是……它能藏到哪呢？",
  ui_story_5038_50381301_36_dialog_content = "它只能待在這個缸裡啊……",
  ui_story_5038_50381301_37_dialog_content = "待在缸裡？",
  ui_story_5038_50381301_38_dialog_content = "等一下，難道「羅盤」不是我理解的那種意思……",
  ui_story_5038_50381301_39_dialog_content = "嗯，「羅盤」是一條魚啊。",
  ui_story_5038_50381301_40_dialog_content = "什麼？！",
  ui_story_5038_50381301_41_dialog_content = "嘻嘻。",
  ui_story_5038_50381301_42_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5038_50381301_43_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5038_50381301_44_dialog_content = "怎、怎麼回事？！有東西碎了？",
  ui_story_5038_50381301_45_dialog_content = "是瓷瓶。可我沒看清在哪……",
  ui_story_5038_50381301_46_dialog_content = "糟了！有人跑出去了！",
  ui_story_5038_50381301_47_dialog_content = "有人？！哪還有別人？",
  ui_story_5038_50381301_48_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5038_50381301_49_dialog_content = "嗯？！門怎麼關上了！",
  ui_story_5038_50381301_50_dialog_content = "是他在外面！",
  ui_story_5038_50381301_51_dialog_content = "所以到底是誰……",
  ui_story_5038_50381301_52_dialog_content = "謝……",
  ui_story_5038_50381301_53_dialog_content = "？！！",
  ui_story_5038_50381301_54_dialog_content = "謝、謝、你、們。",
  ui_story_5038_50381301_55_dialog_content = "<color=#e8d9bb>嗒、嗒、嗒……</color>",
  ui_story_5038_50381301_56_dialog_content = "這是……",
  ui_story_5038_50381301_57_dialog_content = "他跑了！我們得趕緊追上去！",
  ui_story_5038_50381301_58_dialog_content = "這門……船長姐姐，還能把它弄開嗎？",
  ui_story_5038_50381301_59_dialog_content = "我試了，弄不開。外面被重物抵住了。",
  ui_story_5038_50381301_60_dialog_content = "糟了糟了糟了，必須要追上去。",
  ui_story_5038_50381301_61_dialog_content = "有沒有什麼辦法……",
  ui_story_5038_50381301_62_dialog_content = "我們三個一起把門撞開吧！",
  ui_story_5038_50381301_63_dialog_content = "行不通的，我們三個力氣不夠。",
  ui_story_5038_50381301_64_dialog_content = "你先冷靜一下。",
  ui_story_5038_50381301_65_dialog_content = "怎麼冷靜！他就要跑掉了啊！",
  ui_story_5038_50381301_66_dialog_content = "外面是茫茫大海，去哪裡找他……",
  ui_story_5038_50381301_67_dialog_content = "那個，我也許有辦法把門弄開。",
  ui_story_5038_50381301_68_dialog_content = "哇！真的嗎！！！",
  ui_story_5038_50381301_69_dialog_content = "嗯，不過需要點時間。",
  ui_story_5038_50381301_70_dialog_content = "你們等我一會……",
  ui_story_5038_50381301_71_dialog_content = "（雖然有些離譜，但是……）",
  ui_story_5038_50381301_72_dialog_content = "（試試看吧！）",
  ui_story_5038_50381301_73_option_content = "強制感應！",
  ui_story_5038_50381301_74_dialog_content = "PlayerName突然呆在那不動了，應該是在使用他的感應能力吧。",
  ui_story_5038_50381301_X74_dialog_content = "不如趁這會說說「羅盤」到底是怎麼回事。",
  ui_story_5038_50381301_75_dialog_content = "剛才跑掉的那個人又是誰？",
  ui_story_5038_50381301_76_dialog_content = "唔……該從何說起呢。",
  ui_story_5038_50381301_77_dialog_content = "我其實並沒見過逃走的那人。",
  ui_story_5038_50381301_78_dialog_content = "但是能出現在這個房間裡，只有一種可能。",
  ui_story_5038_50381301_79_dialog_content = "他就是「羅盤」。",
  ui_story_5038_50381301_80_dialog_content = "他是「羅盤」？！",
  ui_story_5038_50381301_81_dialog_content = "你一會說「羅盤」是魚，一會又說「羅盤」是人，到底是怎麼回事？",
  ui_story_5038_50381301_82_dialog_content = "「羅盤」確實是魚，而且是一條非常特殊的螭龍魚。",
  ui_story_5038_50381301_83_dialog_content = "但是，魚並非就要一直是魚的型態。",
  ui_story_5038_50381301_84_dialog_content = "還記得我是隻貓嗎？",
  ui_story_5038_50381301_85_dialog_content = "你是說……他是個祟靈？",
  ui_story_5038_50381301_86_dialog_content = "嗯，這是唯一的可能。",
  ui_story_5038_50381301_87_dialog_content = "在舊船獨自漂泊於海上的時間裡，他從魚類變為祟靈。",
  ui_story_5038_50381301_88_dialog_content = "新的力量讓他擺脫了水的桎梏，不用再委身於缸內。",
  ui_story_5038_50381301_89_dialog_content = "可是，他仍然無法離開這間房門緊鎖的艙室。",
  ui_story_5038_50381301_90_dialog_content = "直到我們劈開門鎖走進這裡……",
  ui_story_5038_50381301_91_dialog_content = "……竟會如此。",
  ui_story_5038_50381301_92_dialog_content = "「羅盤」是一條魚……可魚要如何指引航船跨海呢？",
  ui_story_5038_50381301_93_dialog_content = "船長姐姐身為林家人，對自家的圖騰應該很瞭解吧。",
  ui_story_5038_50381301_94_dialog_content = "螭龍魚會為了族群中的個體進行集體行動。",
  ui_story_5038_50381301_95_dialog_content = "而「羅盤」，是螭龍魚族群的首領。",
  ui_story_5038_50381301_96_dialog_content = "首領？！",
  ui_story_5038_50381301_97_dialog_content = "怪不得……螭龍魚會反常地遊蕩在這片海域。",
  ui_story_5038_50381301_98_dialog_content = "你和仲胥也是由此判斷出螭龍魚就在附近的。",
  ui_story_5038_50381301_99_dialog_content = "正是如此。",
  ui_story_5038_50381301_100_dialog_content = "等一下，我好像明白了……",
  ui_story_5038_50381301_101_dialog_content = "螭龍魚是懂得如何往返於兩塊大陸之間的。",
  ui_story_5038_50381301_102_dialog_content = "蜃風號舊船利用了這一點，控制住螭龍魚的首領。",
  ui_story_5038_50381301_103_dialog_content = "進而讓整個螭龍魚族群幫助船隻橫跨海洋……",
  ui_story_5038_50381301_104_dialog_content = "是的，就是這樣。",
  ui_story_5038_50381301_105_dialog_content = "林家常年將螭龍魚首領囚禁在船上。",
  ui_story_5038_50381301_106_dialog_content = "一代代過去後，新生的螭龍魚就將蜃風舊船視作它們的首領。",
  ui_story_5038_50381301_107_dialog_content = "每當航行時，螭龍魚族群會聚集在船隻後方，推動船隻前行。",
  ui_story_5038_50381301_108_dialog_content = "所以林家不用擔心迷失，也不用擔心海上的風浪。",
  ui_story_5038_50381301_109_dialog_content = "魚群總能將他們送至終點。",
  ui_story_5038_50381301_110_dialog_content = "……這件事，為什麼沒有人跟我說過。",
  ui_story_5038_50381301_111_dialog_content = "林家不說，你和仲胥也不說。",
  ui_story_5038_50381301_112_dialog_content = "哎。老哥跟我講過，但我不太明白。",
  ui_story_5038_50381301_113_dialog_content = "他們的理由很複雜，什麼「財不外露」啊，什麼「林家聲譽」啊之類的。",
  ui_story_5038_50381301_114_dialog_content = "既然如此，緘默不言是最好的選擇。",
  ui_story_5038_50381301_115_dialog_content = "……",
  ui_story_5038_50381301_116_dialog_content = "至於我嘛，我只是……對此心懷愧疚。",
  ui_story_5038_50381301_117_dialog_content = "從踏上蜃風號舊船那一天起，我也成了奴役他的共犯。",
  ui_story_5038_50381301_118_dialog_content = "面對陰晴不定的大海，我還是只能選擇用這種卑劣的方式去依靠他。",
  ui_story_5038_50381301_119_dialog_content = "所以，把他稱作「羅盤」對我來說更好受些。",
  ui_story_5038_50381301_120_dialog_content = "愧疚……",
  ui_story_5038_50381301_121_dialog_content = "能產生這樣的情感已經非常難得了。",
  ui_story_5038_50381301_122_dialog_content = "也許是因為我一直把他當作朋友吧。",
  ui_story_5038_50381301_123_dialog_content = "對了，他有個名字的。他的名字叫「尤」。",
  ui_story_5038_50381301_124_dialog_content = "尤。好，我記住了。",
  ui_story_5038_50381301_125_dialog_content = "那個，打擾一下。",
  ui_story_5038_50381301_126_dialog_content = "我好像成功了。",
  ui_story_5038_50381301_127_dialog_content = "成功？你把門打開了嗎？！",
  ui_story_5038_50381301_128_dialog_content = "嗯，馬上就要打開了。",
  ui_story_5038_50381301_129_dialog_content = "喔哦！有兩下子啊！",
  ui_story_5038_50381301_130_dialog_content = "不過你們得做好準備。",
  ui_story_5038_50381301_131_dialog_content = "準備？什麼意思？",
  ui_story_5038_50381301_132_dialog_content = "來了！",
  ui_story_5038_50381301_133_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5038_50381301_134_dialog_content = "嗷！！！",
  ui_story_5038_50381301_135_dialog_content = "嗚啊啊啊！嚇我一跳！",
  ui_story_5038_50381301_136_dialog_content = "暗鬼是怎麼闖進來的……",
  ui_story_5038_50381301_137_dialog_content = "等一下，這不會就是你的開門方法吧？",
  ui_story_5038_50381301_138_dialog_content = "吸引暗鬼來把門砸開？",
  ui_story_5038_50381301_139_dialog_content = "呃……算不算粗暴但有效？",
  ui_story_5038_50381301_140_dialog_content = "挺好的，暗鬼比這扇門好對付多了。",
  ui_story_5038_50381301_141_dialog_content = "除掉他們！",
  ui_story_5038_50381302_1_dialog_content = "怎麼了怎麼了！發生什麼事了！",
  ui_story_5038_50381302_2_dialog_content = "有暗鬼！有暗鬼爬上甲板了！",
  ui_story_5038_50381302_3_dialog_content = "全是從後面那條船上來的！",
  ui_story_5038_50381302_4_dialog_content = "嘎——！",
  ui_story_5038_50381302_5_dialog_content = "骯髒的東西，散去！",
  ui_story_5038_50381302_6_dialog_content = "嘎……",
  ui_story_5038_50381302_7_dialog_content = "竟然如此眾多……",
  ui_story_5038_50381302_8_dialog_content = "殿下，請往後退。",
  ui_story_5038_50381302_9_dialog_content = "粗鄙之事交給玖來辦就好了。",
  ui_story_5038_50381302_10_dialog_content = "所有人！都來船尾！",
  ui_story_5038_50381302_11_dialog_content = "把這些暗鬼攔住，別讓牠們肆意妄為！",
  ui_story_5038_50381302_12_dialog_content = "是！",
  ui_story_5038_50381302_13_dialog_content = "仲胥先生，這是怎麼回事？",
  ui_story_5038_50381302_14_dialog_content = "一艘滿是暗鬼的船隻竟會突然撞上我們……",
  ui_story_5038_50381302_15_dialog_content = "這艘巨船……",
  ui_story_5038_50381302_16_dialog_content = "濃霧中視野不明，許是被風浪碰巧推了過來。",
  ui_story_5038_50381302_17_dialog_content = "糟了！牠們在破壞桅杆！",
  ui_story_5038_50381302_18_dialog_content = "小心！甲板被打碎了許多！",
  ui_story_5038_50381302_19_dialog_content = "哎喲！這樣下去可不行，得想想辦法！",
  ui_story_5038_50381302_20_dialog_content = "可恨的暗鬼！",
  ui_story_5038_50381302_21_dialog_content = "阿玖，我們快去幫忙！",
  ui_story_5038_50381302_22_dialog_content = "且慢。",
  ui_story_5038_50381302_23_dialog_content = "欸？",
  ui_story_5038_50381302_24_dialog_content = "在蜃風上纏鬥下去，只會讓船體進一步受創。",
  ui_story_5038_50381302_25_dialog_content = "必須要把戰場轉移。",
  ui_story_5038_50381302_26_dialog_content = "轉移？您的意思是……",
  ui_story_5038_50381302_27_dialog_content = "取些木板來，搭一條通路去對面船頭。",
  ui_story_5038_50381302_28_dialog_content = "這把火，燒也要燒在那艘船上。",
  ui_story_5038_50381401_1_dialog_content = "仲胥大人，您身體不便，還是留在蜃風號上吧。",
  ui_story_5038_50381401_2_dialog_content = "這邊有我們在，除掉暗鬼足矣。",
  ui_story_5038_50381401_3_dialog_content = "是啊，您可別傷著自己。",
  ui_story_5038_50381401_4_dialog_content = "不必在意。",
  ui_story_5038_50381401_5_dialog_content = "若是會拖累諸位，仲某自然不會跟來。",
  ui_story_5038_50381401_6_dialog_content = "（錯不了，這裡就是蜃風號舊船。）",
  ui_story_5038_50381401_7_dialog_content = "（「羅盤」近在眼前，此去定要將它取回。）",
  ui_story_5038_50381401_8_dialog_content = "（老林，仲某說過的話，絕不會食言。）",
  ui_story_5038_50381401_9_dialog_content = "殿下，暗鬼圍上來了。",
  ui_story_5038_50381401_10_dialog_content = "數量比蜃風號上的更多。",
  ui_story_5038_50381401_11_dialog_content = "來得正好，就在這裡……",
  ui_story_5038_50381401_12_dialog_content = "二位莫急，請先退後兩步。",
  ui_story_5038_50381401_13_dialog_content = "別被仲某傷到。",
  ui_story_5038_50381401_14_dialog_content = "嗯？仲胥先生您……",
  ui_story_5038_50381401_15_dialog_content = "<size=50>炎火焚盡，斷滅諸惡！</size>",
  ui_story_5038_50381401_16_dialog_content = "殿下小心！",
  ui_story_5038_50381401_17_dialog_content = "嘎啊啊啊啊啊啊！！！",
  ui_story_5038_50381401_18_dialog_content = "好、好大的火勢！",
  ui_story_5038_50381401_19_dialog_content = "四下裡的暗鬼竟全都被烈焰裹挾……",
  ui_story_5038_50381401_20_dialog_content = "甚至連迷霧都散去了！",
  ui_story_5038_50381401_21_dialog_content = "怪不得仲胥大人執意要登上敵船。",
  ui_story_5038_50381401_22_dialog_content = "此等威能……斷不能在蜃風號上展現。",
  ui_story_5038_50381401_23_dialog_content = "這艘舊船在海上漂泊許久，被風蝕、被浪打。",
  ui_story_5038_50381401_24_dialog_content = "它的根骨已經朽爛，所剩不過枯槁之軀。",
  ui_story_5038_50381401_25_dialog_content = "用火一催，自然燒得旺盛。",
  ui_story_5038_50381401_26_dialog_content = "太好了！借著仲胥先生的火，我們快點將暗鬼掃清。",
  ui_story_5038_50381401_27_dialog_content = "蜃風號還等著我們回去幫忙呢。",
  ui_story_5038_50381401_28_dialog_content = "殿下請多加小心。火焰灼燒了甲板，也許有崩塌的危險。",
  ui_story_5038_50381401_29_dialog_content = "哦甲板，說得對啊……",
  ui_story_5038_50381401_30_dialog_content = "阿玖，我們互相抓著些吧。",
  ui_story_5038_50381401_31_dialog_content = "一個人要是踩空了，另一人還能幫忙拉一把。",
  ui_story_5038_50381401_32_dialog_content = "互相……",
  ui_story_5038_50381401_33_dialog_content = "嗯，就依殿下所言。",
  ui_story_5038_50381401_34_dialog_content = "行了二位，在下來給你們開路吧。",
  ui_story_5038_50381401_35_dialog_content = "嗯，我們繼續往前。",
  ui_story_5038_50381401_36_dialog_content = "除開消滅暗鬼，仲某還有件事想做。",
  ui_story_5038_50381401_37_dialog_content = "欸，什麼事非要在這艘船上做？",
  ui_story_5038_50381401_38_dialog_content = "若是我沒看錯，此處乃蜃風號舊船。",
  ui_story_5038_50381401_39_dialog_content = "它與仲某有些淵源。",
  ui_story_5038_50381401_40_dialog_content = "啊，原來是傳聞裡失事的那艘……",
  ui_story_5038_50381401_41_dialog_content = "船上存著一件舊物。",
  ui_story_5038_50381401_42_dialog_content = "在此船焚燒殆盡之前，仲某要將其取回。",
  ui_story_5038_50381401_43_dialog_content = "是很重要的東西？",
  ui_story_5038_50381401_44_dialog_content = "嗯，是能助我們返回龍洲的東西。",
  ui_story_5038_50381401_45_dialog_content = "（「羅盤」許久無人照料，不知是否無恙。）",
  ui_story_5038_50381401_46_dialog_content = "（哎，說來也是可笑。）",
  ui_story_5038_50381401_47_dialog_content = "（浩然兩片大陸之間，紐帶竟全繫於一條魚身上。）",
  ui_story_5038_50381401_48_dialog_content = "<color=#e8d9bb>嗒、嗒、嗒……</color>",
  ui_story_5038_50381401_49_dialog_content = "嗯？",
  ui_story_5038_50381401_50_dialog_content = "等一下，我好像聽到了什麼聲音？",
  ui_story_5038_50381401_51_dialog_content = "是躲在哪裡的暗鬼嗎？",
  ui_story_5038_50381401_52_dialog_content = "不對，殿下。這聲音……",
  ui_story_5038_50381401_53_dialog_content = "<color=#e8d9bb>嗒、嗒……</color>",
  ui_story_5038_50381401_54_dialog_content = "這聲音是腳步聲。",
  ui_story_5038_50381401_55_dialog_content = "腳步聲？！除了我們還有其他人嗎？",
  ui_story_5038_50381401_56_dialog_content = "是、你。",
  ui_story_5038_50381401_57_dialog_content = "！！！",
  ui_story_5038_50381401_58_dialog_content = "是誰？！誰的聲音！",
  ui_story_5038_50381401_59_dialog_content = "請站出來當面……",
  ui_story_5038_50381401_60_dialog_content = "「束」。",
  ui_story_5038_50381401_61_dialog_content = "嗚哇——！",
  ui_story_5038_50381401_62_dialog_content = "殿下！我抓住您了！",
  ui_story_5038_50381401_63_dialog_content = "妳、妳快看！！！",
  ui_story_5038_50381401_64_dialog_content = "仲胥先生他——",
  ui_story_5038_50381401_65_dialog_content = "咳……",
  ui_story_5038_50381401_66_dialog_content = "你是誰？",
  ui_story_5038_50381401_67_dialog_content = "我、認、識、你。",
  ui_story_5038_50381401_68_dialog_content = "可我不認識……",
  ui_story_5038_50381401_69_dialog_content = "等等，你的尾巴？！",
  ui_story_5038_50381401_70_dialog_content = "你、在、船、上。",
  ui_story_5038_50381401_71_dialog_content = "那是螭龍魚的尾巴。",
  ui_story_5038_50381401_72_dialog_content = "那是林家人的特徵，你是林家人？",
  ui_story_5038_50381401_73_dialog_content = "你、幫、林、家。",
  ui_story_5038_50381401_74_dialog_content = "不，你不可能是林家人。",
  ui_story_5038_50381401_75_dialog_content = "那件事情過後，舊船上已無活口。",
  ui_story_5038_50381401_76_dialog_content = "會出現在這裡的，只有林家之物。",
  ui_story_5038_50381401_77_dialog_content = "你、的、名、字。",
  ui_story_5038_50381401_78_dialog_content = "仲、胥。",
  ui_story_5038_50381401_79_dialog_content = "你只能是那個東西。",
  ui_story_5038_50381401_80_dialog_content = "那個林家最珍貴的寶物。",
  ui_story_5038_50381401_81_dialog_content = "你是「尤」。",
  ui_story_5038_50381401_82_dialog_content = "那個小孩什麼來頭？他傷了仲胥大人？！",
  ui_story_5038_50381401_83_dialog_content = "小心些，他力量很強。",
  ui_story_5038_50381401_84_dialog_content = "如此年幼的小孩，怎會……",
  ui_story_5038_50381401_85_dialog_content = "莫、莫非他是祟靈？",
  ui_story_5038_50381401_86_dialog_content = "沒想到，你變成了這般樣貌……",
  ui_story_5038_50381401_87_dialog_content = "為何對我發起攻擊？",
  ui_story_5038_50381401_88_dialog_content = "林、家、該、死。",
  ui_story_5038_50381401_89_dialog_content = "……果然，你憎恨他們。",
  ui_story_5038_50381401_90_dialog_content = "是因為你所遭的囚禁吧。",
  ui_story_5038_50381401_91_dialog_content = "船、上、所、有、人。",
  ui_story_5038_50381401_92_dialog_content = "該、死。",
  ui_story_5038_50381401_93_dialog_content = "我，還有林家人，早就預想到你會心懷憎恨。",
  ui_story_5038_50381401_94_dialog_content = "只是我們都沒想到，會有直面憎恨的這一天。",
  ui_story_5038_50381401_95_dialog_content = "船、最、該、死。",
  ui_story_5038_50381401_96_dialog_content = "儘管憎恨吧，這是你的權利。",
  ui_story_5038_50381401_97_dialog_content = "前人的遺落由後人拾起，前人的虧欠由後人償還。",
  ui_story_5038_50381401_98_dialog_content = "有的人比較倒楣，夾在了兩者之間。",
  ui_story_5038_50381401_99_dialog_content = "老林啊，我又幫了你個大忙。",
  ui_story_5038_50381401_100_dialog_content = "你、們、全、都、是。",
  ui_story_5038_50381401_101_dialog_content = "海、的、敵、人。",
  ui_story_5038_50381401_102_dialog_content = "你、們、與、船。",
  ui_story_5038_50381401_103_dialog_content = "沉、入、大、海。",
  ui_story_5038_50381401_104_dialog_content = "嗚哇！腳下……",
  ui_story_5038_50381401_105_dialog_content = "等一下，尤！！！",
  ui_story_5038_50381401_106_dialog_content = "嗯？是、是厘青的聲音！",
  ui_story_5038_50381401_107_dialog_content = "呼、呼——終於追上你了！",
  ui_story_5038_50381401_108_dialog_content = "厘、青……",
  ui_story_5038_50381401_109_dialog_content = "原來「羅盤」竟是這副模樣。",
  ui_story_5038_50381401_110_dialog_content = "嗯？怎麼大家都出現在這裡？發生什麼了？",
  ui_story_5038_50381401_111_dialog_content = "你們三個原來在這啊！",
  ui_story_5038_50381401_112_dialog_content = "發生了什麼？那小孩又是誰啊？",
  ui_story_5038_50381401_113_dialog_content = "那個小孩是我們一直在尋找的「羅盤」。",
  ui_story_5038_50381401_114_dialog_content = "「羅盤」？！",
  ui_story_5038_50381401_115_dialog_content = "人算不如天算，在下當時怎麼沒有算到……",
  ui_story_5038_50381401_116_dialog_content = "等等，當初那三簽！",
  ui_story_5038_50381401_117_dialog_content = "這三卦怪異至極，分別是「首鼠兩端」、「猿猴取月」、「狡兔三窟」。",
  ui_story_5038_50381401_118_dialog_content = "正所謂假作真時真亦假，這三簽是告訴在下，要尋找合適的<color=#FFB400>替代品</color>。",
  ui_story_5038_50381401_119_dialog_content = "對了！原來是這般含義！",
  ui_story_5038_50381401_120_dialog_content = "嗯？你在說什麼？",
  ui_story_5038_50381401_121_dialog_content = "此三簽預示了我們此行的從頭至尾。",
  ui_story_5038_50381401_122_dialog_content = "首簽「首鼠兩端」為始，說的是船長在尋找「羅盤」和抵達龍洲間猶豫不定。",
  ui_story_5038_50381401_123_dialog_content = "末簽「狡兔三窟」為終，說的是「羅盤」不知其何物，不知其何用，亦不知其何處。",
  ui_story_5038_50381401_124_dialog_content = "中簽「猿猴取月」則是連結前後兩者的途徑。",
  ui_story_5038_50381401_125_dialog_content = "踏不可行之路，行不可為之事，方可由始及終。",
  ui_story_5038_50381401_126_dialog_content = "而這三簽合為一處，真正所示的替代品並非旁物。",
  ui_story_5038_50381401_127_dialog_content = "正是蜃風船的新舊交替啊！",
  ui_story_5038_50381401_128_dialog_content = "尤，你到底在做什麼！",
  ui_story_5038_50381401_129_dialog_content = "你要殺了老哥嗎？",
  ui_story_5038_50381401_130_dialog_content = "……",
  ui_story_5038_50381401_131_dialog_content = "不只是我，他還要沉了蜃風。",
  ui_story_5038_50381401_132_dialog_content = "為什麼要這樣……",
  ui_story_5038_50381401_133_dialog_content = "我知道你在小小的魚缸裡過得很憋屈。",
  ui_story_5038_50381401_134_dialog_content = "我知道你心懷不滿、憤怒甚至怨恨。",
  ui_story_5038_50381401_135_dialog_content = "可是人與人是不一樣的，並非所有人都想害你。",
  ui_story_5038_50381401_136_dialog_content = "不該由無辜之人來為惡人替罪啊！",
  ui_story_5038_50381401_137_dialog_content = "你、不、該、出、來。",
  ui_story_5038_50381401_138_dialog_content = "為什麼？",
  ui_story_5038_50381401_139_dialog_content = "出、來、會、死。",
  ui_story_5038_50381401_140_dialog_content = "<color=#e8d9bb>啪——！！！</color>",
  ui_story_5038_50381401_141_dialog_content = "嗚哇哇哇！甲板裂開了嗎？！",
  ui_story_5038_50381401_142_dialog_content = "等一下尤！真的要這樣嗎？",
  ui_story_5038_50381401_143_dialog_content = "這裡的大家沒做錯過什麼呀！尤其是我！",
  ui_story_5038_50381401_144_dialog_content = "忘了我每天給你餵食的日子了嗎！",
  ui_story_5038_50381401_145_dialog_content = "<color=#e8d9bb>啪——！！！</color>",
  ui_story_5038_50381401_146_dialog_content = "你你你！",
  ui_story_5038_50381401_X146_dialog_content = "他現在聽不進別人的話，任由他鬧下去全船人都會沒命。",
  ui_story_5038_50381401_X147_dialog_content = "先想辦法停止他的行動吧。",
  ui_story_5038_50381401_147_dialog_content = "沒用的，老弟。他對你的些許好感蓋不過磅礴的恨。",
  ui_story_5038_50381401_148_dialog_content = "還指望那點魚食能買來全船人的命嗎？",
  ui_story_5038_50381401_149_dialog_content = "可是……",
  ui_story_5038_50381401_150_dialog_content = "蜃風號可不會任人宰割。",
  ui_story_5038_50381401_151_dialog_content = "想要胡作非為，經過我們的同意了嗎？",
  ui_story_5038_50381401_152_dialog_content = "就是啊！想對蜃風號出手，我們絕不答應！",
  ui_story_5038_50381401_153_dialog_content = "嘶，對小孩子出手是否不太道德……",
  ui_story_5038_50381401_154_dialog_content = "他是祟靈，年紀說不定夠當你爺爺了。",
  ui_story_5038_50381401_155_dialog_content = "他要發起攻擊了！",
  ui_story_5038_50381401_156_dialog_content = "大家，做好戰鬥準備！",
  ui_story_5038_50381402_1_dialog_content = "走、開。",
  ui_story_5038_50381402_2_dialog_content = "他的力量減弱了很多！",
  ui_story_5038_50381402_3_dialog_content = "看樣子，對我們發動攻擊已經非常吃力了。",
  ui_story_5038_50381402_4_dialog_content = "嗯。他剛成為祟靈不久，對力量的控制還不熟練。",
  ui_story_5038_50381402_5_dialog_content = "太多沒有目標的攻擊反而將力量耗盡了。",
  ui_story_5038_50381402_6_dialog_content = "別給他做困獸之鬥的機會，趁現在把他擒住。",
  ui_story_5038_50381402_7_dialog_content = "好，我來幫妳！",
  ui_story_5038_50381402_8_dialog_content = "沉、沒。",
  ui_story_5038_50381402_9_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_5038_50381402_10_dialog_content = "他、他在攻擊我們腳下的船！",
  ui_story_5038_50381402_11_dialog_content = "而且我沒看錯的話……海裡有不少螭龍魚正聚集過來！",
  ui_story_5038_50381402_12_dialog_content = "厘青，動手。",
  ui_story_5038_50381402_13_dialog_content = "我知道！",
  ui_story_5038_50381402_14_dialog_content = "尤，真沒想到，我們從朋友變成同類了。",
  ui_story_5038_50381402_15_dialog_content = "厘、青……",
  ui_story_5038_50381402_16_dialog_content = "你學會了使用語言。",
  ui_story_5038_50381402_17_dialog_content = "別、擋、我。",
  ui_story_5038_50381402_18_dialog_content = "可惜我們沒什麼交談的機會。",
  ui_story_5038_50381402_19_dialog_content = "讓、開。",
  ui_story_5038_50381402_20_dialog_content = "囂張什麼，作為崇靈我可是你的前輩！",
  ui_story_5038_50381402_21_dialog_content = "你還有很多不會的事情呢！",
  ui_story_5038_50381402_22_dialog_content = "作為前輩我很想教給你，但是……",
  ui_story_5038_50381402_23_dialog_content = "要等我打贏你之後！",
  ui_story_5038_50381402_24_dialog_content = "（月白，就現在！）",
  ui_story_5038_50381402_25_dialog_content = "！！！",
  ui_story_5038_50381402_26_dialog_content = "別想動我的船。",
  ui_story_5038_50381402_27_dialog_content = "呃……嗚……",
  ui_story_5038_50381402_28_dialog_content = "他受傷了！我們快去把他制住！",
  ui_story_5038_50381402_29_dialog_content = "好！我按住他的左臂了！",
  ui_story_5038_50381402_30_dialog_content = "殿下，右臂交給我就好。",
  ui_story_5038_50381402_31_dialog_content = "你、你們，不用那麼使勁的。",
  ui_story_5038_50381402_32_dialog_content = "他已經失去力量了。",
  ui_story_5038_50381402_33_dialog_content = "嗯？是嗎？",
  ui_story_5038_50381402_34_dialog_content = "嘶……嘶……",
  ui_story_5038_50381402_35_dialog_content = "……魚是不會叫的。他還沒學會如何發出痛苦的聲音。",
  ui_story_5038_50381402_36_dialog_content = "呼——終於贏了。",
  ui_story_5038_50381402_37_dialog_content = "我們算是把「羅盤」拿下了？",
  ui_story_5038_50381402_38_dialog_content = "是的，他就是「羅盤」無疑。",
  ui_story_5038_50381402_39_dialog_content = "即便變成了祟靈，「羅盤」的功能仍舊沒有改變。",
  ui_story_5038_50381402_40_dialog_content = "那我們，接下來是要怎麼做？",
  ui_story_5038_50381402_41_dialog_content = "……",
  ui_story_5038_50381402_42_dialog_content = "……",
  ui_story_5038_50381402_43_dialog_content = "依照「羅盤」的用法，我們需要把他囚禁在蜃風號上。",
  ui_story_5038_50381402_44_dialog_content = "然後，誘使他發出「溯遊」的訊號。",
  ui_story_5038_50381402_45_dialog_content = "螭龍魚群收到首領的訊號後，會聚集在蜃風周圍，推動我們重返龍洲。",
  ui_story_5038_50381402_46_dialog_content = "這趟旅程將不會再有任何危險，就像之前的無數次航行一樣。",
  ui_story_5038_50381402_47_dialog_content = "欸……",
  ui_story_5038_50381402_48_dialog_content = "我們要，囚禁這樣一個小孩子嗎？",
  ui_story_5038_50381402_49_dialog_content = "哎呀，航行順利是好事，可這方式讓人心裡不舒服啊。",
  ui_story_5038_50381402_50_dialog_content = "是的，尤其在剛剛見識了他的憎恨之後。",
  ui_story_5038_50381402_51_dialog_content = "林家先祖最先激發了這份憎恨，每一位登船的過客又讓它逐步加深。",
  ui_story_5038_50381402_52_dialog_content = "所有人都心存僥倖，一廂情願地認為「羅盤」只是一條魚，它不會憎恨。",
  ui_story_5038_50381402_53_dialog_content = "只要恨不存在，罪過便無從談起，也不必心懷歉疚。",
  ui_story_5038_50381402_54_dialog_content = "可真等到憎恨出現在眼前，再想談後悔已是晚了。",
  ui_story_5038_50381402_55_dialog_content = "……仲胥先生您後悔嗎？",
  ui_story_5038_50381402_56_dialog_content = "您也覺得囚禁「羅盤」是錯的吧。",
  ui_story_5038_50381402_57_dialog_content = "我為許多事情而後悔。",
  ui_story_5038_50381402_58_dialog_content = "造下那些殺孽是錯的，執著於「羅盤」也是錯的。",
  ui_story_5038_50381402_59_dialog_content = "原本該在陸地上解決的問題被放到了海上，最終導致了現在的局面。",
  ui_story_5038_50381402_60_dialog_content = "那我們……還要延續之前的錯誤嗎？",
  ui_story_5038_50381402_61_dialog_content = "以仲某的歲數，若是有機會償還罪過，搭上性命亦不足惜。",
  ui_story_5038_50381402_62_dialog_content = "可是，此處並非只有仲某一人。",
  ui_story_5038_50381402_63_dialog_content = "不利用「羅盤」，蜃風還有望抵達龍洲嗎？",
  ui_story_5038_50381402_64_dialog_content = "這個……",
  ui_story_5038_50381402_65_dialog_content = "嘶，蜃風遭受了撞擊，還不知損害如何……",
  ui_story_5038_50381402_66_dialog_content = "我明白老哥的意思，這個問題我想過很多次。",
  ui_story_5038_50381402_67_dialog_content = "身在海上，許多事情身不由己。",
  ui_story_5038_50381402_68_dialog_content = "我把尤當作朋友，也想過要還他自由，可是……",
  ui_story_5038_50381402_69_dialog_content = "我接受不了這樣做的代價。",
  ui_story_5038_50381402_70_dialog_content = "代價……",
  ui_story_5038_50381402_71_dialog_content = "（大家都不說話了。）",
  ui_story_5038_50381402_72_dialog_content = "（幾道目光在空氣中交錯，用這一點點行動來編織著無助。）",
  ui_story_5038_50381402_73_dialog_content = "（像是在沉默中進行一場懺悔。）",
  ui_story_5038_50381402_74_dialog_content = "（我們知道那是錯誤，可是又別無選擇。）",
  ui_story_5038_50381402_75_dialog_content = "不必都陰沉著臉吧。",
  ui_story_5038_50381402_76_dialog_content = "我們找到了「羅盤」，目標已經達成，應當更開心些。",
  ui_story_5038_50381402_77_dialog_content = "……船長，航行有望順利完成，確是值得開心的事情。",
  ui_story_5038_50381402_78_dialog_content = "可是，一想到要囚禁這個孩子就……",
  ui_story_5038_50381402_79_dialog_content = "誰說要囚禁他了，有這個必要嗎？",
  ui_story_5038_50381402_80_dialog_content = "什麼？！",
  ui_story_5038_50381402_81_dialog_content = "船長，您這是何意？",
  ui_story_5038_50381402_82_dialog_content = "我們是要找到「羅盤」，只有這樣才能抵達龍洲。",
  ui_story_5038_50381402_83_dialog_content = "但找到之後，該如何利用它尚有多種選擇。",
  ui_story_5038_50381402_84_dialog_content = "林家先祖的選擇看來大家都不喜歡。",
  ui_story_5038_50381402_85_dialog_content = "那麼，我會做出新的選擇。",
  ui_story_5038_50381402_86_dialog_content = "真的嗎？可以不用囚禁尤？",
  ui_story_5038_50381402_87_dialog_content = "……",
  ui_story_5038_50381402_88_dialog_content = "我問你，願意做蜃風號的客人嗎？",
  ui_story_5038_50381402_89_dialog_content = "……不。",
  ui_story_5038_50381402_90_dialog_content = "當、然、不。",
  ui_story_5038_50381402_91_dialog_content = "既然如此，蜃風與你的緣分已盡。",
  ui_story_5038_50381402_92_dialog_content = "腳下這艘船不久就要沉沒，你快回到海裡去吧。",
  ui_story_5038_50381402_93_dialog_content = "其他人把他放開，我們回蜃風。",
  ui_story_5038_50381402_94_dialog_content = "真、真的可以嗎？",
  ui_story_5038_50381402_95_dialog_content = "把他放走容易，再想找回來可就難了。",
  ui_story_5038_50381402_96_dialog_content = "他是條魚，回到海裡比待在船上更加合適。",
  ui_story_5038_50381402_97_dialog_content = "走吧，霧氣已經散去，我們該揚帆出發了。",
  ui_story_5038_50381402_98_dialog_content = "妳已經考慮清楚了？",
  ui_story_5038_50381402_99_dialog_content = "是的。",
  ui_story_5038_50381402_100_dialog_content = "仲胥大人，您要阻攔我嗎？",
  ui_story_5038_50381402_101_dialog_content = "我向老林承諾過，要幫他守住林家根基。",
  ui_story_5038_50381402_102_dialog_content = "如今「羅盤」交到林家新一代人手上，承諾已然兌現。",
  ui_story_5038_50381402_103_dialog_content = "只要妳清楚這個決定的重量，我便尊重妳的選擇。",
  ui_story_5038_50381402_104_dialog_content = "走吧，船長已經下令了。",
  ui_story_5038_50381402_105_dialog_content = "她比我們更清楚航海需要些什麼。",
  ui_story_5038_50381402_106_dialog_content = "唉，是啊，我們瞎操心什麼呢。",
  ui_story_5038_50381402_107_dialog_content = "走了走了。PlayerName，快跟上來啊，發什麼呆呢？",
  ui_story_5038_50381402_108_dialog_content = "哦，我在看海裡的螭龍魚。",
  ui_story_5038_50381402_109_dialog_content = "好壯觀啊，牠們在船邊不停地環繞。",
  ui_story_5038_50381402_110_dialog_content = "就像在等著船隻沉沒一樣。",
  ui_story_5038_50381402_111_dialog_content = "別矯情了，回蜃風號一樣能看。",
  ui_story_5038_50381402_112_dialog_content = "先動起來吧。",
  ui_story_5038_50381402_113_dialog_content = "哈哈，來了來了。",
  ui_story_5038_50381402_114_dialog_content = "恭喜你啊，尤！你自由了！",
  ui_story_5038_50381402_115_dialog_content = "自、由……",
  ui_story_5038_50381402_116_dialog_content = "還沒明白嗎，他們說了要放你走。",
  ui_story_5038_50381402_117_dialog_content = "好不容易變成祟靈了，以後要多練習說話啊。",
  ui_story_5038_50381402_118_dialog_content = "跟你聊天太費勁了。",
  ui_story_5038_50381402_119_dialog_content = "放、我、走？",
  ui_story_5038_50381402_120_dialog_content = "是啊，聽不明白嗎？",
  ui_story_5038_50381402_121_dialog_content = "去你該去的地方吧。",
  ui_story_5038_50381402_122_dialog_content = "我……",
  ui_story_5038_50381402_123_dialog_content = "我要走了，我可不能掉進海裡。",
  ui_story_5038_50381402_124_dialog_content = "別忘了，厘青是尤的朋友。",
  ui_story_5038_50381402_125_dialog_content = "拜拜——",
  ui_story_5038_50381402_126_dialog_content = "哎喲船長！您可回來了！",
  ui_story_5038_50381402_127_dialog_content = "剛才蜃風號被撞，又遭到暗鬼襲擊，不少地方有了破損。",
  ui_story_5038_50381402_128_dialog_content = "大家正在努力搶修……",
  ui_story_5038_50381402_129_dialog_content = "我知道了。維修工作別停，立刻把帆張開。",
  ui_story_5038_50381402_130_dialog_content = "我們現在就出發。",
  ui_story_5038_50381402_131_dialog_content = "現在？大家不休整一下嗎？",
  ui_story_5038_50381402_132_dialog_content = "沒有等待的時間了。",
  ui_story_5038_50381402_133_dialog_content = "螭龍魚馬上會開始溯遊，我們得跟上牠們。",
  ui_story_5038_50381402_134_dialog_content = "螭龍魚？",
  ui_story_5038_50381402_135_dialog_content = "哇真的！海裡的螭龍魚遊起來了！",
  ui_story_5038_50381402_136_dialog_content = "牠們全都在向著一個方向前進！",
  ui_story_5038_50381402_137_dialog_content = "那是龍洲的方向。",
  ui_story_5038_50381402_138_dialog_content = "在海裡，沒有什麼比牠們更渴望回家。",
  ui_story_5038_50381402_139_dialog_content = "哦，我好像明白了！",
  ui_story_5038_50381402_140_dialog_content = "月白你把尤放走，螭龍魚就會重新開始溯遊。",
  ui_story_5038_50381402_141_dialog_content = "利用牠們引路，蜃風就能走上最快返回龍洲的航線！",
  ui_story_5038_50381402_142_dialog_content = "道理是很簡單的。不過，跟上螭龍魚並不容易。",
  ui_story_5038_50381402_143_dialog_content = "最後一段行程，還需船上各位多多助力。",
  ui_story_5038_50381402_144_dialog_content = "嗯！一定會的！",
  ui_story_5038_50381402_145_dialog_content = "哎喲，船底漏水止不住了。",
  ui_story_5038_50381402_146_dialog_content = "快去多叫點人來！",
  ui_story_5038_50381402_147_dialog_content = "沒有人了，所有船工都忙得要死。",
  ui_story_5038_50381402_148_dialog_content = "海上風浪很大，蜃風號帶著破損前進非常吃力。",
  ui_story_5038_50381402_149_dialog_content = "這裡還堅持得住嗎？",
  ui_story_5038_50381402_150_dialog_content = "之前用兔耳封住的縫隙又開始漏水了。",
  ui_story_5038_50381402_151_dialog_content = "我們在用力往外舀，但水位還是不斷上漲啊。",
  ui_story_5038_50381402_152_dialog_content = "漏水……這可怎麼辦……",
  ui_story_5038_50381402_153_dialog_content = "算了，既然大家都很忙，就不用管我們了。",
  ui_story_5038_50381402_154_dialog_content = "接下來舀得更快些便是。",
  ui_story_5038_50381402_155_dialog_content = "你看，在下現在一手拎著一個水桶。",
  ui_story_5038_50381402_156_dialog_content = "等會在下嘴上再叼一個，一人舀三份水！",
  ui_story_5038_50381402_157_dialog_content = "這、這樣真的可以嗎？",
  ui_story_5038_50381402_158_dialog_content = "沒什麼不可以的，就剩最後一段路，大家全都拼了。",
  ui_story_5038_50381402_159_dialog_content = "只要船還在全速行駛，就沒什麼可怕的。",
  ui_story_5038_50381402_160_dialog_content = "你走吧，別耽誤在下幹活了！",
  ui_story_5038_50381402_161_dialog_content = "誰那還有空桶？遞給我一個！",
  ui_story_5038_50381402_162_dialog_content = "PlayerName公子！這邊這邊！",
  ui_story_5038_50381402_163_dialog_content = "過來幫我個忙！",
  ui_story_5038_50381402_164_dialog_content = "怎麼了丹棠？妳這是在……",
  ui_story_5038_50381402_165_dialog_content = "固定船帆的絞盤壞了，現在只能靠人來把它拽住。",
  ui_story_5038_50381402_166_dialog_content = "之前一直是我在拽，不過……",
  ui_story_5038_50381402_167_dialog_content = "風好像變大了，我一個人有些吃力。",
  ui_story_5038_50381402_168_dialog_content = "哦哦！那我來幫妳！",
  ui_story_5038_50381402_169_dialog_content = "就這樣一直拽著嗎？",
  ui_story_5038_50381402_170_dialog_content = "嗯，一直拽著。",
  ui_story_5038_50381402_171_dialog_content = "妳的手掌好像都紅了，沒事吧？",
  ui_story_5038_50381402_172_dialog_content = "沒事沒事，只是平日裡疏於鍛鍊。",
  ui_story_5038_50381402_173_dialog_content = "要是這點小事都做不來，我也太沒用了。",
  ui_story_5038_50381402_174_dialog_content = "還不知道要堅持多久，再這樣下去妳的手……",
  ui_story_5038_50381402_175_dialog_content = "那有什麼，蜃風號都在堅持呢。",
  ui_story_5038_50381402_176_dialog_content = "把這個箱子丟下去！",
  ui_story_5038_50381402_177_dialog_content = "是！",
  ui_story_5038_50381402_178_dialog_content = "哇，丟東西還挺爽的！",
  ui_story_5038_50381402_179_dialog_content = "還有這個！這個也一起丟了！",
  ui_story_5038_50381402_180_dialog_content = "都不要了嗎？這裡可是全部的被褥……",
  ui_story_5038_50381402_181_dialog_content = "不要了，現在哪有工夫睡覺。",
  ui_story_5038_50381402_182_dialog_content = "好嘞，這箱也丟掉！",
  ui_story_5038_50381402_183_dialog_content = "一切不必要的東西全都丟掉，能減重多少就減重多少。",
  ui_story_5038_50381402_184_dialog_content = "我們可是在跟大海搶時間啊。",
  ui_story_5038_50381402_185_dialog_content = "說的也是……",
  ui_story_5038_50381402_186_dialog_content = "丟吧，全都丟了！",
  ui_story_5038_50381402_187_dialog_content = "還有家具，所有桌子、椅子，能搬動的全丟進海裡！",
  ui_story_5038_50381402_188_dialog_content = "（蜃風號上的人們從未如此忙碌過。）",
  ui_story_5038_50381402_189_dialog_content = "（每一個人，每一樣工具，都在最大限度地發揮作用。）",
  ui_story_5038_50381402_190_dialog_content = "（蜃風的面前有兩個終點，一個是沉沒，另一個則是龍洲。）",
  ui_story_5038_50381402_191_dialog_content = "（現實與願望在比拼誰更加有力。）",
  ui_story_5038_50381402_192_dialog_content = "（我們遠望著陸地的方向，太陽從地平線升起，船隻向海平面下沉。）",
  ui_story_5038_50381402_193_dialog_content = "（命運在迫不及待地想要宣布結局。）",
  ui_story_5038_50381402_194_dialog_content = "不行了不行了！整個貨艙都淹了！",
  ui_story_5038_50381402_195_dialog_content = "老船員們，有沒有什麼辦法？",
  ui_story_5038_50381402_196_dialog_content = "全都淹了……",
  ui_story_5038_50381402_197_dialog_content = "這能有什麼辦法，船艙都淹了的話，接下來……",
  ui_story_5038_50381402_198_dialog_content = "嗚哇啊！水漫上甲板了！！！",
  ui_story_5038_50381402_199_dialog_content = "怎麼辦啊，有沒有什麼辦法……",
  ui_story_5038_50381402_200_dialog_content = "我、我們要沉船了嗎？",
  ui_story_5038_50381402_201_dialog_content = "該做什麼該做什麼……",
  ui_story_5038_50381402_202_dialog_content = "船長！船長！！！",
  ui_story_5038_50381402_203_dialog_content = "您去哪了？您看現在……",
  ui_story_5038_50381402_204_dialog_content = "都別慌張，在甲板上站好。",
  ui_story_5038_50381402_205_dialog_content = "蜃風號不會沉沒的。",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>砰、砰、砰、砰——</color>",
  ui_story_5038_50381402_207_dialog_content = "什、什麼動靜？！",
  ui_story_5038_50381402_208_dialog_content = "好像有什麼東西在撞擊船底……",
  ui_story_5038_50381402_209_dialog_content = "等等等等！你們有沒有感覺到，我們在往上升？",
  ui_story_5038_50381402_210_dialog_content = "哦真的是！到底怎麼回……",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>唰——！！！</color>",
  ui_story_5038_50381402_212_dialog_content = "哇啊啊啊啊！飛起來了嗎！",
  ui_story_5038_50381402_213_dialog_content = "你、你們往下看！是魚！好多螭龍魚！",
  ui_story_5038_50381402_214_dialog_content = "牠們把蜃風號馱起來了！",
  ui_story_5038_50381402_215_dialog_content = "真的是！這也太壯觀了！",
  ui_story_5038_50381402_216_dialog_content = "我說過吧，螭龍魚回到海裡比待在船上更加合適。",
  ui_story_5038_50381402_217_dialog_content = "哦對！是尤在幫助我們！",
  ui_story_5038_50381402_218_dialog_content = "尤！你在這裡嗎！",
  ui_story_5038_50381402_219_dialog_content = "謝謝你！！！",
  ui_story_5038_50381402_220_dialog_content = "月白，妳放走尤的時候就知道會發生這種事嗎？",
  ui_story_5038_50381402_221_dialog_content = "不知道。大海變幻莫測，誰也沒法預知海上的每一件事。",
  ui_story_5038_50381402_222_dialog_content = "我只知道，我們完成了每一個目標，為航行做足了努力。",
  ui_story_5038_50381402_223_dialog_content = "我們一定能抵達龍洲。",
  ui_story_5038_50381501_1_dialog_content = "仲胥先生來了嗎？",
  ui_story_5038_50381501_2_dialog_content = "快點，把大人請到這邊。",
  ui_story_5038_50381501_3_dialog_content = "來了來了。一個個不知道幫忙，就知道催。",
  ui_story_5038_50381501_4_dialog_content = "厘青老弟，這是要幹嘛？",
  ui_story_5038_50381501_5_dialog_content = "老哥，大家怕你蝸居在船艙中錯過美景。",
  ui_story_5038_50381501_6_dialog_content = "快看，那邊是什麼？",
  ui_story_5038_50381501_7_dialog_content = "那是……",
  ui_story_5038_50381501_8_dialog_content = "我們回來了？",
  ui_story_5038_50381501_9_dialog_content = "是啊，我們回來了！前面就是龍洲！",
  ui_story_5038_50381501_10_dialog_content = "想它了嗎？",
  ui_story_5038_50381501_11_dialog_content = "龍洲……",
  ui_story_5038_50381501_12_dialog_content = "於我數十載人生中，很少用「龍洲」二字稱呼腳下的土地。",
  ui_story_5038_50381501_13_dialog_content = "沒想到如今聽你提起它，竟然十分懷念。",
  ui_story_5038_50381501_14_dialog_content = "我們果真離開了許久啊。",
  ui_story_5038_50381501_15_dialog_content = "是啊。我們經歷了那麼多事情，去到了那麼遠的地方。",
  ui_story_5038_50381501_16_dialog_content = "一來一回之間，船換了一艘，座下也添了副輪椅。",
  ui_story_5038_50381501_17_dialog_content = "再想登上朝堂向聖上下跪，可就沒那麼容易了。",
  ui_story_5038_50381501_18_dialog_content = "老哥你對龍洲的念想就只是朝堂嗎？",
  ui_story_5038_50381501_19_dialog_content = "活到我這個歲數最容易念舊。",
  ui_story_5038_50381501_20_dialog_content = "無論是朝堂之上還是四海之下，我踏足過的地方都會留下念想。",
  ui_story_5038_50381501_21_dialog_content = "和你說話總是彎彎繞繞，費勁得很。",
  ui_story_5038_50381501_22_dialog_content = "你就說，能在甲板上欣賞如此奇景，你歡喜不歡喜？",
  ui_story_5038_50381501_23_dialog_content = "呵呵，仲某歡喜極了。",
  ui_story_5038_50381501_24_dialog_content = "你們看那邊，螭龍魚群開始向遠處遊了！",
  ui_story_5038_50381501_25_dialog_content = "當然，牠們又不能跟著我們上岸。",
  ui_story_5038_50381501_26_dialog_content = "幫助我們行至港口之後，就該去做自己的事情了。",
  ui_story_5038_50381501_27_dialog_content = "被牠們馱著前行了這麼久，還有些捨不得。",
  ui_story_5038_50381501_28_dialog_content = "可能是被慣壞了吧。",
  ui_story_5038_50381501_29_dialog_content = "師父說過，離別總會令人不舍。",
  ui_story_5038_50381501_30_dialog_content = "既然留不住牠們，就好好說再見囉。",
  ui_story_5038_50381501_31_dialog_content = "是啊，旅途走到終點，就該跟同路人分離了。",
  ui_story_5038_50381501_32_dialog_content = "再見，謝謝你們！",
  ui_story_5038_50381501_33_dialog_content = "嗚嗚嗚……終於回來了……",
  ui_story_5038_50381501_34_dialog_content = "是啊，差點以為要死在海上了。",
  ui_story_5038_50381501_35_dialog_content = "真好，看到陸地就安心了。",
  ui_story_5038_50381501_36_dialog_content = "都得多謝船長啊，這一路沒有她的話，不知道要沉船幾次。",
  ui_story_5038_50381501_37_dialog_content = "當然！我們船長太厲害了！",
  ui_story_5038_50381501_38_dialog_content = "想想她帶著我們做成了什麼？",
  ui_story_5038_50381501_39_dialog_content = "我們把林家的海上航路恢復了！",
  ui_story_5038_50381501_40_dialog_content = "哎！船長過來了！",
  ui_story_5038_50381501_41_dialog_content = "船長，您快過來，大家正誇您呢！",
  ui_story_5038_50381501_42_dialog_content = "你們……",
  ui_story_5038_50381501_43_dialog_content = "聚在這裡遊手好閒幹嗎？快回自己位置。",
  ui_story_5038_50381501_44_dialog_content = "蜃風要準備靠岸了，別在最後出岔子。",
  ui_story_5038_50381501_45_dialog_content = "船長下令了，別出岔子，聽到沒有！",
  ui_story_5038_50381501_46_dialog_content = "是！！！",
  ui_story_5038_50381501_47_dialog_content = "我我我、我好像有點緊張。",
  ui_story_5038_50381501_48_dialog_content = "待會下船之後我該做什麼？",
  ui_story_5038_50381501_49_dialog_content = "緊張什麼，跟著我們就可以了啊！",
  ui_story_5038_50381501_50_dialog_content = "海上大風大浪都經歷過來了，陸地上還能更可怕嗎？",
  ui_story_5038_50381501_51_dialog_content = "可是……接下來的環境好陌生啊。",
  ui_story_5038_50381501_52_dialog_content = "我找不到一個熟悉的支點，自己還是孤身一人……",
  ui_story_5038_50381501_53_dialog_content = "怎麼能叫孤身一人呢，不是有我們在你身邊嗎？",
  ui_story_5038_50381501_54_dialog_content = "就是。",
  ui_story_5038_50381501_55_dialog_content = "到了龍洲之後在下可是真正的萬事通，保準讓你吃好喝好。",
  ui_story_5038_50381501_56_dialog_content = "好了好了，趕緊收拾行李吧。",
  ui_story_5038_50381501_57_dialog_content = "船長正在催促，我們要準備下船了！",
  ui_story_5038_50381501_58_dialog_content = "冰～糖～葫蘆～",
  ui_story_5038_50381501_59_dialog_content = "冰～糖～葫蘆～喲——",
  ui_story_5038_50381501_60_dialog_content = "大叔，冰糖葫蘆怎麼賣的？",
  ui_story_5038_50381501_61_dialog_content = "那邊有吹糖人的，快過去看看！",
  ui_story_5038_50381501_62_dialog_content = "我是不是聞到元宵的味道了？",
  ui_story_5038_50381501_63_dialog_content = "哇哇哇，好熱鬧的街道！",
  ui_story_5038_50381501_64_dialog_content = "好多人啊！",
  ui_story_5038_50381501_65_dialog_content = "怎麼樣，好玩不？",
  ui_story_5038_50381501_66_dialog_content = "我、我不知道。龍洲的街上總是這麼多人嗎？",
  ui_story_5038_50381501_67_dialog_content = "那倒不是。你來得巧，正趕上「春朔節」的尾巴。",
  ui_story_5038_50381501_68_dialog_content = "這是龍洲最熱鬧的節日，街上到處都是好吃的好玩的。",
  ui_story_5038_50381501_69_dialog_content = "你看，小孩子手裡握的那個叫「糖葫蘆」，酸酸甜甜的很好吃。",
  ui_story_5038_50381501_70_dialog_content = "那邊桌子上擺擺成一排的玩意叫「糖人」，是用糖吹起來的，只能看不能吃。",
  ui_story_5038_50381501_71_dialog_content = "然後前面一口大鍋裡煮著的叫「元宵」，是一種過節時才能吃到的小點心。",
  ui_story_5038_50381501_72_dialog_content = "喔哦，好豐富啊！",
  ui_story_5038_50381501_73_dialog_content = "有什麼好奇的都可以問我哦。",
  ui_story_5038_50381501_74_dialog_content = "我看看哦。",
  ui_story_5038_50381501_75_dialog_content = "那邊在地上搭個席子，手裡搖晃著木簽的是在做……",
  ui_story_5038_50381501_76_dialog_content = "哎喲那可不是什麼好事啊！是騙人錢的！",
  ui_story_5038_50381501_77_dialog_content = "騙錢？",
  ui_story_5038_50381501_78_dialog_content = "對，那個叫「算命」，不是什麼好事啊。",
  ui_story_5038_50381501_79_dialog_content = "攤主淨會裝神弄鬼，號稱要替人卜算吉兇。",
  ui_story_5038_50381501_80_dialog_content = "其實啊，就是編些吉祥話來騙人家錢。",
  ui_story_5038_50381501_81_dialog_content = "既然這麼壞，幹嘛不懲治他們？",
  ui_story_5038_50381501_82_dialog_content = "哎，這裡頭說不清道不明的，彎彎繞多著呢。",
  ui_story_5038_50381501_83_dialog_content = "總之您甭信他們。真想算算前程走勢，找在下就行了！",
  ui_story_5038_50381501_84_dialog_content = "找、找你？",
  ui_story_5038_50381501_85_dialog_content = "這不是壞事嗎？",
  ui_story_5038_50381501_86_dialog_content = "萬事吧，也要分人，沒那麼簡單的。",
  ui_story_5038_50381501_87_dialog_content = "哼哼。我們龍洲有句古話，叫「同行是冤家」。",
  ui_story_5038_50381501_88_dialog_content = "PlayerName公子，你細細琢磨吧～",
  ui_story_5038_50381501_89_dialog_content = "哎呀，讓開些讓開些。",
  ui_story_5038_50381501_90_dialog_content = "沒看到這裡有殘疾人嗎？",
  ui_story_5038_50381501_91_dialog_content = "厘青老弟，我們走慢點吧，別礙著旁人。",
  ui_story_5038_50381501_92_dialog_content = "那怎麼行。好不容易回到自己家了，當然要走得昂首闊步。",
  ui_story_5038_50381501_93_dialog_content = "不過船長姐姐，我們這一大幫人是要去什麼地方啊？",
  ui_story_5038_50381501_94_dialog_content = "蜃風是林家的商船，入港後自然該回林府。",
  ui_story_5038_50381501_95_dialog_content = "諸位若不嫌棄，可以一併來府上做客。",
  ui_story_5038_50381501_96_dialog_content = "節慶期間，家主一定希望多些客人。",
  ui_story_5038_50381501_97_dialog_content = "老哥，我們要去吧？",
  ui_story_5038_50381501_98_dialog_content = "我肚子餓了。",
  ui_story_5038_50381501_99_dialog_content = "當然要去，不邀請我也得去。",
  ui_story_5038_50381501_100_dialog_content = "你們林家主人可虧欠我不少呢。",
  ui_story_5038_50381501_101_dialog_content = "仲胥大人，春朔節期間哪有上門討債的。",
  ui_story_5038_50381501_102_dialog_content = "何況您堂堂一位將軍的要價，如今落魄的林家也出不起啊。",
  ui_story_5038_50381501_103_dialog_content = "出不起就對了。",
  ui_story_5038_50381501_104_dialog_content = "仲某就是想讓他欠著，然後愧疚一輩子。",
  ui_story_5038_50381501_105_dialog_content = "回來了！蜃風號的人回來了！",
  ui_story_5038_50381501_106_dialog_content = "哎喲真不容易！快請進來！",
  ui_story_5038_50381501_107_dialog_content = "一個個都累壞了吧？",
  ui_story_5038_50381501_108_dialog_content = "哇，這裡就是林家嗎？",
  ui_story_5038_50381501_109_dialog_content = "能造出蜃風號那麼大的船隻，沒想到房子還挺普通的。",
  ui_story_5038_50381501_110_dialog_content = "畢竟是落魄了呀。",
  ui_story_5038_50381501_111_dialog_content = "聽說以前的宅門可壯觀了。",
  ui_story_5038_50381501_112_dialog_content = "大宅門才不好呢，冷清得很。",
  ui_story_5038_50381501_113_dialog_content = "現在這樣，最有過年的氣氛！",
  ui_story_5038_50381501_114_dialog_content = "都回來了，就快些進屋吧。",
  ui_story_5038_50381501_115_dialog_content = "別在門口站著。",
  ui_story_5038_50381501_116_dialog_content = "咦，這位老爺爺是……",
  ui_story_5038_50381501_117_dialog_content = "家主，您怎麼出來了？",
  ui_story_5038_50381501_118_dialog_content = "蜃風號歸來，這麼大的事情，我哪能在屋裡擺譜。",
  ui_story_5038_50381501_119_dialog_content = "諸位是林家的功臣和貴客，在下沒去港口相迎，已是禮數不周了。",
  ui_story_5038_50381501_120_dialog_content = "說得對，該叫他大擺筵宴百里相迎。",
  ui_story_5038_50381501_121_dialog_content = "不然怎對得起他坐在家享的清福啊。",
  ui_story_5038_50381501_122_dialog_content = "仲兄，你回來了！",
  ui_story_5038_50381501_123_dialog_content = "你這腿……",
  ui_story_5038_50381501_124_dialog_content = "沒什麼，小傷而已。",
  ui_story_5038_50381501_125_dialog_content = "如此說來，仲某為朝廷征戰沙場，不過在身上添些傷疤。",
  ui_story_5038_50381501_126_dialog_content = "為你林家做事，卻折了雙腿。",
  ui_story_5038_50381501_127_dialog_content = "老林，你的面子要蓋過皇上了。",
  ui_story_5038_50381501_128_dialog_content = "仲兄，此話我如何擔待得起啊……",
  ui_story_5038_50381501_129_dialog_content = "你且在府中修養，我去為你尋些名醫，看看可有轉機。",
  ui_story_5038_50381501_130_dialog_content = "不必了，坐著輪椅倒也清閒。",
  ui_story_5038_50381501_131_dialog_content = "真讓哪個醫生治好了我的腿，不是駁我厘青老弟的面子嗎。",
  ui_story_5038_50381501_132_dialog_content = "不可能！",
  ui_story_5038_50381501_133_dialog_content = "你這腿準沒治了，誰來都沒用！",
  ui_story_5038_50381501_134_dialog_content = "這、這位小友怎麼出言不遜？",
  ui_story_5038_50381501_135_dialog_content = "呵呵，無礙。厘青老弟一向如此心直口快。",
  ui_story_5038_50381501_136_dialog_content = "此次一去，經歷頗豐啊……",
  ui_story_5038_50381501_137_dialog_content = "老林，「羅盤」我終究是沒能保住。",
  ui_story_5038_50381501_138_dialog_content = "仲兄……",
  ui_story_5038_50381501_139_dialog_content = "說這番話，是想讓我下不來台嗎？",
  ui_story_5038_50381501_140_dialog_content = "你能回來，已是千萬個不易了。",
  ui_story_5038_50381501_141_dialog_content = "林某無德，護不住家業，牽連了朋友。",
  ui_story_5038_50381501_142_dialog_content = "在此，向仲兄還有各位謝罪了。",
  ui_story_5038_50381501_143_dialog_content = "免了免了。",
  ui_story_5038_50381501_144_dialog_content = "無功不受祿，我沒保住「羅盤」，我們互不虧欠。",
  ui_story_5038_50381501_145_dialog_content = "倒是你林家後繼有人，不靠「羅盤」仍能往返於海上。",
  ui_story_5038_50381501_146_dialog_content = "那些矯情的話，留著向她說吧。",
  ui_story_5038_50381501_147_dialog_content = "對啊，沒有「羅盤」你們竟然能平安返航。",
  ui_story_5038_50381501_148_dialog_content = "月白，妳果真有出息啊。",
  ui_story_5038_50381501_149_dialog_content = "家主，此事我亦當向您謝罪。",
  ui_story_5038_50381501_150_dialog_content = "其實我們拿到了「羅盤」。只是後來，我將它放了。",
  ui_story_5038_50381501_151_dialog_content = "放了……",
  ui_story_5038_50381501_152_dialog_content = "我覺得祖上利用「羅盤」渡海的方式不妥，所以做了這樣的決定。",
  ui_story_5038_50381501_153_dialog_content = "雖問心無愧，可林家寶物畢竟折損在了我的手上。",
  ui_story_5038_50381501_154_dialog_content = "故此，月白向家主謝罪。",
  ui_story_5038_50381501_155_dialog_content = "哈哈哈哈。這哪是謝罪啊，這是責怪我呢。",
  ui_story_5038_50381501_156_dialog_content = "妳這話裡藏刀的本事，跟那仲胥老兒學的？",
  ui_story_5038_50381501_157_dialog_content = "……月白並無此意。",
  ui_story_5038_50381501_158_dialog_content = "什麼寶物不寶物的，只是為了渡海想的無奈法子。",
  ui_story_5038_50381501_159_dialog_content = "既然你不用倚仗它，我該高興才是。",
  ui_story_5038_50381501_160_dialog_content = "謝家主寬恕。",
  ui_story_5038_50381501_161_dialog_content = "這孩子，幹嘛這麼畢恭畢敬的。",
  ui_story_5038_50381501_162_dialog_content = "妳為林家開闢了自己的航路。說不準過段時間，被叫家主的就該是妳了。",
  ui_story_5038_50381501_163_dialog_content = "什麼？！",
  ui_story_5038_50381501_164_dialog_content = "家主，這話可誇得重了……",
  ui_story_5038_50381501_165_dialog_content = "這話不重，是妳應得的。",
  ui_story_5038_50381501_166_dialog_content = "希望妳別再介意自己的出身，那些都已經過去了。",
  ui_story_5038_50381501_167_dialog_content = "林可以成就木，木亦可成就林。",
  ui_story_5038_50381501_168_dialog_content = "是，月白記下了。",
  ui_story_5038_50381501_169_dialog_content = "好了好了，嘮叨太久了。",
  ui_story_5038_50381501_170_dialog_content = "街上寒冷，諸位快進屋吧，好酒好菜儘管享用。",
  ui_story_5038_50381501_171_dialog_content = "是啊別等著了，家主大人已經發話了。",
  ui_story_5038_50381501_172_dialog_content = "走吧走吧，有話進屋再聊！",
  ui_story_5038_50381501_173_dialog_content = "<color=#e8d9bb>嗒、嗒、嗒、嗒……</color>",
  ui_story_5038_50381501_174_dialog_content = "我、我也要進去嗎？",
  ui_story_5038_50381501_175_dialog_content = "當然。你有別處要去嗎？",
  ui_story_5038_50381501_176_dialog_content = "沒有，但是……",
  ui_story_5038_50381501_177_dialog_content = "我這個陌生人進林家蹭飯好像不太合適……",
  ui_story_5038_50381501_178_dialog_content = "怎麼是陌生人，你們幫助蜃風號度過了海上的劫難。",
  ui_story_5038_50381501_179_dialog_content = "你看，其他幾位已經衝進去搶飯吃了。",
  ui_story_5038_50381501_180_dialog_content = "好酒好菜，嘖嘖嘖，在下得快點。",
  ui_story_5038_50381501_181_dialog_content = "富貴人家的菜餚肯定了得！阿玖，我們去嚐嚐鮮！",
  ui_story_5038_50381501_182_dialog_content = "殿下，您小心門檻！",
  ui_story_5038_50381501_183_dialog_content = "哇，一溜煙全沒了……",
  ui_story_5038_50381501_184_dialog_content = "所以說不用擔心多餘的問題。",
  ui_story_5038_50381501_185_dialog_content = "在龍洲的這段時間裡住在林家就好。",
  ui_story_5038_50381501_186_dialog_content = "等蜃風號下次啟航，我再將你送回艾斯特拉。",
  ui_story_5038_50381501_187_dialog_content = "一直住在林家嗎？會不會太打擾了……",
  ui_story_5038_50381501_188_dialog_content = "龍洲的客套就別學去了。",
  ui_story_5038_50381501_189_dialog_content = "快進來吧，不然好菜要被搶光了。",
  ui_story_5038_50381501_190_dialog_content = "（龍洲，一個人聲鼎沸、熱鬧非凡的地方。）",
  ui_story_5038_50381501_191_dialog_content = "（在充斥著歡騰的聲音裡，完全不會感到孤獨。）",
  ui_story_5038_50381501_192_dialog_content = "<color=#e8d9bb>數日後</color>",
  ui_story_5038_50381501_193_dialog_content = "去蜃風號上？現在？",
  ui_story_5038_50381501_194_dialog_content = "對，月白正招呼大家一起去呢，就差你了。",
  ui_story_5038_50381501_195_dialog_content = "可在下不想出海啊，上船做什麼？",
  ui_story_5038_50381501_196_dialog_content = "放心吧，不是出海，不會把你綁架去艾斯特拉的。",
  ui_story_5038_50381501_197_dialog_content = "詳細的事情月白也沒跟我說，去了就知道了！",
  ui_story_5038_50381501_198_dialog_content = "得嘞，反正港口不遠，我跟你走一趟就是。",
  ui_story_5038_50381501_199_dialog_content = "這就對了！",
  ui_story_5038_50381501_200_dialog_content = "怎麼樣PlayerName，在龍洲待的這幾天，過得快活嗎？",
  ui_story_5038_50381501_201_dialog_content = "還是有些陌生，不太敢跟本地人接觸。",
  ui_story_5038_50381501_202_dialog_content = "而且我也不知道該去哪裡玩。",
  ui_story_5038_50381501_203_dialog_content = "哎呦喂，林家這待客做得太差了。",
  ui_story_5038_50381501_204_dialog_content = "過幾天你來找在下，在下帶你好好玩玩。",
  ui_story_5038_50381501_205_dialog_content = "哈哈哈，好啊！",
  ui_story_5038_50381501_206_dialog_content = "哦對了，其實還遇到件怪事。",
  ui_story_5038_50381501_207_dialog_content = "怪事？",
  ui_story_5038_50381501_208_dialog_content = "其實我帶了一封信來龍洲。",
  ui_story_5038_50381501_209_dialog_content = "可我這兩天找來找去，怎麼都找不到收信的地址。",
  ui_story_5038_50381501_210_dialog_content = "然後昨天，我收拾信件的時候不小心把水灑到上面。",
  ui_story_5038_50381501_211_dialog_content = "信上的蠟封被打濕，緊接著一堆<color=#FFB400>紅紙</color>竟然從信裡飛了出來。",
  ui_story_5038_50381501_212_dialog_content = "紅紙？！",
  ui_story_5038_50381501_213_dialog_content = "是的，好像是紅紙剪成的蝴蝶，聚在一起轉眼就飛走了。",
  ui_story_5038_50381501_214_dialog_content = "信封裡也沒有其他東西，這信不知道算送到了沒有。",
  ui_story_5038_50381501_215_dialog_content = "嘶，此事啊……",
  ui_story_5038_50381501_216_dialog_content = "李天閑，你對它有頭緒嗎？",
  ui_story_5038_50381501_217_dialog_content = "嘖嘖嘖，意味深長啊。",
  ui_story_5038_50381501_218_dialog_content = "這信你別管了，信主人的意願已經達成。",
  ui_story_5038_50381501_X218_dialog_content = "蝴蝶戀花，那些紅紙自會找到收信之人。",
  ui_story_5038_50381501_219_dialog_content = "此事翻篇了。",
  ui_story_5038_50381501_220_dialog_content = "欸，這樣就算送完了？",
  ui_story_5038_50381501_221_dialog_content = "那是自然。",
  ui_story_5038_50381501_X221_dialog_content = "真沒想到，它竟會飄洋過海而來。",
  ui_story_5038_50381501_X222_dialog_content = "<size=35>福禍相依啊，果然此番大難不死之福並非憑空修來。</size>",
  ui_story_5038_50381501_X223_dialog_content = "<size=35>接下來……</size>",
  ui_story_5038_50381501_X224_dialog_content = "什麼？福禍相依？",
  ui_story_5038_50381501_X225_dialog_content = "沒事沒事，在下自說自話呢。",
  ui_story_5038_50381501_222_dialog_content = "哎喲，碼頭就在前面了。",
  ui_story_5038_50381501_223_dialog_content = "PlayerName，我們緊趕兩步吧。",
  ui_story_5038_50381501_224_dialog_content = "船舷的木板釘好了嗎？",
  ui_story_5038_50381501_225_dialog_content = "釘好了！還剩些多餘的釘子有沒有人要？",
  ui_story_5038_50381501_226_dialog_content = "欸，最後兩個人過來了！",
  ui_story_5038_50381501_227_dialog_content = "來來來，等你們半天了。",
  ui_story_5038_50381501_228_dialog_content = "船長姐姐！人都到齊了！",
  ui_story_5038_50381501_229_dialog_content = "到齊了？",
  ui_story_5038_50381501_230_dialog_content = "好，我們準備開始吧。",
  ui_story_5038_50381501_231_dialog_content = "船長大人，這神神祕祕的是要做什麼啊？",
  ui_story_5038_50381501_232_dialog_content = "大家共同經歷了這麼多風風雨雨。",
  ui_story_5038_50381501_233_dialog_content = "接下來這一刻，也應該共同見證。",
  ui_story_5038_50381501_234_dialog_content = "哦？接下來這一刻？",
  ui_story_5038_50381501_235_dialog_content = "報告船長！",
  ui_story_5038_50381501_236_dialog_content = "修理工作已經完成，全船檢修完畢。",
  ui_story_5038_50381501_237_dialog_content = "蜃風號，恢復如初！",
  ui_story_5038_50381501_238_dialog_content = "<size=45>喔哦哦哦哦哦哦哦哦哦哦哦！！！</size>",
  ui_story_5038_50381501_239_dialog_content = "哇，蜃風號修好了？！",
  ui_story_5038_50381501_240_dialog_content = "是啊，終於修好了。",
  ui_story_5038_50381501_241_dialog_content = "到這一刻為止，蜃風號才算完成了它的旅程。",
  ui_story_5038_50381501_242_dialog_content = "於航行中不斷被破損，又不斷被修補，如今終於恢復原貌。",
  ui_story_5038_50381501_243_dialog_content = "此行總算功德圓滿了。",
  ui_story_5038_50381501_244_dialog_content = "真好！我已經快忘了完整的蜃風號是什麼樣了！",
  ui_story_5038_50381501_245_dialog_content = "這到處鋥光瓦亮的，連個補丁都沒有，真是不習慣。",
  ui_story_5038_50381501_246_dialog_content = "諸位待會再四處閒逛。",
  ui_story_5038_50381501_247_dialog_content = "還有件事情，需要大家共同完成。",
  ui_story_5038_50381501_248_dialog_content = "共同完成？什麼事情？",
  ui_story_5038_50381501_249_dialog_content = "許多工匠都有個習慣，在滿意的作品上刻下自己的名字。",
  ui_story_5038_50381501_250_dialog_content = "我們在航行中一次次修補蜃風，所有人都是它的工匠。",
  ui_story_5038_50381501_251_dialog_content = "希望這艘煥然一新的蜃風號，可以用大家的名字進行裝點。",
  ui_story_5038_50381501_252_dialog_content = "就刻在最有標誌性的「兔耳」上吧。",
  ui_story_5038_50381501_253_dialog_content = "哦，好有意思！",
  ui_story_5038_50381501_254_dialog_content = "這個好，這個好啊！",
  ui_story_5038_50381501_255_dialog_content = "我、我的字不好看，你們別嫌棄啊。",
  ui_story_5038_50381501_256_dialog_content = "既然大家都樂意，那就再好不過。",
  ui_story_5038_50381501_257_dialog_content = "那麼，就從我們異國他鄉的朋友開始吧。",
  ui_story_5038_50381501_258_dialog_content = "欸？我嗎？！",
  ui_story_5038_50381501_259_dialog_content = "嗯。龍洲的待客之道，處處以客人為先。",
  ui_story_5038_50381501_260_dialog_content = "這是刻刀，把你的名字刻在喜歡的位置吧。",
  ui_story_5038_50381501_261_dialog_content = "怪、怪不好意思的。",
  ui_story_5038_50381501_262_dialog_content = "而且我的名字大家也看不懂吧……",
  ui_story_5038_50381501_263_dialog_content = "看不懂多好啊，沒人會覺得你寫得醜！",
  ui_story_5038_50381501_264_dialog_content = "能先選位置也好啊，找個最顯眼的地方。",
  ui_story_5038_50381501_265_dialog_content = "就是，有什麼好怕的！",
  ui_story_5038_50381501_266_dialog_content = "哎呀大家……",
  ui_story_5038_50381501_267_dialog_content = "那我去刻了哦。",
  ui_story_5038_50381501_268_dialog_content = "嗯，快去吧。",
  ui_story_5038_50381501_269_dialog_content = "（攥緊刻刀，不要手抖。）",
  ui_story_5038_50381501_270_dialog_content = "（就選最邊上的位置吧。）",
  ui_story_5038_50381501_271option_content = "PlayerName",
  ui_story_5038_50381501_272_dialog_content = "對對，就這樣！刻得挺好的嘛！",
  ui_story_5038_50381501_273_dialog_content = "再刻大一點哦，不然要看不清了。",
  ui_story_5038_50381501_274_dialog_content = "（海水是無法留下痕跡的。）",
  ui_story_5038_50381501_275_dialog_content = "（平靜也好洶湧也好，怎樣都是暫時。）",
  ui_story_5038_50381501_276_dialog_content = "（但人們還是會想盡辦法在海上留下痕跡。）",
  ui_story_5038_50381501_277_dialog_content = "（就像我現在，正鐫刻著自己的名字。）",
  ui_story_5038_50381501_278_dialog_content = "（我知道它會陪著蜃風橫跨海洋，往返在兩片大陸之間。）",
  ui_story_5038_50381501_279_dialog_content = "（大海不會因此發生什麼變化。）",
  ui_story_5038_50381501_280_dialog_content = "（可是在某些人的認知中，大海與我的名字聯繫在了一起。）",
  ui_story_5038_50381501_281_dialog_content = "PlayerName",
  ui_story_5038_50381501_282_dialog_content = "未完待續"
}
return config
